window.POEMS = [
 {
  "id": "2021_02_14_7021",
  "title": "Радуюсь, или Яшкины мурашки",
  "genre": "философская лирика",
  "date": "14.02.2021 16:13",
  "url": "https://stihi.ru/2021/02/14/7021",
  "text": "Морозно-февральское утро,\nи солнце уж светит весной.\nВсё в мире устроено мудро.\nЯ радуюсь жизни земной.\n\nПускай всё, что есть, протекает,\nспокойной широкой рекой.\nВсе реки, куда-то впадая,\nнесут свои воды домой.\n\nОгромное общее Нечто\nустроило эту игру.\nЗачем? Коротать чтобы Вечность?\nРазвеять вселенскую грусть?\n\nНеведомо то, непонятно.\nНо чувствую. Смысл - он есть.\nМурашки - с макушки до пяток.\nКак солнце, я радуюсь. Весь.\n\n14.02.21\nЕлец"
 },
 {
  "id": "2021_02_06_2154",
  "title": "Лена from Vienna",
  "genre": "гражданская лирика",
  "date": "06.02.2021 08:54",
  "url": "https://stihi.ru/2021/02/06/2154",
  "text": "С ней встретились мы в Вене,\nбыл дальше Будапешт.\nИ звали её Лена,\nполна была надежд.\n\nО будущем мечтала\nи верила в себя.\nНе грезя пьедестала,\nжелала жить любя.\n\nЛюбя весь свет весёлый,\nлюбя животных, птиц,\nгулять горами, полем\nи миром без границ...\n\nЯ с нею соглашался\nи тоже мыслил так...\nНо тут Covid нам пальцем\nгрозит всем. Guten Tag!\n\nТеперь в кафе за кофе\nв Европу - не судьба.\nКвартира сейчас - офис,\nона же - паб и бар.\n\nУж год, как на планете\nграницы на замке,\nи странствовать по свету\nмогу я лишь в стихе.\n\nНо к счастью, есть Россия.\nНа благо есть Сибирь.\nИсточник, где брать силы,\nширокий русский мир.\n\nНаш континент могучий,\nпроекция всех стран.\n- Давай, разгоним тучи!\nЭй, солнце! Где ты там?\n\nНам есть испить где чаю.\nОтправимся в путь вновь!\nИ Ленку повстречаем\nв одном из городов.\n\n04/02/21\nЕлец"
 },
 {
  "id": "2021_01_30_2833",
  "title": "Вспоминая Японию",
  "genre": "пейзажная лирика",
  "date": "30.01.2021 09:45",
  "url": "https://stihi.ru/2021/01/30/2833",
  "text": "Ту ночь я жил у океана:\nв отеле, с чаем, в кимоно.\nПроснувшись утром очень рано,\nпошёл я к барышне одной.\n\nОна служила в местном храме.\nХотел я солнце встретить там:\nбосой ступая по татами,\nмолиться с ней её богам.\n\nНо храм закрыт был. Я стучал\nв его ворота вековые...\nХотя ворот мне не открыли,\nв то утро всё ж я не скучал.\n\nСпустился на берег. Уже,\nиз вод глубоких вырываясь,\nсверкало солнце. Стал \"ура!\" я\nкричать по-русски в кураже.\n\nИ, отшвырнув одежду, прыгнул\nв бодрящую волну стихий...\nСолёно-солнечные брызги -\nсейчас вот - буквы и стихи.\n\nНаполнены восточным бризом.\nПрогнали мой медвежий сон.\nЗима. Россия. А я вижу\nяпонский берег... Близок он.\n\nА барышня? Её не встретил.\nВ тот день был самолёт домой.\nНо я храню её браслетик\nи пентаграмму со стрелой.\n\n29/01/21\nЕлец\n\n(фото: март 2012 года, Япония)"
 },
 {
  "id": "2021_01_16_2870",
  "title": "Неделя на Невском",
  "genre": "городская лирика",
  "date": "16.01.2021 10:16",
  "url": "https://stihi.ru/2021/01/16/2870",
  "text": "Цокот лошадок по мостовой,\nкрики смеющихся чаек.\nЖил я на Невском, окошком во двор,\nдумал о жизни ночами.\n\nМожет, поэты из прежних эпох\nв тех же гостиных сидели.\nМуз уловляли они каждый вздох,\nгрезя их слушать в постели.\n\nЛибо другой, умудрённый судьбой\nстарец, здесь Богу молился\nо справедливости в жизни земной,\nо государстве, о близких...\n\nНевский проспект, протянувшись в веках, -\nкраха, величья свидетель.\nМного оставлено им в дураках,\nправда, иных заприметил.\n\nОн будто поезд из ярких домов.\nМы все - его пассажиры.\n- Только неделю я еду, как вновь\nпеть стал под невскую лиру!\n\nЧайки... Лошадки... Поэты в кафе...\nМузы... И Русь золотая...\nВсё оживало в моей голове.\nСпал я, во сне улыбаясь.\n\nПетербург\nянварь 2021"
 },
 {
  "id": "2019_06_12_5093",
  "title": "День России. Размышления",
  "genre": "гражданская лирика",
  "date": "12.06.2019 14:57",
  "url": "https://stihi.ru/2019/06/12/5093",
  "text": "Сегодня день России... Что значит это?\nВсего лишь день, чтоб думать нам о Ней?\nО Той, которая одна шестая света,\nлежит меж океанов и морей.\n\nВсего лишь день. И выбран день, который\nнаш материк - Россию - расколол.\nПревратности судьбы? Властей суд скорый?\nПредательство элит, иль просто зло?\n\nНе думаю... Точнее вижу смысл,\nчто этот день был выбран для России\nкак память нам, кем были мы.\nКак потеряли мощь, масштаб и силу.\n\nКак обретём... Да, обретём!\nИначе нет ни смысла, ни причины\nнам праздновать сей день, и в нём\nискать тех скрепов вечных величины.\n\nКак обретём? Открытостью, добром,\nпознанием себя, небес и мира.\nИ армией, и флотом, и царём...\nЦарём в делах... Но не кумиром!\n\nЦарь - в головах, и Бог - в сердцах.\nВ телах же - сила и здоровье.\nРоссия, с праздником! Живи в веках!\nИ радуй мир, защитница народов.\n\n12.06.19\nМосква"
 },
 {
  "id": "2019_04_09_3861",
  "title": "Город и его имена",
  "genre": "городская лирика",
  "date": "09.04.2019 11:41",
  "url": "https://stihi.ru/2019/04/09/3861",
  "text": "У меня ассоциативное мышление.\nПредставьте, каждый район Москвы\nсилами непонятного мне притяжения\nсвязуется с определёнными именами,\nвнутри моей головы.\n\nНапример, Китай-город - это Иванна,\nа Таганка - несомненно, Яна.\nПятницкая улица - это Оксана,\nа Кузнецкий мост - Иоланта.\n\nНе буду раскрывать все детали.\nХочу лишь, чтобы они и вы это знали.\n\nНе подумайте, прошу, ничего дурного.\nПросто так работает мой мозг.\nС кем-то виделся часто и много,\nа с кем-то - пару раз, и то не всерьёз.\n\nЕсть друзья, с которыми иду десятилетия:\nАнтон - Бауманская, Олег - Солнцево.\nКого-то занесло по глупости, ветрами,\nна дорожку мою, ночами бессонными.\n\nПросто перечислю - место и имя -\nне давая больше никаких оценок.\nДмитровская - Андрей, Фонвизинская - Нина.\nНескучный сад - много разных ленок.\n\nАртём - Переделкино. Белорусская - Аня.\nПарк Горького - Катя. Якиманка - Таня.\nПарк Культуры - Иван. Чертаново - опять Лена.\nОх, уж и много станций у метрополитена!\n\nВасилиса - Шаболовка. Дима - Варшавка.\nОдна мадам - как же её? - сидели на лавке...\nНастя - Никольская, Университет - Сашка,\nи десятки имён - на Патриарших.\n\nА ещё, конечно, есть имена другие:\nиз телевизора, истории, книжек.\nТакие же для Москвы неотъемлемо родные,\nсердцу моему кто-то далёк, кто-то ближе.\n\nСергей - Тверская, Владимир - Петровка.\nСаша - на месте Страстного монастыря.\nИосиф - Кунцево. В Кремле - он же и Вовка.\nНа Красной площади - вождь Октября.\n\nЛефортово - Пётр. В Коломенском - Грозный.\nЛубянка - Ягода, Ежов, Лаврентий.\nВасилий на площади - божий, босый.\nНа набережной - окровавленная голова Стеньки.\n\nБорис - в Новодевичьем. И Софья - тут же.\nХамовники - Лев. Замоскворечье - Иван.\nМарина - Арбат. Воробьёвы - Кутузов.\nНаполеон, что стену Кремля взрывал...\n...\n\nВсё! Хватит-хватит. Начал шутливо, лирично,\nа теперь вот - всерьёз понесло.\nЯ лишь про то, как в районах столичных\nмыслится мне... Широко и светло.\n\n07.04.19\nМосква"
 },
 {
  "id": "2019_03_25_6714",
  "title": "Юлий. Избранный богами",
  "genre": "сонеты, канцоны, рондо",
  "date": "25.03.2019 17:00",
  "url": "https://stihi.ru/2019/03/25/6714",
  "text": "В одном из городков увидев храм,\nчто посвящён владыке Геркулесу,\nзайти решил - зачем? - не знал и сам,\nиспанский тридцатитрёxлетний квестор.\n\nБыл храм безлюден. Но среди колонн\nего внимание привлёк бюст Александра -\nлик - утренней зарёю освещён.\nПриблизился тогда к скульптуре странник.\n\nКурился фимиам. Блаженство. Тишь.\nКак вдруг... Удар! Из пустоты.\nСознание пронзили чьи-то стрелы -\n\nвглубь сердца Цезаря смотрел кумир.\n- В моём он возрасте уже весь мир\nзавоевал. А я... Что сделал?!\n\n24.03.2019\nМосква\n\n______________________\n* идея сюжета стихотворения взята из книги Гая Свето;ния Транкви;лла \"Божественный Юлий\" (II век н. э.)"
 },
 {
  "id": "2019_03_18_4595",
  "title": "Не позвать ли гулять поэтессу...",
  "genre": "городская лирика",
  "date": "18.03.2019 13:06",
  "url": "https://stihi.ru/2019/03/18/4595",
  "text": "* * *\n\nНе позвать ли гулять поэтессу\nпо московским бульварам весной,\nнасладиться погоды прогрессом\nи из горлышка пить с ней вино!?\nТак, неспешно, вдоль улиц пустынных\nк Патриаршему пруду прийти.\nВспомнить тени поэтов старинных.\n- Их стихи почитаешь мне ты?\n\nМожет, лебедь по лунной дорожке\nв этот миг мимо нас проплывёт...\nИль мяукнув, за мартовской кошкой\nпробежит вдруг булгаковский кот...\nИли с неба к тебе на ладошку\nзолотая звезда упадёт...\n\nВ предвкушении этой уж встречи.\nКак щекочет мне мысли весна!\nСоглашайся на чудный тот вечер,\nчто Москва приготовила нам!\n\n17.03.19\nМосква"
 },
 {
  "id": "2019_02_18_4982",
  "title": "Редьярд Киплинг. Ромул и Рем",
  "genre": "поэтические переводы",
  "date": "18.02.2019 13:39",
  "url": "https://stihi.ru/2019/02/18/4982",
  "text": "Редьярд Киплинг. Ромул и Рем\n/ перевод: Яков Шахов /\n\nО многом ль думал он, волчонок,\nкогда замыслил Рим?\nВеличьем, славой ли потомков\nон был ли устремим?\n\nНа запад бредший мили, странник,\nсобрав из Тибра ил,\nвокруг своей стоянки странно\nон стены возводил.\n\nКогда же брат его глумленьем\nосыпал этот труд,\nон внял грядущего веленью,\nиз Рема сделав труп.\n\nУдар был быстр, как мысль быстра.\nУзрел деяний роль,\nкак превратить плоды затрат\nневерье может в ноль.\n\nНе будет явью тот дворец\nвсевластья, блеска, лжи -\nпевцов, поэтов, пап, царей -\nоставив Рему жизнь...\n\nК богам отправил брата и,\nотдав припадку цену,\nиз камней и комков земли\nпродолжил строить стену.\n\n(февраль 2019)\n\nRomulus and Remus\nby Rudyard Kipling\n\nOh, little did the Wolf-Child care—\nWhen first he planned his home,\nWhat City should arise and bear\nThe weight and state of Rome.\n\nA shiftless, westward-wandering tramp,\nChecked by the Tiber flood,\nHe reared a wall around his camp\nOf uninspired mud.\n\nBut when his brother leaped the Wall -\nAnd mocked its height and make,\nHe guessed the future of it all\nAnd slew him for its sake.\n\nSwift was the blow--swift as the thought\nWhich showed him in that hour\nHow unbelief may bring to naught\nThe early steps of Power.\n\nForeseeing Time's imperilled hopes\nOf Glory, Grace, and Love—\nAll singers, Caesars, artists, Popes—\nWould fail if Remus throve,\n\nHe sent his brother to the Gods,\nAnd, when the fit was o'er,\nWent on collecting turves and clods\nTo build the Wall once more!\n\n1907"
 },
 {
  "id": "2019_02_14_4530",
  "title": "Уильям Шекспир. Сонет 154",
  "genre": "поэтические переводы",
  "date": "14.02.2019 12:16",
  "url": "https://stihi.ru/2019/02/14/4530",
  "text": "Уильям Шекспир. Сонет 154\n/ перевод: Яков Шахов /\n\nОднажды бог любви прилёг поспать.\nОгонь, воспламеняющий сердца,\nон рядом положил - там, где кровать\nего стояла. Одна из нимф, устав\nблюдущая всю жизнь прожить в чести,\nогонь желания взяла-украла.\nСудьба свела в коварстве их пути,\nво сне обезоружив генерала.\n\nСвоей рукой тот факел погрузив\nв источник хладный, думала монашка\nлюбовь убить. Но нет на то на свете сил...\nВслед за Шекспиром повторит сегодня Яшка:\nОгонь любви согреет воду, но сам\nне гаснет ни в воде, ни в небесах.\n\n(январь 2019 г.)\n\nSonnet 154\nby William Shakespeare\n\nThe little Love-god lying once asleep,\nLaid by his side his heart-inflaming brand,\nWhilst many nymphs that vowed chaste life to keep,\nCame tripping by, but in her maiden hand,\nThe fairest votary took up that fire,\nWhich many legions of true hearts had warmed,\nAnd so the general of hot desire,\nWas sleeping by a virgin hand disarmed.\n\nThis brand she quenched in a cool well by,\nWhich from Love’s fire took heat perpetual,\nGrowing a bath and healthful remedy,\nFor men discased, but I my mistress’ thrall,\nCame there for cure and this by that I prove,\nLove’s fire heats water, water cools not love.\n\n(конец XVI века)"
 },
 {
  "id": "2019_02_04_5227",
  "title": "Древний Рим на верхней полке",
  "genre": "философская лирика",
  "date": "04.02.2019 13:53",
  "url": "https://stihi.ru/2019/02/04/5227",
  "text": "Опять в пути. Опять не сплю.\nГудит, вибрирует вагон.\nВ моей ладони телефон,\nего я светом озарён.\n\nМой мозг, как в панцире моллюск.\nНо волен он, могуч, обилен,\nкогда его весь с новой силой\nогнём сердечным окатило.\n\nИ рвутся мысли на экран.\nКак Карфаген у древних Канн\nна Рим, успехом обуян.\nА буквы - павшие в бою -\n\nложатся в строки - легионы...\nМелькают за окном перроны.\nНа верхней боковой в вагоне\nопять не сплю. Опять пою.\n\n02.02.19\nпоезд Москва - Елец"
 },
 {
  "id": "2019_01_09_4234",
  "title": "Мне однажды стал мал Петербург...",
  "genre": "гражданская лирика",
  "date": "09.01.2019 12:24",
  "url": "https://stihi.ru/2019/01/09/4234",
  "text": "* * *\n\nМне однажды стал мал Петербург,\nа теперь и Москвы маловато.\nРим, Париж хочу знать... И Стамбул.\nНе поймите превратно, ребята!\n\nНи зазнайство, ни гордость виной\nк заграничному столь интересу.\nЛюбознательность двигает мной\nощущать мировые процессы.\n\nГеографию с детства люблю.\nГлобус часто вращаю поныне.\nФлаги, гимны, названья валют,\nязыки и религии, книги.\n\nТо не значит, что меньше ценить\nстал Отечество наше родное.\nНет, отнюдь. Мой сердечный магнит\nрасширяет сознания поле.\n\nСреди общей палитры племён\nрусский дух ощутим и понятен.\nСколько славных страниц и имён!\nПомню всё, берегу, верю свято.\n\nЯ хочу для культуры Земли...\nБыть причастным, хотя бы отчасти.\nИз провинций и древних столиц\nэликсир создать общего счастья.\n\n05.01.19\nЕлец\n\nЯков Шахов"
 },
 {
  "id": "2018_12_19_263",
  "title": "Р. Фрост Остановившись в роще заснеженным вечером",
  "genre": "поэтические переводы",
  "date": "19.12.2018 00:31",
  "url": "https://stihi.ru/2018/12/19/263",
  "text": "Чья это роща?! Да-да, знаю.\nЕго дом там - в усадьбе, с краю.\nОстановлюсь: он не заметит.\nА снег собой всё заполняет.\n\nМой конь не разумеет это:\nснежинок танец, лёгкий ветер,\nдеревья, лес, замёрзший пруд...\nНа свете самый тёмный вечер!\n\n- Друг мой, что мы забыли тут?\nВоды б нам, сена да уют...\nНарушил колокольчик тишь,\nи мысли больше не поют.\n\nЧто дальше ждёт нас на пути?!\nКак много нужно воплотить.\nИ столько миль ещё пройти.\nИ столько миль ещё пройти.\n\n2018\nЯков Шахов\n(перевод с английского стихотворения Роберта Фроста)\n\nStopping By Woods on a Snowy Evening\n\nWhose woods these are I think I know.\nHis house is in the village though;\nHe will not see me stopping here\nTo watch his woods fill up with snow.\n\nMy little horse must think it queer\nTo stop without a farmhouse near\nBetween the woods and frozen lake\nThe darkest evening of the year.\n\nHe gives his harness bells a shake\nTo ask if there is some mistake.\nThe only other sound’s the sweep\nOf easy wind and downy flake.\n\nThe woods are lovely, dark and deep.\nBut I have promises to keep,\nAnd miles to go before I sleep,\nAnd miles to go before I sleep.\n\n1922\nRobert Frost"
 },
 {
  "id": "2018_09_23_3666",
  "title": "Карадаг",
  "genre": "философская лирика",
  "date": "23.09.2018 11:36",
  "url": "https://stihi.ru/2018/09/23/3666",
  "text": "Когда над Карадагом Вега,\nкогда о скалы бьёт волна,\nохватывает душу нега,\nплывут в сознанье письмена.\n\nСредь этих огненных историй\nя вижу дней минувших ход.\nОгнём охваченную Трою.\nВ Стамбул из Крыма пароход.\n\nРуно златое, что в Колхиде\nгероям взять не удалось.\nИ немцев орды очи видят.\nНарод советский в землю врос.\n\nЭпохи, нации и страны\nсменялись здесь под пенье волн.\nНезыблем лишь покой вулкана\nда хладный взор далёких солнц.\n\nсентябрь 2018\nКоктебель, Ялта"
 },
 {
  "id": "2018_09_08_5691",
  "title": "Поехать в Коктебель, потрогать море...",
  "genre": "любовная лирика",
  "date": "08.09.2018 16:22",
  "url": "https://stihi.ru/2018/09/08/5691",
  "text": "Поехать в Коктебель, потрогать море,\nупасть в стихи и думать ни о чём.\n- Хотя б три дня побудь, о Крым, врачом\nдуше моей, так страждущей простора.\n\n- И ты моя, о милая Москва,\nвручи меня в заботливые руки.\nВернувшись, я поведаю те звуки,\nиз бриза уловлённые слова.\n\nОсенний пляж и сочные плоды,\nвкушать готов с улыбкой и восторгом.\nИ, может, ждёшь меня на набережной ты,\nиз будущего присланная Богом.\n\nПоехать в Коктебель, потрогать море...\nЯ, кажется, решил, пока писал стихи.\n\n07.09.18\nМосква"
 },
 {
  "id": "2018_05_24_6404",
  "title": "Под пледом",
  "genre": "любовная лирика",
  "date": "24.05.2018 16:56",
  "url": "https://stihi.ru/2018/05/24/6404",
  "text": "Струятся в граните каналы,\nнад ними упруги мосты.\nДруг друга когда-то не знали,\nно схожие снились мечты.\n\nУкрывшись под пледом, внимаем\nмелькающим мимо домам,\nромантике чудного мая.\nуже почти белым ночам\n\nКораблик волну рассекает,\nна палубе ветры морей\nДуша, словно чайка морская,\nи выше летит, и смелей.\n\n23.05.18\nМосква"
 },
 {
  "id": "2018_04_17_6582",
  "title": "Гроза в апреле",
  "genre": "пейзажная лирика",
  "date": "17.04.2018 16:10",
  "url": "https://stihi.ru/2018/04/17/6582",
  "text": "Гроза в середине апреля -\nне припомню такого в Москве.\nКолесница Перуна гремела,\nпролетая за улицей сквер.\n\nЭлектричество молний озоном\nнаполняло ночную идиль.\nЯ проснулся. Что снилось - не помню -\nот дождя чуть оконце прикрыл.\n\nНе спалось. Что-то новое пело.\nНаконец-то настало тепло.\nОчищалось, сверкало, гремело\nи стучало водой о стекло.\n\n17.04.18\nМосква"
 },
 {
  "id": "2018_03_21_7901",
  "title": "Картошка в мундире",
  "genre": "любовная лирика",
  "date": "21.03.2018 17:05",
  "url": "https://stihi.ru/2018/03/21/7901",
  "text": "Картошка в мундире варится,\nа за окошком весна.\nГрустит у окошка красавица,\nночь провела без сна.\n\nВчера повстречался ей суженный,\nкоторого долго ждала.\nТакой очень нужен мужем ей:\nласковая скала.\n\nКак же пронзающе чувственны\nгорят серебром глаза.\nБрови и волосы - русые -\nих позабыть нельзя.\n\nТолько б и он почувствовал,\nкак и она, судьбу -\nв будущее бодро идущую,\nобщую их тропу.\n\nТогда уж, конечно, сложится\nсложно запутанный пазл.\nBерим, надеемся, Боженька,\nда не оставишь Ты нас.\n\n04.03.18\nМосква"
 },
 {
  "id": "2018_02_26_5052",
  "title": "Дубай",
  "genre": "городская лирика",
  "date": "26.02.2018 12:41",
  "url": "https://stihi.ru/2018/02/26/5052",
  "text": "В Дубае дубы не растут.\nЛишь пальмы да небоскрёбы.\nТуристам оазис и яхтам приют.\nФинансовый климат особый.\n\nВ Дубае добыты из нефти цветы,\nотели и банки, и моллы...\nПронзителен голос в мечетях муллы:\nо, помните Божую волю.\n\nИллюзия, тлен и миражи\nпусть сердце твоё не обманут.\nВсевышний лишь знает, как счастливо жить.\nПочувствуйте Божие планы!\n\nЗахочет и явит в пустыне мечту.\nЗахочет, всё снова разрушит.\nЗахочет, в Дубае дубы зацветут\nиль море поглотит всю сушу.\n\nфевраль 2018\nДубай, Шарджа"
 },
 {
  "id": "2018_02_05_3360",
  "title": "Благость",
  "genre": "религиозная лирика",
  "date": "05.02.2018 10:24",
  "url": "https://stihi.ru/2018/02/05/3360",
  "text": "Точёный стан, перехваченный поясом,\nволосы убраны, платье до пят.\nВзгляд на иконе сосредоточенный,\nмедовые свечи в песке горят.\n\nМысли от сердца. О чём? О Родине\nи о любимом, который вдали.\n- Благословенные, милые, родные,\nбудьте здоровы, родители!\n\nЯсное небо над белым храмом:\nзвёздная россыпь, лимоном луна.\nИ до весны спит, укрывшись снегами,\nта, что взрастила всех нас.\n\n04.02.18\nМосква"
 },
 {
  "id": "2018_01_22_6075",
  "title": "Внутренние битвы",
  "genre": "религиозная лирика",
  "date": "22.01.2018 13:52",
  "url": "https://stihi.ru/2018/01/22/6075",
  "text": "Правда вечная,\nизначальная\nпраздным вечером\nизмочалена,\nсловно блудница\nпьяным скопищем.\nУж не сбудется\nто хорошее,\nбеспримерное\nи манящее,\nво что верует\nнастоящее.\nВера - ветрена,\nбаба слабая,\nне заметила,\nкак пропала ты.\n\nНет, не правда то,\nне пропала ты.\nВсё лукавые\nсилы жалкие,\nжаждут этого,\nхотят справиться.\nСилы светлые\nим не нравятся...\nЧто мир полон весь\nправдой, верою.\nБесов полчища\nлюциферовы\nодолеются\nратью видною,\nшлемоблещущих\nславных витязей.\n\nДа погонят псов\nдо окраины,\nДа надломятся\nветви Каина...\nВера с правдою\nне потерены:\nживут праведно\nв светлом тереме.\nСердце каждое\nими полнится,\nв жизни нашей всё\nславно сложится.\nБури утренним\nштилем сменятся.\nСолнцем внутренним\nжизнь согрета вся.\n\n20-21.01.18\nМосква"
 },
 {
  "id": "2018_01_15_7790",
  "title": "Нева. Начало зимы",
  "genre": "городская лирика",
  "date": "15.01.2018 16:52",
  "url": "https://stihi.ru/2018/01/15/7790",
  "text": "Неву всю покрывает льдами,\nкак поцелуями, мороз.\nИ город встречами, стихами,\nкак прежде, мил, приветлив, прост.\n\n13/01/18\nПетербург"
 },
 {
  "id": "2017_12_31_8323",
  "title": "С улыбкой на устах",
  "genre": "религиозная лирика",
  "date": "31.12.2017 19:17",
  "url": "https://stihi.ru/2017/12/31/8323",
  "text": "Рождаться, умирать -\nс улыбкой на устах.\nПрожив жизнь, не устать,\nлететь к другим мирам.\n\nВлюбиться - чтоб на век -\nи с ней - путь до конца.\nЧтоб мысли в голове -\nдостойные Отца.\n\n29/12/17\nМосква"
 },
 {
  "id": "2017_12_27_3418",
  "title": "Огурцы",
  "genre": "гражданская лирика",
  "date": "27.12.2017 10:20",
  "url": "https://stihi.ru/2017/12/27/3418",
  "text": "Босиком по нагретой земле,\nрукавом отмахнувшая чёлку,\nогурцы, что травы зеленей,\nполивает из лейки девчонка.\n\nОчень прост её дачный наряд.\nПлатье беж, загорелое тело\nи счастливый, смеющийся взгляд...\nСтаей птиц сколько лет пролетело?!\n\nЗапах свежий, чуть с горечью вкус\nмне минувшее время напомнят.\nЗа столом ресторана \"La Russe\"\nем салат я, усталый паломник.\n\nМожет, это и вовсе не я\nтам сижу, вспоминаю о прежнем.\nМожет, чья-то чужая мечта\nпроросла, словно звонкий подснежник.\n\nСколько русских во все времена\nтосковало о Родине вечной.\nСколько их, живших вне, живших на,\nза неё в храмах ставивших свечи.\n\nСквозь столетие, видно, ко мне,\nчей-то шёпот далёкий донёсся\nо сияющей русской весне,\nурожае и ладане сосен.\n\n27.12.17\nМосква"
 },
 {
  "id": "2017_12_12_7007",
  "title": "Неслучайны",
  "genre": "философская лирика",
  "date": "12.12.2017 18:00",
  "url": "https://stihi.ru/2017/12/12/7007",
  "text": "Человечество.\nМы человечество.\nЗдесь мы недавно.\nПланета, отечество -\nнаша пути...\nНам,\nмонадам, доверены\nразные ветви единого дерева.\nВетры судьбы\nветви эти качают,\nСолнце Вселенной их греет лучами.\n\nНет, в мироздании всё неслучайно!\n\nОт инфузорий до звёздных динамик...\nОт алых зорь с их лесными ручьями\nдо городов, озаряемых снами.\n\nНу и конечно же, мы\nнеслучайны.\n\nдекабрь 2017\nМосква"
 },
 {
  "id": "2017_12_03_5351",
  "title": "Сердце",
  "genre": "мистика и эзотерика",
  "date": "03.12.2017 13:06",
  "url": "https://stihi.ru/2017/12/03/5351",
  "text": "Мы смотрим в сердце,\nкак в шар магический:\nусловность меркнет\nот электричества.\n\nС нарядно-льстивых\nпокровы сорваны.\nНе так красивы\nнагие образы.\n\nЗдесь всё по правде,\nвсё органичнее.\nВ масштабе давней\nсвятой этичности.\n\nКак боги сверху,\nна Землю с вечности...\nИх щедрость - сердце -\nдар человечеству.\n\n30.11.2017\nМосква"
 },
 {
  "id": "2017_11_30_3112",
  "title": "У вечного огня",
  "genre": "гражданская лирика",
  "date": "30.11.2017 09:41",
  "url": "https://stihi.ru/2017/11/30/3112",
  "text": "На площади Победы, у вечного огня,\nстояли мы - четыре - свои главы склоня.\n\nДва парня, две девчонки - вокруг, по сторонам.\nЧетыре части света дышали в спины нам.\n\nМы спорили о разном, о чём-то невсерьёз.\nА здесь в момент притихли. Повис внутри вопрос.\n\nАх, сколько тут когда-то таких же, как и мы,\nклялись беречь пространство родной своей страны.\n\nНа битвы уходили, трудились ли в тылу.\nУбиты? Победили? Огонь - их клятвы луч.\n\nА мы? Способны или... Стране своей служить?\nДостойно предков наших, достойно жизнь прожить?\n\nСтояли и молчали, единые в мечте.\nИ лица озарялись в вечерней темноте.\n\n29.11.17\nМосква"
 },
 {
  "id": "2017_11_22_6643",
  "title": "Двери души",
  "genre": "философская лирика",
  "date": "22.11.2017 15:58",
  "url": "https://stihi.ru/2017/11/22/6643",
  "text": "Я к Вам лицом, а Вы затылком...\nЯ к Вам с душой и речью пылкой...\n\nА Вы: \"Поэтам я не верю,\nстрастями схожи с диким зверем\nони - терзающие души -\nсвоё лишь эго могут слушать.\"\n\nУшла. Захлопнула все двери.\nЧто здесь кичиться, лицемерить?\nВедь барышня права отчасти...\n\nНо страсть стиха - не в нашей власти.\nНе может сёрфер океаном...\nКак и песчинка ураганом...\n\nСтихией той повеливать.\nСие бы барышням понять.\n\nПоэзия - поток обильный,\nнесущий океаны силы.\nЭнергия любви живая...\nЧтоб люди жили, сознавая\nсебя и место в Мирозданье.\nНе гасла чтоб звезда познанья...\n\nЯ то шептал, кричал... И верил!\nИ Вы свои закрыли двери.\n\n21.11.17\nМосква"
 },
 {
  "id": "2017_11_03_4224",
  "title": "Вершина снежная",
  "genre": "любовная лирика",
  "date": "03.11.2017 11:26",
  "url": "https://stihi.ru/2017/11/03/4224",
  "text": "Ты, как горная вершина,\nвся алмазна в блеске солнца,\nв небо взор свой устремляешь,\nчистотой снегов маня.\n\nПутник я. Пришёл с равнины,\nвырвавшись из жизни сонной.\nФлагом мой костёр пылает\nот сердечного огня.\n\nУ подножия, в долине,\nлагерь я поставил скромный.\nТалой влагой утоляю\nжажду уж четыре дня.\n\nСтрасть моя ж неутолима,\nалчу этих линий томных.\nМыслями повелеваешь,\nиссушила ты меня.\n\nТолько гордая вершина,\nвсех моих зерно бессонниц,\nхолодна, как неживая.\nПокорил её не я.\n\n- Да куда же вам, мужчинам,\nсилами тягаться с солнцем.\nЛишь оно меня ласкает,\nтопит все мои снега.\n\nЧто ж, пойду дорогой длинной,\nтем уроком умудрённый.\nТа иллюзия нагая\nбудет сердцу дорога.\n\n01.11.17\nМосква"
 },
 {
  "id": "2017_10_29_6934",
  "title": "Карма или судьба",
  "genre": "философская лирика",
  "date": "29.10.2017 15:20",
  "url": "https://stihi.ru/2017/10/29/6934",
  "text": "Если это не судьба,\nа всего лишь карма,\nпозвоню в небесный банк,\nвсе долги отдам я.\n\nЕсли это не судьба,\nкротко и смиренно\nбуду изучать себя,\nвзвешивать решенья.\n\nЕсли это просто так,\nсбой какой, ошибка,\nсмысла нет мне знак искать.\nЯ не парюсь шибко.\n\nЕсли это всё ж судьба,\nберег мой желанный,\nпротруби скорей, труба!\nО любви, о главной.\n\nЕсли это, если то...\nВот сижу, гадаю.\nИ стихами сладкий торт\nжизни украшаю.\n\n28.10.17\nМосква"
 },
 {
  "id": "2017_10_26_2906",
  "title": "Взрывоопасно",
  "genre": "любовная лирика",
  "date": "26.10.2017 09:27",
  "url": "https://stihi.ru/2017/10/26/2906",
  "text": "Эти груди, размера \"4\",\nзадурманили мысли мои.\nБосоного по тёплой квартире\nносят их, чуть пижамкой покрыв.\n\nБезрассудно! Ох, безрассудно!\nЭто ж ядра с тротилом внутри!\nПо сознанью. как палубой судна,\nнеминуемый катится взрыв.\n\nПрыгать в море (без шлюпок и круга)?\nПлыть до берега? Падать до дна?\nНет! Картечью по грудям подруги\nпоцелуями полных огня!!!\n\n25.10.17\nМосква"
 },
 {
  "id": "2017_10_24_3350",
  "title": "На Таганке",
  "genre": "городская лирика",
  "date": "24.10.2017 10:05",
  "url": "https://stihi.ru/2017/10/24/3350",
  "text": "На Таганке - Матрёна,\nна Таганке - Высоцкий.\nТам разрушены стены старинной тюрьмы.\nТам когда-то татары\nмастерили высокие\nдля обедов походных свои таганы.\nЗажигает там окна\nнад рекою - высотка -\nсимвол сталинских планов ремонта страны.\nТам под ручку влюблённые\nмимо Яузы сонной...\nТам бывает, что в мае гуляем и мы.\n\n23.11.17\nМосква"
 },
 {
  "id": "2017_09_27_4853",
  "title": "Редко мёртвые к нам приходят...",
  "genre": "философская лирика",
  "date": "27.09.2017 12:50",
  "url": "https://stihi.ru/2017/09/27/4853",
  "text": "Редко\nмёртвые к нам приходят.\nРедко\nи то - украдкой во снах.\nБудто бы\nива касается глади водной\nсвоею веткой,\nмёртвые\nнавещают нас.\n\nПриходят из мира ли высшего,\nболее чистого?\nКак вестники, помощники\nнам.\nИли, из бездны адовой\nвырвавшись,\nземного воздуха глотнуть,\nчтобы опять упасть?\n\nИли, скажет материалист,\nих нет,\nи мы о них забыли.\nА вспоминаем редко,\nкогда самим нам тяжело.\nУпрёк себе,\nчто мы - ещё живые -\nпогрязли в мелочности дел\nи слов.\n\nРедко\nмёртвые к нам приходят...\nВеткой упругой\nкруги по воде...\nИвы, не плачьте!\nМы здесь,\nмы живы.\nА они все\nгде?\n\nсентябрь 2017\nМосква"
 },
 {
  "id": "2017_09_19_3875",
  "title": "Любовная война",
  "genre": "любовная лирика",
  "date": "19.09.2017 11:17",
  "url": "https://stihi.ru/2017/09/19/3875",
  "text": "Моё тело объявило войну твоему.\nСквозь границы проникну, в пределы войду.\nСкажешь, \"вражье вторженье\"? Скажешь даже, \"блицкриг\"?\n\"Оккупация наций! Под пятой материк!\"\nЭто так. Покорись... Хотя нет. Восставай!\nПримиряясь потом, выпьем с мёдом мы чай.\nА пока - штыковая! Сраженье. Вражда.\nТебе нравится это?\nСлышу робкое \"да\".\n\n17.09.17\nМосква"
 },
 {
  "id": "2017_09_15_3783",
  "title": "Бабье лето",
  "genre": "пейзажная лирика",
  "date": "15.09.2017 11:13",
  "url": "https://stihi.ru/2017/09/15/3783",
  "text": "Сушатся листья под ласковым солнцем,\nпадают и под ногами шуршат.\nНа саксофоне из золота соло\nосень мелодию стала играть.\n\nЯрко-блестящие краски в начале\nи мокро-бурая серость в конце.\nБлюз о влюблённости и о печалях,\nпуть от улыбок до слёз на лице.\n\nРыжеволосая, выйдя на сцену\nи провожая подружку свою,\nлету вступленьем почти \tнеизменно\nвторит, даруя народам жару.\n\nТак и играют они, те девчонки.\nВечно четыре, друг другу вослед.\nКто-то на бубне\t, а кто-то чуть тоньше\nзвуками\tнежных серебряных флейт.\n\n14.09.17\nМосква"
 },
 {
  "id": "2017_09_12_7308",
  "title": "Ежели",
  "genre": "без рубрики",
  "date": "12.09.2017 17:04",
  "url": "https://stihi.ru/2017/09/12/7308",
  "text": "Ежели желаете, полетели вместе\nв край любой на свете или в рай небесный.\n\nМожно и во времени нам переместиться.\nНапример, античность ежели вам снится,\n\nили, вы грядущее вдруг узреть хотите -\nэто не проблема - будете там зритель.\n\nЧто за чудо-транспорт сей? Времени машина,\nтеле- ли портатор судеб властелина?\n\nМожет, так оно и есть... Ежели хотите.\nСтихотворные плету путешествий нити.\n\nНити-нити, вы плетитесь, нити Ариадны!\nИ ведите, нас ведите в край с любым названьем.\n\nЕжели названия место не имеет,\nимя мы придумаем - флаг уже с ним реет.\n\n05.09.17\nМосква"
 },
 {
  "id": "2017_08_23_4164",
  "title": "Поэзия и поезда",
  "genre": "философская лирика",
  "date": "23.08.2017 11:37",
  "url": "https://stihi.ru/2017/08/23/4164",
  "text": "Поэзия и поезда\nпорождены одним началом.\nПоэзия и поезда\nотправляются с одних вокзалов.\nУвозят людей или мысли уносят,\nвесну - в лето,\nа лето - в осень.\nОчень\nпочему ночью хочется ехать?\nКуда-то, куда нету билетов.\nМожно\nосторожно зайцем пробраться.\nНа третьей полке притаиться,\nбояться,\nчтобы проводник не заметил\nтебя безбилетного\nрвущегося в лето\nнебесное, раньше срока.\nУпрёка ни единого\nтебе не скажет.\nА ты боишься,\nа ехать жаждешь.\nДали...\nВсе ли печали утолят?\nЧто там?\nКто ждёт нас?\nКуда мы?\nВ рай? Или, всё-таки...\nАд?\n\n19.08.17\nМосква"
 },
 {
  "id": "2017_08_17_3089",
  "title": "Асильда",
  "genre": "любовная лирика",
  "date": "17.08.2017 10:03",
  "url": "https://stihi.ru/2017/08/17/3089",
  "text": "*** памяти моей кошки ***\n\nКак в детстве - своём и моём -\nты прыгнула с пола... На небо.\nЧуть выше - обычно на мебель -\nа так... Как всегда, с озорством.\n\nКартинки из жизни кручу:\nсемнадцать мы лет были вместе.\nСтроптива, игрива, прелестна.\nТы слышишь? Стихами кричу.\n\nПусть бог ваш кошачий в раю\nтебе светлый терем построит.\nСудьбе покоримся достойно.\nТвой образ в душе сохраню.\n\nУвидимся ли мы ещё,\nв пространстве рождаясь межзвёздном?\nВселенная - вечна. Возможно\nв ней всякое, если не всё.\n\nПока ещё видела мир,\nуспел я... И радуюсь, ибо\nты слышала, как говорил,\nпрощаясь: \"Асильда! Спасибо!\"\n\n17.08.17\nМосква"
 },
 {
  "id": "2017_08_14_4203",
  "title": "Стихи или грехи",
  "genre": "философская лирика",
  "date": "14.08.2017 12:32",
  "url": "https://stihi.ru/2017/08/14/4203",
  "text": "Стихи мои,\nво грехах рождённые;\nгрехи мои,\nв стихах отражённые -\nкак два зеркала,\nбесконечность являют?\nМир отражений\nони выражают?\nИли трамплин то,\nнад бытом поднявшись,\nчто-то узреть,\nни черта не понявши.\nТак или Иначе,\nто или это -\nто вопрощаю,\nто сею ответы.\nСтих или грех\nвновь меня устремляет?\nБлаго всё это.\nЯ знаю, не зная.\n\n05.08.17\nМосква"
 },
 {
  "id": "2017_07_28_3134",
  "title": "Наполняйтесь кратеры сердец...",
  "genre": "религиозная лирика",
  "date": "28.07.2017 10:21",
  "url": "https://stihi.ru/2017/07/28/3134",
  "text": "Наполняйтесь кратеры сердец\nдо краёв благодатью заветной.\nШар земной погрузить хочу весь\nв чаши нашей любви межпланетной.\n\nВ тишине, неспеша пусть Земля\nтам омоется, словно в джакузи.\nПод струями добра и тепла,\nочищаясь, блаженство пусть вкусит.\n\nОчень многое нужно бы смыть\nнам своею любовью сердечной.\nА иначе... Библейская мысль:\nсмоют нас всех потопом предвечным.\n\n27.07.17\nМосква"
 },
 {
  "id": "2017_07_21_3966",
  "title": "Когда выхожу я на балкон...",
  "genre": "шуточные стихи",
  "date": "21.07.2017 11:24",
  "url": "https://stihi.ru/2017/07/21/3966",
  "text": "Когда выхожу я на балкон -\nкофе с лимоном пью или сочную грушу кушаю -\nморе людей я вижу внизу -\nликующих, готовых речь мою слушать.\n\nА я такой - в тоге античной или в тунике -\nжестом трибуна прошу их гул прекратить,\n(как научили нас древние книги)\nдабы свет мудрости им в души пролить.\n\nИ вот, десницу свою дланью вперёд подняв,\nподождав пока всё стихнет,\nя начинаю очень мощно вещать.\nИ слушают, слушают люди пронзающий стих мой.\n\nА на самом деле... Грушу доев\nили (что там у нас?) кофе с лимоном выпив,\nудаляюсь просто в квартиру свою:\nостатки груши выкинуть / чашку помыть...\n\nДа, ни Эллада, ни Троя, ни Рим:\nвсего лишь спальный район Москвы.\nНо приятно так, знаете, фантазией ум покорив,\nвечером летним на балкон свой выйти.\n\n16.07.17\nМосква"
 },
 {
  "id": "2017_07_17_4132",
  "title": "Страждущие и любимые",
  "genre": "верлибр",
  "date": "17.07.2017 12:05",
  "url": "https://stihi.ru/2017/07/17/4132",
  "text": "Сколько тел человеческих на полях сражений землю удобрило!\nСколько душ людских ввысь поднялось,\nсколько вниз кануло!\n\nДоколи мы будем в колесе отражений бегать?\nДоколи Бога в ближних не замечать?\n\nМы - те павшие,\nи мы - те воспарившие.\nМы - страждующие,\nи мы - Богом любимые.\n\nЛюди - мы.\nЧеловеками стать дерзающие.\n\n17.07.17\nМосква"
 },
 {
  "id": "2017_07_14_2712",
  "title": "Аменхотеп",
  "genre": "религиозная лирика",
  "date": "14.07.2017 09:32",
  "url": "https://stihi.ru/2017/07/14/2712",
  "text": "Египет гибнет:\nНил забыл разлиться.\nМолитесь!\nМолитесь!\nМолитесь все - жрецы и жрицы -\nу фараоновых могил,\nчтоб Бог верховный нас простил.\n\nАменхотеп разгневал Бога\nубийством льва.\nЕго дорога\nв долину Нила привела\nко храму благостному Ра.\nИ пал он ниц.\nОн!\nСын Его!\nИ сам который бог!\nУ ног распластан каменного лика.\nМолитву за народ Египта\nрекли прекрасные уста:\n\n- Отец! Создатель всех и вся.\nНарушил Твой закон премудрый!\nПрости! Я не молю о чуде -\nобрушь свой гнев лишь на меня.\nНарод - младенец и дитя.\nЖрецы и я - одни в ответе.\nПред взором истины и света\nтерзаюсь я. Терзай меня!\n\nТри долгих дня никто не смел\nсолнцеподобного тревожить.\nА Нил?\nРазлился, как и должно.\nАменхотеп стал телом бел.\nДушой ушёл к богам в чертог.\nТеперь по праву с равными воссядет.\nОн бог.\n\nДругих таков ли ждёт итог?\n\nиюль 2017"
 },
 {
  "id": "2017_07_09_5700",
  "title": "Ротонда",
  "genre": "любовная лирика",
  "date": "09.07.2017 15:08",
  "url": "https://stihi.ru/2017/07/09/5700",
  "text": "I.\n- Давай назначим нашу встречу\nна восемь вечера в саду.\nЧто скажешь мне? - Да-да, приду!\n- У входа в сад тогда я встречу,\nв ротонду к пруду проведу.\n\nII.\nИнкогнито, в плаще, пришла,\nсквозь город пыльный пробираясь,\nпод видом странника скрывая\nгетеры стан и пламя глаз.\nОн ждал, как страж в воротах рая.\n\nИ было райское вполне\nвсё то, что здесь их ожидало:\nскульптуры, блеск луны в бокале,\nцветы хмельно благоухали,\nи лебедь плавал в тишине...\n\nIII.\nКогда вино зари багрянцем\nс востока небо залило,\nкогда всё в мире рассвело,\nпришла пора двоим расстаться.\nИз комнат выйдя на балкон,\n\nон наблюдал, как плащ накинув,\nдорожкой сада путник шёл...\nИ думал, впишет ли ещё\nсудьба её в его картину?\n- Пожалуй, было б хорошо.\n\nиюнь-июль 2017\nМосква"
 },
 {
  "id": "2017_06_26_3424",
  "title": "Орангутанг",
  "genre": "философская лирика",
  "date": "26.06.2017 11:04",
  "url": "https://stihi.ru/2017/06/26/3424",
  "text": "Орангутанг,\nори,\nори!\nС начала ночи до зари!\nО рваных ранах чувств твоих\nори,\nори,\nори!\n\nО самке ли? Той, что дарить\nтебе умела тело.\nО джунглях ли? Что покорить\nне смог, хоть дрался смело.\n\nК другому, может быть, ушла -\nфортуна иль подруга?\nЗлой человек, зажав приклад,\nубил обеих грубо?\n\nДа, если был бы ты поэт\nи выражать умел\nвсё то, о чём и слов-то нет,\nнеясное в уме,\n\nтогда, конечно бы, ты смог,\nбогам послав свой ор,\nвсё получить: и мысль, и слог,\nдля творчества простор.\n\nПоэты - тоже, как и ты,\nвлагают в песню крик...\nОрангутанг - тот, что внутри!\nОри!\nОри!\nОри!\n\n21.06.17\nМосква"
 },
 {
  "id": "2017_06_22_4325",
  "title": "Поэт роет",
  "genre": "философская лирика",
  "date": "22.06.2017 12:14",
  "url": "https://stihi.ru/2017/06/22/4325",
  "text": "Поэт -\nон роет жизнь, как крот:\nнаощупь ищет выход в вечность.\nПарит орлом и соловьём поёт,\nпрекрасно сознавая - \"жизнь конечна\".\n\nА бесконечно что?\nНад нами божество?\nПод нами хаос?\nМы песчинки в мире?\n\nВопросов много. И поэт поёт,\nи роет, и летает, опаляя\nбездной крылья.\n\n17.06.17\nМосква"
 },
 {
  "id": "2017_06_21_3083",
  "title": "Как правильно жениться",
  "genre": "гражданская лирика",
  "date": "21.06.2017 09:54",
  "url": "https://stihi.ru/2017/06/21/3083",
  "text": "Задали тему для экспромта:\n\"Как правильно жениться\" - Вот.\n- Жюри, прости, что горизонта\nу мысли нет. Масштаб не тот.\n\nБанально, кисло, не в формате...\nВозможно так, но я скажу.\nИдёт изящна, в белом платье,\nкрасавица. А рядом муж.\n\nУж поженились. Всё, как надо.\nДовольны, счастливы вдвоём.\nВ просторной зале и нарядной\nсидят за праздничным столом.\n\nКругом друзья, родные - \"горько\"\nкричат хмельно со всех сторон.\nНо сладко им... Заметим только:\nкак долго простоит их \"дом\"?\n\nЧто ж, здесь отвечу очень просто.\nЯ человек. Откуда ж знать?\nПусть Гименей дарует роста\nих роду... Ну а мы молчать\n\nлишь будем. Да ещё молиться,\nчтоб боги зажигали нам\nулыбками почаще лица\nи верность дали бы сердцам.\n\n20/06/17\nМосква"
 },
 {
  "id": "2017_06_20_5532",
  "title": "С неба снег будто",
  "genre": "философская лирика",
  "date": "20.06.2017 15:02",
  "url": "https://stihi.ru/2017/06/20/5532",
  "text": "С неба снег\nбудто,\nнам во сне\nмысли\nсеет сквозь\nсито\nсветлый наш\nбог.\nТот, кем мы\nбудем,\nесли всё\nсловим,\nлишних не\nтратя\nпопусту\nслов.\nНас он ждёт,\nсловно\nокеан\nреку.\nОн, как трон\nпринцу.\nДля пчелы -\nмёд.\nНаша цель\nжизни,\nкак к тебе\nвыйти?\nВсе пути-\nнити\nкак постичь\nнам?\nТерем ты\nсвета,\nо тебе\nгрезим.\nОттого\nвидим\nмы в ночи\nсны.\n\n14.06.17\nМосква"
 },
 {
  "id": "2017_06_16_3786",
  "title": "Грёзы о Париже",
  "genre": "шуточные стихи",
  "date": "16.06.2017 11:19",
  "url": "https://stihi.ru/2017/06/16/3786",
  "text": "Аромат парфюма сладкий\nмолодой официантки\nбудоражит аппетит...\nХорошо в Париже жить.\n\nТам все дамы летом в шляпках,\nкавалеры - в лёгких тапках.\nМузычка так \"ля-ля-ля\"...\nЕлисейские поля.\n\nСлавно там в кафе с друзьями\nза бокалом с пузырями,\nнеспеша вкушая жизнь,\nобсудить постмодернизм.\n\nПомурлыкать по-французски\nс девушкой в шикарной блузке.\nС ней остаться тет-а-тет,\nесли скажет \"да\" в ответ.\n\nТо - фантазия моя,\nи в Париже не был я :-(\n\nНо однажды посещу,\nвсё тогда уж изложу\nпрозаичней и реальней\nя о жизни галлов славных.\n\nМожет вместе, а? Друзья!\nЕсть и виза у меня!\n\nЕсли, вдруг, чего решите,\nнепременно напишите.\n\n15.06.17\nМосква"
 },
 {
  "id": "2017_06_13_2651",
  "title": "Хворост",
  "genre": "любовная лирика",
  "date": "13.06.2017 09:45",
  "url": "https://stihi.ru/2017/06/13/2651",
  "text": "Сеньорита,\nподбросьте хворосту\nв сердечную топку!\nЧтоб ум помутился,\nсбивался бы с толку.\n\nНе хочу строить планов.\nПусть будет всё пламенно:\nогнём желаний\nчувства дурманят.\nЧто с нами станет?\nНе знаю.\nНо веру в сердце\nсмело бросаю.\n\n06.06.17\nМск"
 },
 {
  "id": "2017_06_09_4144",
  "title": "Тишина",
  "genre": "верлибр",
  "date": "09.06.2017 11:44",
  "url": "https://stihi.ru/2017/06/09/4144",
  "text": "Знаешь, что мне в тебе понравилось?\nТишина.\nТы можешь быть взбалмошной и весёлой, но...\nТишина.\nТы тоже её слышишь.\nТишина.\nВечная, неколебимая ничем. Основа всего.\nТишина.\nКогда-то ничего не было. И когда-нибудь ничего не будет, но\nТишина\nБыла, есть и будет всегда.\nТишина.\nВо все времена. До времени. И после него.\nТишина.\nРождающая космос. Пространство для нас.\nТишина.\n\n08.06.17\nМск"
 },
 {
  "id": "2017_06_07_3882",
  "title": "Письмо А. С. Пушкину",
  "genre": "религиозная лирика",
  "date": "07.06.2017 11:13",
  "url": "https://stihi.ru/2017/06/07/3882",
  "text": "Свежевыкрашенное небо каплет серым.\nВроде лето на дворе, да не тепло.\nВ грусть нырнуть можно было бы нам всем смело,\nно так много на душе слов.\n\nДень рождения у Вас, Саша.\nВам хочу от всей души сказать:\nдля сердец Вы русских - чаша.\nВ этой чаше - благодать.\n\nЕсли мир вдруг в хаос погрузится,\nа на улицах всё заслонит туман.\nЧаши капли оживят нам лица,\nпробудят уснувший в нас талант.\n\nДа, все бури, вьюги и ненастья\nс Вашей чашей, Саша, не страшны.\nДа живите вечно! Дай Бог счастья\nдля всей нашей страждущей страны.\n\n06/06/17\nМосква"
 },
 {
  "id": "2017_06_05_78",
  "title": "В Тарусе",
  "genre": "без рубрики",
  "date": "05.06.2017 00:07",
  "url": "https://stihi.ru/2017/06/05/78",
  "text": "Бросаем якорь\nсегодня в Тарусе.\nЯков! Ты с нами?\nГуляем по-русски.\nПоэзии ягод\nотведайте вкусных!\nРаскрасим ночь ярко -\nв Тарусе мы тусим.\n\n03-04.06.17\nТаруса, Москва"
 },
 {
  "id": "2017_06_02_3333",
  "title": "Великан",
  "genre": "шуточные стихи",
  "date": "02.06.2017 10:21",
  "url": "https://stihi.ru/2017/06/02/3333",
  "text": "\"Влезай на плечи великанов:\nсверху мир весь лучше обозрим!\"\nТак советовал приятель мой, чуть странный,\nмы в трактир когда входили с ним.\n\nСев за стойкой и испив бокал с игристым,\nмонолог достойно продолжал:\n\"Знаешь ли, что дальше может сбыться?\nВдруг тебя не сможет удержать\nистукан, колени подломивши...\nПочему? Одно из двух я дам:\nлибо с великаном ты ошибся,\nлибо... Сам ты - великан!\"\n\nУлыбнулся мысли, подытожил:\n\"Если так... В одной из дальних стран,\nи в твоей стране, быть может...\nКто-нибудь, налив вина стакан,\nна портрет твой глянет, да и скажет:\n\"эх, вот то-то великан!\"\nА потом, однажды, дерзновенный,\nвдруг \"постигший\", что такое жизнь,\nон к тебе на плечи влезет.\nТак что, брат, готовься. И держись!\"\n\n01.06.17\nМосква"
 },
 {
  "id": "2017_05_26_6254",
  "title": "На коленях - кошечка",
  "genre": "белый и вольный стих",
  "date": "26.05.2017 15:31",
  "url": "https://stihi.ru/2017/05/26/6254",
  "text": "Мне кошечка рыжая \"прыг\" на колени,\nуютно усевшись, мурлычет вовсю.\n\nНо цепкие когти из лапок пустила\nи, в джинсы вцепившись, блаженно лежит.\n\nТак люди за \"счастье\" отчайно цепляясь,\nего мимолётность хотят удержать.\n\nНо джинсы не носит наш Бог-Вседержитель,\nсидеть на диванах Ему ни к чему.\n\nНас нежно погладит рукой по головке -\nмурлычем, к Нему на коленки хотим.\n\nДа, жизнь есть движенье, и Боже не может\nнас долго всех нянчить, как малых котят.\n\nЕму интересней, чтоб мы развивались,\nстремились, росли, расширяясь душой.\n\nДрузья! В нас проявлен пульс вечной Вселенной:\nв болотах уюта негоже нам гнить!\n\n07.05.17\nдеревня Поддыбье Ивановской области"
 },
 {
  "id": "2017_05_20_8024",
  "title": "American friend",
  "genre": "без рубрики",
  "date": "20.05.2017 19:38",
  "url": "https://stihi.ru/2017/05/20/8024",
  "text": "Я в подмосковной электричке.\nМне друг в WhatsApp'е позвонил:\nс ним обсуждаем по привычке\nвсё, что приносят жизни дни.\n\nЖивёт давненько он в Канзасе.\nТам, в самом центре США,\nгде домик Элли в город сказок\nторнадо унесли ветра.\n\nБродило племя краснокожих\nсреди широких тех степей.\nТеперь товарищ мой... И всё же\nРоссия образы сильней.\n\nМерещится ему раздолье,\nРоссии-матушки поля.\nВ Миссури видит славный Дон он.\nРодная будто бы земля.\n\nПшеница также колосится,\nплывут такие ж облака,\nв прудах рыбёшечка резвится.\nПрям Русь... Что сердцем бы лакал.\n\nНо люди всё же по-английски\nпривыкли душу выражать.\nЗастолье - барбекю, да виски.\nДушевно вроде. Но не так.\n\nПорою хочется забыться,\nсесть в белоснежный самолёт\nи улететь в страну, что снится\nему уже который год...\n\nТакое вряд ли он мне скажет.\nМой друг - брутальный человек.\n- Hello. Как сам?\n- С Катрин. На пляже.\nМеж строк читаю мысли те.\n\nДва континента между нами\nи неспокойный океан.\nМчит электричка тут полями,\nнад лесом уж взошла Луна.\n\nКрем для загара Кэтрин мажет\nему, на пляже дорогом.\nТоварищ о тоске - не скажет:\nне первый год я с ним знаком.\n\nапрель-май 2017\nМосква"
 },
 {
  "id": "2017_05_17_2952",
  "title": "Скоро лето",
  "genre": "шуточные стихи",
  "date": "17.05.2017 09:34",
  "url": "https://stihi.ru/2017/05/17/2952",
  "text": "Две недели ещё - и лето!\nНа каникулы дети пойдут.\nУ костра, да с гитарой... Рассветы?\nНет.\nЭтим летом мы встретим.... Весну.\n\nДа, её. Долгожданную где-то\nтретий месяц не можем найти.\nУбежала с любовником Ветром\nв южный край. Ох, и ветряный тип!\n\nЗадурманил её, заворОжил.\nОбещал, что покажет места,\nгде живёт он почти, как художник:\nнарисует с ней \"ню\" три холста.\n\nИ она, молодая, наивная\nполетела за Ветром тем вслед...\nНу а мы? Всё снега, да вот ливни тут -\nвсё вкушаем сей зимний десерт.\n\nНо вернётся! Не может иначе\nбыть под Небом на вечной Земле.\nSMS-ку прислала мне, с дачи:\nмол, \"у Ветра лишь сны на холсте...\n\nПрилетаю. Целую. До встречи!\"\nОстаётся лишь верить, да ждать:\nбудем мы первый летний наш вечер\nпо-весеннему, с песней встречать.\n\n16.05.17\nМосква"
 },
 {
  "id": "2017_05_05_6899",
  "title": "Весенние девушки",
  "genre": "городская лирика",
  "date": "05.05.2017 16:41",
  "url": "https://stihi.ru/2017/05/05/6899",
  "text": "Давно стихов я не писал,\nа вот сегодня захотелось.\nВлетела в тело мне весна -\nдуша запела.\n\nСады цветут по всей стране.\nБерёзки озорно смеются.\nКак Русь чудесна по весне!\nЖивит в нас чувства.\n\nОдеты девушки теперь\nизящно и легко - как вишни:\nпрям из садов Руси моей\nцветущих вышли.\n\nИ сотни наших городов\nнаполнились струями света.\nПорхает бабочкой любовь...\nВесна всё это!\n\n05.05.2017\nМосква"
 },
 {
  "id": "2017_04_12_6787",
  "title": "Ёж желаний",
  "genre": "любовная лирика",
  "date": "12.04.2017 15:45",
  "url": "https://stihi.ru/2017/04/12/6787",
  "text": "Она не носит нижнее бельё\nи чувствует себя чуть-чуть свободней.\nМужские взгляды падая, её\nшекочат страстью. Но всегда, так модно\nодета внешне - что не упрекнёшь.\nОна лишь знает, что секрет скрывает.\nЯ тоже её тайну эту знаю.\nИ колет мне воображенье ёж\nиголками желания... Лишь стать\nмечтаю я сейчас её одеждой,\nсобой чтоб нежно кожу укрывать\nеё души и плоти вешней.\n\n10.04.17\nМск"
 },
 {
  "id": "2017_04_09_5343",
  "title": "Предобеденный обет",
  "genre": "без рубрики",
  "date": "09.04.2017 12:36",
  "url": "https://stihi.ru/2017/04/09/5343",
  "text": "Получи лучи в лицо.\nСолнце радость раздаёт.\nТучи, прочь! В душе - светло,\nрасцветает всё, поёт.\n\nМысли зимние растают,\nпочву духа напитают.\nЧтоб бежалось по траве\nрадостно, ты, ветер, вей!\nСвежий воздух приноси,\nчувства новые и сил.\nВсё увидеть, обежать\nи. конечно ж, лучше стать.\n\nВыполним мы сей обет?\nДа, но только на обед\nуж пора нам всем, друзья...\nотобедаю и я\n\n30.03.17\nМосква"
 },
 {
  "id": "2017_04_09_5256",
  "title": "Девушка за кофе",
  "genre": "любовная лирика",
  "date": "09.04.2017 12:30",
  "url": "https://stihi.ru/2017/04/09/5256",
  "text": "Вы заказали каппучино,\nкогда вошёл в кафе мужчина\nи чинно к Вам за стол присел:\n- Пардон-муа, мадмуазель.\nЯ из Британии туманной...\nПятнадцать стран, три океана\nза пять мы лет пересекли.\nИ вот сегодня корабли\nв столицу Вашу привели.\nСкажите мне, не Вы ль царица\nземли сей? Дивные ресницы -\nтак царственны, невинны так.\nМечта моя, мой идеал!\nО Вас я грезил, Вас желал.\n\nСюжет эпохи романтизма?\nУже его не встретишь в жизни?\nВсё в Лету кануло, увы.\nО чём, красавица, же Вы\nмечтаете теперь за кофе,\nкогда его в кафе Вы пьёте:\nодна, с подружкой, с интернетом...\nРаскройте мне свои секреты!\n\nДа, дон жуаны, дон кихоты,\nпохоже, больше не в почёте.\nНе нужны также флибустьеры...\nБанкиры лишь? Миллионеры?\n- Ну что Вы, сударь, говорите?\nДа, жить неплохо на Таити.\nНо знаете... Душа - одна,\nона в любые времена\nполна романтики, мечтаний\nи благородных трепетаний.\n\nДостойный был ответ дан мне.\nНе зря узрел царицу в ней...\n\nПусть будет больше благородных!\nС душой красивой и свободной\nБожественных и озорных,\nглубоких, чувственных, родных.\nА прочие? Ну что ж, Бог с ними...\nнайдутся и для них мужчины.\n\n02-03.04.17\nпоезд Елец-Москва"
 },
 {
  "id": "2017_03_04_3683",
  "title": "Пятницкая",
  "genre": "городская лирика",
  "date": "04.03.2017 10:19",
  "url": "https://stihi.ru/2017/03/04/3683",
  "text": "Вот вечер пятницы.\nИду по Пятницкой\nот Красной площади и до кольца.\nПять дней я в офисе.\nЧто делал спросите?\nКак все, трудился там, в поте лица.\n\nТеперь я менеджер\nпотоков денежных:\nанализ/синтез new IT-чудес.\nСоздатель диаграмм,\nараб-факир я прям:\nкручу-верчу fucking бизнес-процесс.\n\nА что с поэзией?\nГде равновесие\nтеперь я черпаю своей душой?\nВсё там же, собственно...\nСердечно, образно\nпытаюсь чувствовать наш мир большой.\n\nЕсть жизнь и в офисе.\nКоллеги, кофе и...\nРитм, пульс, динамика - всё по часам.\nНайду минуточку\nпредаться чуточку\nмоим художествам, моим мечтам.\n\nИду по Пятницкой,\nна сердце радостно.\nЧуть позже вечером поеду к ней.\nВесна на улице -\nдождлива, буднична.\nА вот внутри - поёт уж соловей..\n\nфевраль-март 2017\nМосква\n\nЯков Шахов"
 },
 {
  "id": "2017_02_24_3204",
  "title": "Честный следователь",
  "genre": "гражданская лирика",
  "date": "24.02.2017 09:52",
  "url": "https://stihi.ru/2017/02/24/3204",
  "text": "Едет следователь Палыч\nна трамвае в комитет.\nАлкогольная усталость.\nВоскресенье. Денег нет.\n\nНо зато он верен службе:\nчтит закон, бичует зло.\nГод в столице - тут он нужен.\nС коллективом повезло.\n\nФедерального масштаба\nдело Палыч наш ведёт.\nКазнокрадцам из Генштаба\nнары в Воркуте куёт.\n\nВсе дома их на Рублёвке\nгосударству перейдут.\nАрестантскую похлёбку\nпохлебают, пожуют.\n\nАдвокаты тех злодеев\nпредлагали взять ему\nчемодан зелёных денег,\nчтоб не слал господ в тюрьму.\n\nПлюнул в лица тем холуям\nПалыч, гнев свой не сдержав.\nЧто же ждёт его? Не пуля\nи не лезвие ножа.\n\nХуже дома ожидало:\nосуждения жены.\nМол, \"дурак же ты, Пал Палыч.\nДолго будем мы бедны?\"\n\nВон, у Светки муж - электрик,\nда и тот - на BMW.\nТы - майор. Живём, как в клетке.\nПаша, где нам взять лаве?\n\nТех преступников, пойми же,\nведь отпустят - их друзья.\nБудут жить себе в Париже.\nКому честь нужна твоя?\"\n\nЧто ей скажешь? Неприятно.\nНо он любит и любим.\nПромолчал. И так несладко.\nВодку пил два дня один.\n\nА на утро, в воскресенье,\nвот поехал в комитет...\nНад Россиюшкой весенней\nсолнышка чуть брезжил свет.\n\n22/02/17\nМосква"
 },
 {
  "id": "2017_02_08_3874",
  "title": "Русский февраль",
  "genre": "пейзажная лирика",
  "date": "08.02.2017 10:56",
  "url": "https://stihi.ru/2017/02/08/3874",
  "text": "* * *\nЯ вчера вот вернулся из Праги:\nтам весна, а в Москве - снегопад.\nТам ручьи уже топят овраги,\nа в России морозы трещат.\n\nПо порогам бежит звучно Влтава:\nя с моста в ней кормил лебедей...\nНо давайте рассудим мы здраво:\nвсё же Родина сердцу милей.\n\nА февраль над Россией - не вечен.\nВскоре в край наш прибудет тепло.\nПусть луна серебрит дивный вечер -\nсеребром всю страну замело!\n\nНаш мороз - он нам дух укрепляет,\nчистотой закаляет сердца.\nНа Руси жизни смысл означает:\nжить по правде, и быть до конца.\n\nИ пророчит нам лучик весенний,\nчто средь стужи капель пробудил:\n\"Верь Россия, ведь будет спасенье:\nбудет март, будет жизнь впереди!\"\n\n07.02.17\nЕлец"
 },
 {
  "id": "2017_02_06_5803",
  "title": "Сергею Брокаренко",
  "genre": "акростихи",
  "date": "06.02.2017 13:55",
  "url": "https://stihi.ru/2017/02/06/5803",
  "text": "С древнейших пор\nЕлецкая дружина\nРоссии преданно\nГероями служила.\nЕлец - он прям, он горд,\nЮлить, лукавить не привыкший.\n\nБорец за правду (ту, что Свыше),\nРусь спасший от набега орд.\nОтечества он сын достойный.\nКогда же мир царит, покой,\nАрмейский дух - на пир застольный,\nРоссийский шумный пир горой!\nЕлец - он в Праге, он и в Ницце,\nНью-Йорк... Да, что нам океан?!\nКутим - такое не приснится!\nО, друг! Налей мне квас в стакан.\n\nфевраль 2017\nЕлец, Москва, Прага\n\n________________\n* первыми буквами по вертикали - Сергею Брокаренко"
 },
 {
  "id": "2017_01_21_3125",
  "title": "Два райских дерева",
  "genre": "философская лирика",
  "date": "21.01.2017 10:02",
  "url": "https://stihi.ru/2017/01/21/3125",
  "text": "Ах, Ева-Ева!\nN-раз \"пра-пра-\", прабабушка моя!\nХарактер твой, да и Адама-деда,\nпохоже, унаследовал и я\n\nРастут два дерева в саду... Всё, как и прежде.\nОдно - красиво и стройно, другое - нет.\nОдно - всё вширь, да вверх: к звезде, к надежде.\nДругое кустиком всё стелется к земле.\n\nРумяные плоды на первом. Только нужно\nвысоко залезать, сорвать чтоб плод.\nВторое дерево само даёт всё дружно,\nно вкус сомнителен, хоть аромат неплох.\n\nПленяет, как и вас, о предки наши,\nменя то дерево, что ввысь растёт.\nСадовник запретил ту дерзость... Страшен\nво гневе, слышал я, садовник тот.\n\n- Червивые плоды на дереве познанья\nДобра и Зла, - мне кто-то говорит.\nНе червь ли шепчет это назиданье?\nМагнитом дерево манит.\n\nКарабкаться наверх бессмысленно, бесплодно?\nВедь можно просто обезьянкой стать.\nКак все вкушать, банальные плоды второго?\nВ них есть стабильность, есть свой результат.\n\nА может, как Мичурин, третье древо,\nиз двух имеющихся, рядом посадить?\nЧтоб были все плоды - сочны и зрелы...\nИ смысл знать, и в радости чтоб жить.\n\n18.01.17\nЕлец"
 },
 {
  "id": "2017_01_18_12389",
  "title": "И причина, и смысл",
  "genre": "религиозная лирика",
  "date": "18.01.2017 23:37",
  "url": "https://stihi.ru/2017/01/18/12389",
  "text": "Эх...\nПосле баньки да в снег!\nВсе\nмы живём, как во сне.\nЧас\nпробуждения нас\nвот,\nвсё ж, однажды придёт.\nИ\nот своей суеты\nмы\nс первым солнцем весны\nмир\nлучезарный узрим,\nвесь\nот земли до небес.\nВек\nлишь живёт человек...\nТой\nвечно яркой весной\nвсю\nмироздания суть\nмы\nвсе постигнуть должны.\nОн\nнам откроет Закон:\nчто\nесть добро, а что зло.\nА\nпока надо нам знать:\nБог -\nнесомнено Любовь.\nТак\nпламенеет мечта...\nПусть\nтает злоба и грусть.\nМысль,\nсловно солнышка диск:\nмы -\nи причина, и смысл.\n\n13/01/17\nЕлец\n\nЯков Шахов"
 },
 {
  "id": "2016_12_28_4089",
  "title": "Шубка белая",
  "genre": "любовная лирика",
  "date": "28.12.2016 11:46",
  "url": "https://stihi.ru/2016/12/28/4089",
  "text": "Твоя шубка мне душу щекочет\nпредвкушением тела под ней.\nА улыбка игриво пророчит\nне замёрзнуть под сенью ночей.\n\nМоё сердце, как солнце, лучами\nвмиг растопит твой снежный наряд.\nПусть пылает любовное пламя,\nпусть алеет, как летний закат.\n\nМы едины порывом мгновений.\nПоглотил нас космический вихрь,\nдавний спор двух начал во Вселенной\nза пространство одно на двоих.\n\nА потом... Нет \"потом\". Только Вечность.\nБесконечно пусть длится любовь.\nВне-телесны и вне-человечны,\nты богиня сейчас, а я бог.\n\nдекабрь 2016\nМосква"
 },
 {
  "id": "2016_12_20_10658",
  "title": "Шерлок Холмс и газетная утка",
  "genre": "шуточные стихи",
  "date": "20.12.2016 22:27",
  "url": "https://stihi.ru/2016/12/20/10658",
  "text": "\"Инопланетное вторженье!!!\nЧто будем делать в Рождество?\nВесь Лондон полон раздраженья,\nгадает, кто же злейший вор,\nдерзнувший Англию-старушку\nоставить вовсе без игрушек...\"\n\nЗа чаем, с трубкою во рту,\nчитал газету Шерлок Холмс.\nкоторую ему принёс\nприятель оксфордский - Артур,\nналоговый инспектор в Лидсе.\nМогло такое ли случиться?!\n\nНо сыщика не проведёшь...\nОн в корень зрит, картину видит:\n- Бьюсь о заклад, то \"Gifts for Kids\"\nзадумали свою интригу.\nМонополисты, что возмёшь!\nИ в утреннем же завтра \"Таймсе\"\nнапишут, о покупке акций\nсвоих всех конкурентов, и\nпоявятся игрушки... Пли!\n\nСказав то, трубку чинно вынул.\nСкомкал газету, на пол кинул.\n\n20.12.2016\nЕлец"
 },
 {
  "id": "2016_12_04_8755",
  "title": "Четыре прадеда",
  "genre": "религиозная лирика",
  "date": "04.12.2016 18:02",
  "url": "https://stihi.ru/2016/12/04/8755",
  "text": "Четыре прадеда моих...\nКакая разная судьба.\nПускай приблизит этот стих\nк эпохе их, когда война\nвеликая пришла на Русь...\nВо славу стих им будет пусть!\n\n1. Александр Шахов\nОставив сына и жену,\nушёл на фронт. И не вернулся.\nГде Сталинград был, в том краю\nлишилось тело пулей пульса.\nОн \"финскую\" уже прошёл,\nи, вроде б, даже ранен был.\nКарельским скалам предпочёл\nпростор степных братских могил...\n\n2. Николай Зюзин\nДва старших сына - на войне.\nА он, вдовец, один хлопочет,\nчтоб выжить всей большой семье:\nтри сына маленьких, две дочки.\nВ озёрах северных - уха.\nВ лесах - озёра ягод спелых.\n\"Корова есть. Живём пока.\"\nЗимой для фронта лыжи делал...\n\n3. Илья Семишин\nСвоё уже отвоевал.\nКак много на сердце утрат:\nпохоронил жену, забрал\nи дочь блокадный Ленинград.\nОрловская губерния.\nДеревня. Он, сынок и дочь.\nНашествие немецкое...\nНо выжить нужно. Всем. Помочь.\n\n4. Иван Гаврилов\nК началу той войны великой\nтринадцать лет уже в земле...\nНарёк победно сына - Виктор.\nИ сын в свои семнадцать лет\nотправился на фронт. Мать, дом\nоставив - армии так нужен.\nНаверно, за двоих с отцом\nв боях он дважды был контужен.\n\nЕлецкая земля всего\nчетыре дня была под немцем.\nЗдесь после той войны мой род\nстал городским, был деревенским.\n\nПра-деды! Вы не обижайтесь,\nчто мало сведений о вас.\nВы жили правильно! Сейчас\nведь есть праправнуки у вас.\n\nПрабабушки детей рожали,\nсвои вы строили дома...\nНу а когда пришла война,\nВы тоже сделали немало:\nуберегли наш скромный род...\nИ ваша кровь во мне течёт!\n\nА ваша жизнь - пример достойный,\nРоссии нашей как служить.\nНарода подвиг миллионный,\nпотомкам давший право жить.\n\n1 декабря 2016\nЯков Шахов (Yakov Shakhov)"
 },
 {
  "id": "2016_11_29_7394",
  "title": "Лепестки цветков черешни...",
  "genre": "любовная лирика",
  "date": "29.11.2016 16:55",
  "url": "https://stihi.ru/2016/11/29/7394",
  "text": "Лепестки цветков черешни\nна подстриженном газоне\nнежно розовым и вешним\nна насыщенно зелёном\nвывели узор изящный,\nиероглиф обновленья,\nсимвол вечного движенья\nвереницы поколений.\n\nПо ковру тому ступает\nбосиком полубогиня:\nозорна, полунагая...\n– Здравствуйте, как Ваше имя?\nНичего мне не ответив,\nлишь улыбкой своей милой\nпробудила силу в жилах.\nМолча жестом пригласила\n\nпокачаться на качелях,\nчто стояли у черешен.\nВечер был безгрешно-нежен:\nпела много древних песен\nо любви бурлящих реках,\nчто приносят обновленье,\nи о Том, кому повеки\nмы обязаны твореньем.\n\n12-13/05/2016\nЕлец"
 },
 {
  "id": "2016_11_23_7370",
  "title": "Размышление о предназначеии",
  "genre": "философская лирика",
  "date": "23.11.2016 17:03",
  "url": "https://stihi.ru/2016/11/23/7370",
  "text": "ТАЙНА ИМЕНИ\nили РАЗМЫШЛЕНИЯ О ПРЕДНАЗНАЧЕНИИ\n\nЕсть в каждой вещи суть своя,\nи слово - код для этой сути.\nМы те в структуре бытия,\nкем Бог нарёк, наш мир творя.\nИ этим будем.\n\nХочу вопрос задать...\nВедь Бог создал\nменя.\nЯ тоже элемент Вселенной.\nХожу по тверди этой бренной\nзачем?\nКто я?\n\nВопрос меня когда-то мучил.\nТеперь уж нет.\nТеперь уж лучше.\nПрочёл послание и я,\nчто начертал могучий Случай,\nсоздав меня.\n\nСостав меня - довольно прост.\nСейчас открою его вам!\nРитм имени - хорей,\nне ямб,\nи рифма - чуть неточная,\nне встрой.\nНу что ж, как есть.\nМой смысл такой.\nМой код таков:\n\nЯ - ковш, черпающий любовь.\nЯ - ковш, ломающий преграды.\nЯ - ковш из мира снов и правды\nЯ - ковш, ЯковШ...\nЯков Шахов.\n\nОткапывать мне суждено\nпогрязшие в болотах страхов\nлюдские души... Путь иной\nпоказывай им, Яков Шахов.\n\nПусть кто-то скажет, что нескромно\nсебе призвание избрал.\nДрузья мои, не для похвал.\nНе сам избрал,\nтак Бог назвал.\n\nСкажи и ты мне, брат по веку!\nСо-путник мой, зачем ты здесь?\nЧтоб пересечь достойно реку,\nчтоб дотянуться до небес,\nчтоб мир любить огромный весь,\nосмыслить нужно человеку,\nзачем он здесь,\nи кто он есть.\n\n17.11.16\nЕлец"
 },
 {
  "id": "2016_11_21_3562",
  "title": "Царствуй",
  "genre": "религиозная лирика",
  "date": "21.11.2016 10:58",
  "url": "https://stihi.ru/2016/11/21/3562",
  "text": "Мне есть, в чём каяться пред Богом.\nНе то, чтоб этим сильно горд.\nНапротив, возгордиться мог бы,\nне знавши, что я грешный вор.\n\nВорую счастье у себя же.\nК нему добраться не могу.\nГрехи, как путы, ноги вяжут,\nя спотыкаюсь на бегу.\n\nРаспутай, Бог, мои распутства!\nРазумную я жизнь прошу.\nА если в бездну мой рассудок\nстремится, дай мне парашют.\n\nЗачем все эти говорю я\nбанальности в своём стихе?\nТы благо каждому даруешь...\nЯ грешен... Речь не о грехе.\n\nСебе хочу напомнить просто:\nТы есть. И мне уже светло.\nДа, есть за небом в тучах россыпь\nиз звёздных изумрудных слов.\n\nСкрижали те во снах открыто\nТвою нам Правду говорят:\nкак мы унылы и забиты,\nзабыли, что сердца хранят.\n\nЧто в нас, как в звёздах небосвода,\nогонь любви Твоей горит!\nНеиссикаема свобода,\nмы в царствии Твоём - цари.\n\n17.11.16\nЕлец\n\nЯков Шахов"
 },
 {
  "id": "2016_11_06_4819",
  "title": "Иоланта",
  "genre": "любовная лирика",
  "date": "06.11.2016 12:28",
  "url": "https://stihi.ru/2016/11/06/4819",
  "text": "На одной из московских тусовок\nя на танец её пригласил.\nОбстановка, признаться, мне нова:\nв этом баре впервые я был.\nНо под ритмы знакомой бачаты\nуж сближаются наши тела...\nРаз-два-три... Пять-шесть-семь... Ла-ла-ла.\nДа, девчонка - что надо... Мила!\n\n- Как зовут тебя, леди, скажи мне?\n- Иоланта. - Ого, Это в честь...\nНе встречалось ни разу мне жизни.\n- У Чайковского опера есть,\nвот меня в честь неё и назвали.\n- Ой прошу, замолчи, замолчи.\nРазве можно такое в ночи?!\nВ сердце страстью уж сальса звучит...\n\nОсторожней! Влюбиться ж могу.\nНе в тебя, а в историю эту.\nИ с твоих лепесток сорвать губ.\nГоворить же такое поэту?!\nЗасмеялась. Продолжили танец.\n- Иоланта, откуда же ты?\n- Из московской простой суеты,\nмой отец - перуанец... А ты?\n\nНо не мог уже я говорить,\nрастворившись с ней в звуках бачаты.\nНавивал мне мелодии ритм\nМачу-пикчу багровы закаты.\nНад долиной реки Урубамбы\nя испанцем отважным стоял,\nиндианку-трофей обнимал.\nИ масштаб снежных Анд был мне мал...\n\nМы в России: дождлива столица.\nВот и песни уж слышен финал.\n- Иоланта, позволь мне присниться -\nрасскажу всё, что я не сказал...\nНо довольно. Довольно влюбляться!\nБыть невольником взбалмошных чувств:\nохлаждать льдом рассудка искус\nя у северных наций учусь.\n\nоктябрь-ноябрь 2016\nМосква, Елец\n\nЯков Шахов"
 },
 {
  "id": "2016_11_05_3215",
  "title": "Верблюд",
  "genre": "сатирические стихи",
  "date": "05.11.2016 09:55",
  "url": "https://stihi.ru/2016/11/05/3215",
  "text": "- Людей люблю, -\nсказал верблюд. -\nКогда они\nне любят книг,\nтак много от верблюдов в них:\nидут-бредут,\nидут-жуют,\nих мысли ум не шевельнут.\nКогда же люди любят книги,\nони - как мы: согбенны, тихи,\nнавьючены,\nнаучены.\nЗато их шаг - уверен, горд.\nВзяв цель, идут из года в год...\nИ растворяются в тоске,\nкак мы, в пустынях и в песке.\n- Людей люблю, -\nвздохнул верблюд, -\nчитающих или без книг.\nТак много от верблюдов в них.\n\n02.11.2016\nЕлец"
 },
 {
  "id": "2016_11_03_4939",
  "title": "Детские страсти",
  "genre": "любовная лирика",
  "date": "03.11.2016 12:59",
  "url": "https://stihi.ru/2016/11/03/4939",
  "text": "Я зажал её в углу:\n- Будь моею!\n- Не могу, -\nговорит. - Я Димкина!\n- Уф-ф, - рычу, - где Димка тот?!\nБуду морду ему бить!\nРаз не хочешь ты любить.\nА колечко, что купил,\nвыброшу: раз я не мил.\nИли лучше я его\nподарю потом другой.\nМне, ведь, нету и шести -\nу меня всё впереди!\nИ у нас, в детском саду,\nя любовь ещё найду!\n\nоктябрь 2016\nМосква, Елец"
 },
 {
  "id": "2016_11_01_3078",
  "title": "Итог дорог",
  "genre": "авторская песня",
  "date": "01.11.2016 09:52",
  "url": "https://stihi.ru/2016/11/01/3078",
  "text": "ИТОГ ДОРОГ (романс)\n\nМожет, итог не один?\nМожет, дорог, две?\nСолнце, Луна ль в пути.\nАд или Рай в конце.\n\nКак же прожить жизнь,\nчтобы в ней был смысл?\nЧто за явление \"мы\"?\nи откуда пришли?\n\nБлагодарю ВСЁ:\nв каждом феномене - суть.\n\"Ми\" - между \"до\" и \"соль\",\nМы - в цикле \"радость\"-\"грусть\".\n\nДабы прожить жизнь,\nдабы вкусить смысл,\nмысль устремив ввысь,\nкрепко за Землю держись.\n\n15.10.16\nЕлец"
 },
 {
  "id": "2016_10_30_8785",
  "title": "Подарок юности",
  "genre": "городская лирика",
  "date": "30.10.2016 18:47",
  "url": "https://stihi.ru/2016/10/30/8785",
  "text": "Есть одна очень длинная улица,\nчто бежит вдоль широкой реки,\nв городе, где по утру целуются\nразведённые на ночь мосты.\n\nКак и прежде, поэты гуляют\n(где когда-то гулялось и мне)\nи в бокалы стихи наливают,\nдам купают в сём сладком вине.\n\nЯ оставил тот город романтиков\nи не так уже пьян от стихов.\nНо бывает по розовым бантикам\nузнаю облака тех годов.\n\nОдевай их почаще. Мне нравится!\nПылкой юности солнечный дар,\nопьяняй, вдохновляй! О, красавица.\nНе старел чтоб душой никогда.\n\nосень 2016\nЕлец"
 },
 {
  "id": "2016_10_12_9752",
  "title": "Брусничное утро",
  "genre": "гражданская лирика",
  "date": "12.10.2016 21:15",
  "url": "https://stihi.ru/2016/10/12/9752",
  "text": "Проснувшись в деревне утром,\nкогда ещё солнце красно,\nвключать не спеши в компьютер,\nища новостей вчерашних.\nТвой сонный, пускай, мобильник\nостанется на зарядке,\nа сам росою обильной\nиди, не влезая в тапки.\nНыряй с головою в речку,\nсеребряную прохладу.\nПлыви, озорной, беспечный,\nк девчонке, ждущей у сада.\nЕё поцелуй горячий\nне спутай со вкусом ягод,\nтех, что в берёзовой чаще\nона для тебя собрала!\nА после чаёк из блюдца -\nв беседке у самовара.\nСердца друг к дружке прижмутся,\nим целого мира мало.\nИ мысли уж - небанальны,\nот кислой во рту брусники:\nты раб сетей социальных?!\nИль сын природы великой.\n\n08.10.16\nЕлец\n\nЯков Шахов"
 },
 {
  "id": "2016_10_08_7357",
  "title": "Корабль",
  "genre": "философская лирика",
  "date": "08.10.2016 17:30",
  "url": "https://stihi.ru/2016/10/08/7357",
  "text": "Океанскому лайнеру тесно\nв русле даже широкой реки.\nОн пришелец миров\nнездешних,\nгде кричат свои песни киты.\nГде поверхность кудрявая нежно\nосвещена,\nа в пучинах - кромешная бездна\nи тишина.\n\nСвой фарватер по\nмелководью\nему нужно пройти.\nА там волны оближут любовно\nбелоснежные в тине борты.\n\n06.10.16\nЕлец"
 },
 {
  "id": "2016_10_02_4106",
  "title": "Разжигая звезду",
  "genre": "мистика и эзотерика",
  "date": "02.10.2016 12:10",
  "url": "https://stihi.ru/2016/10/02/4106",
  "text": "Я в груди разжигаю звезду.\nИзнутри всё она озаряет.\nРазноцветьем энергий играя,\nв мир транслирует свет, красоту.\n\nЯ внутри разжигаю звезду.\nСолнцу, пусть, на Земле помогает\nи, любовью людей опьяняя,\nпробуждает в сердцах доброту.\n\nИзнутри разжигаю звезду.\nПритяженье её возрастает.\nКаждый день, каждый миг я стараюсь\nпосвящать свою душу труду.\n\nА когда-нибудь в небо уйду...\nСредь созвездий радушных гуляя,\nбуду счастлив, другим помогая\nотыскать свою в жизни тропу.\n\nсентябрь 2016\nЕлец, Москва"
 },
 {
  "id": "2016_09_17_5548",
  "title": "Я - с Дона, она - с Волги",
  "genre": "любовная лирика",
  "date": "17.09.2016 15:03",
  "url": "https://stihi.ru/2016/09/17/5548",
  "text": "Я - с Дона, она - с Волги,\nа встретились в Москве.\nВ тоске не будем больше\nбродить из века в век.\n\nМы вместе. Это значит,\nчто яркая звезда\nлюбовью и удачей\nпрольётся к нам в сердца.\n\nЕсть смысл просыпаться.\nЕсть смысл вперёд идти.\nКружить по жизни в танце,\nпрокладывать пути.\n\nЯ - с Дона, она - с Волги.\nСольются берега.\nИ к счастью устремится\nединая река.\n\n18.08.2016\nЕлец\n\nПоэтический паблик автора:"
 },
 {
  "id": "2016_09_16_3394",
  "title": "Байкер",
  "genre": "любовная лирика",
  "date": "16.09.2016 10:45",
  "url": "https://stihi.ru/2016/09/16/3394",
  "text": "Душа кочевника зовёт в дорогу.\nГашетку до упора жму.\nВсе русские сердца гудят в восторге.\nРычите, волки! Мы в Крыму!\n\nОт Керчи и до самой Ялты\nпромчусь в каких-то три часа.\nРусалок здесь, братан, видал ты?!\nРельефы радуют глаза!\n\nОдну скульптурную блондинку\nвот прямо с пляжа захвачу.\nГалопом в гору, серпантином\nконя стального я помчу.\n\nДрожит девица, прижимая\nнабухший бюст свой мне к спине.\nУпруга юность озорная...\nПегас несёт нас в вышине.\n\nПод вечер, к ужину спустившись\nс перинных мягких облаков,\nза столиком в кафе обсудим\nнаш Крым, Россию и любовь.\n\nавгуст-сентябрь 2016\nЕлец, Самара, Москва\n\nПоэтический паблик автора:"
 },
 {
  "id": "2016_09_10_3394",
  "title": "Карфаген будет разрушен",
  "genre": "гражданская лирика",
  "date": "10.09.2016 10:53",
  "url": "https://stihi.ru/2016/09/10/3394",
  "text": "В Китае Обаме не подали трап.\nНа родине кудахчет Дональд Трамп.\nОдна Хиллари...\nИ та - хилая.\nАтлантизму приходит экзистенциальный конец.\nЛюди русские! Седлайте коней.\nНебоскрёбы взорваны Бушем.\nНебесных скрижалей сценарий слушай:\nКарфаген будет разрушен!\nБудет разрушен.\nБудет разрушен."
 },
 {
  "id": "2016_08_28_3953",
  "title": "Дождь и радуга",
  "genre": "любовная лирика",
  "date": "28.08.2016 12:08",
  "url": "https://stihi.ru/2016/08/28/3953",
  "text": "У фортепьяно сидит одиноко склонённая\nдевушка в синеньком платье домашнем своём.\nГоречь на сердце... Небесные глазки влюблённые\nбольше не радует солнышка блеск за окном.\n\n- Ах ты зачем мне тогда повстречался весною?\nДушу изранив, рассеял словами покой. -\nТо ли поёт, то ли плачет любовью и болью,\nпесней сердечной спасая себя от оков.\n\n- Ах вы, оковы любви той моей невзаимные,\nвас расколю о колючие камни судьбы.\nВы же прекрасные сны, мои грёзы невинные,\nвидно, не сбудитесь больше в сей жизни. Увы.\n\nЭта мелодия змейкой всё выше возносится\nи достигает прозрачную бездну небес.\nШирится, множится, серенькой тучей становится\nи направляется в город далёкий - Елец.\n\nГород тот древний, на русской равнине распластанный,\nмирно вкушает свой послеполуденный сон.\nЗдесь проживает тот Мишка, парнишка отчаянный.\nВот, кого девушка любит. Но он невлюблён.\n\n- Серые очи твои - отблеск северной ночи.\nПомнишь, как вдоль мы серебряной реченьки шли?..\nДождь за окном. В небе яркая буря грохочет.\nЧто-то иголкой кольнуло у парня внутри.\n\nВспышкой у Мишки в душе промелькнули картины:\nбелая майская ночь в отраженьях Невы,\nвместе идут вдоль фасадов любимых, старинных.\nДождь барабанит... И форточку Мишка закрыл.\n\nЗа фортепьяно поёт изнутри озарённая\nдевушка в синеньком платье домашнем своём...\nПеснь очищает прохладой ей душу влюблённую\nи проливается в город далёкий дождём.\n\nЯков Шахов\nиюль-август 2016"
 },
 {
  "id": "2016_08_18_5482",
  "title": "Одиночество",
  "genre": "философская лирика",
  "date": "18.08.2016 14:47",
  "url": "https://stihi.ru/2016/08/18/5482",
  "text": "Одиночество - отчество творчества.\nОдиночество - ночью один.\nПостигаешь немое пророчество\nв лабиринтах небесных картин.\n\nЕсли небо затянуто тучами,\nмелкий дождь фортепьянно стучит -\nэто жизни мгновения лучшие\nдля раскрытия тайны души.\n\nЧистый холст и палитра эмоций,\nинтуиции тонкая кисть...\nНу играй же смелей, новый моцарт!\nОщущая мелодией жизнь...\n\nИ пускай, тьма и тьма поколений\nпостигала её до тебя.\nРасширяет просторы Вселенной\nозарённое, скромное \"я\".\n\n16.08.16\nЯков Шахов"
 },
 {
  "id": "2016_07_25_9209",
  "title": "Каждый день я слушаю эту песню...",
  "genre": "без рубрики",
  "date": "25.07.2016 21:51",
  "url": "https://stihi.ru/2016/07/25/9209",
  "text": "Каждый день я слушаю эту песню.\nКаждый день, как в первый раз.\nЧто сокрыто в ней? В ней бездна,\nбездна чувств и нежность фраз.\n\nДа, душа, когда страдает,\nнет ей дела до ума.\nВ ней борьба... И светлым раем\nмрачный ад превозмогает,\nсилой мудрости полна.\n\nЭто близко мне. Я помню,\nкак и сам душой страдал...\nПесни той живые волны -\nоживляющий бальзам.\n\n21.07.16\n\nЕлец"
 },
 {
  "id": "2016_07_19_5466",
  "title": "Увёз из грёз",
  "genre": "любовная лирика",
  "date": "19.07.2016 14:55",
  "url": "https://stihi.ru/2016/07/19/5466",
  "text": "Романсы пишешь...\nСо сцены арии\nсопрано ты поёшь давно.\nС годами чище\nи печальнее.\nСудьбой уж так предрешено.\n\nИль нет?\nЯ мудрствовать не стану.\nОтветь,\nне кажется ли странным\nтот эпизод, длиной в три дня?\nИ я, приехавший нажданно\nк тебе. Случайно или нет?\nПрошу ответь\nсвозь интернет.\n\nМы шли с тобой той белой ночью.\nРекой текла беседа точно:\nширока и светла. Потом\nнастала осень над Невою.\nВсего два дня. И небо колем\nвдвоём с тобой одним зонтом.\n\nИ больно. Небу и тебе.\nА мне?\nПожалуй, нет.\nЯ ведь всего лишь спал,\nи это всё приснилось мне.\n\nПроснулся в поезде,\nна верхней полке,\nвзяв и покинув город грёз.\n\"Всерьёз?\" вопрос иль \"Не всерьёз?\"\nДа просто так:\nменя увёз\nиз грёз простой электровоз.\n\nВполне типичная хэппи-энд\nдля сна, в три дня.\nЧто скажешь? Нет?\n\n18.07.2016\nЕлец"
 },
 {
  "id": "2016_07_01_1962",
  "title": "Привет из Сирии",
  "genre": "любовная лирика",
  "date": "01.07.2016 08:12",
  "url": "https://stihi.ru/2016/07/01/1962",
  "text": "Наши тела не подходят друг другу,\nа души - не пазлы Инь-Яня.\nОтчего же из круга в круги\nменя к тебе тянет?\n\nПомнишь древний песок пустыни?\nТы в скафандре вельможной особы.\nА я раб. Нёс тебя в балдахине,\nне скрывая восторгов и злобы.\n\nИ твой муж тогда, это заметив,\nсвёл меня на каменоломни.\nВот когда блеск очей твоих светлых\nнавсегда я душою запомнил.\n\nА потом уже было иначе.\nБерег Тибра. Я римский патриций.\nТы наложница: лучше и слаще\nнет трофея из южных провинций.\n\nЖили мы в поднебесном Китае\nи в Мадриде времён инквизиций.\nБангладеш, Амазонка, Гавайи...\nА теперь вот Россия нам снится.\n\nТы актриса московских театров,\nа я снайпер в сирийской пустыне:\nприлетел я в себе разобраться\nи понять, что с тобой у нас было.\n\nМне про карму ту странную нашу\nодин старый поведал сириец.\nОн монах (здесь воюет за наших),\nот разлуки не давший мне спиться.\n\nА стихи записал мой товарищ,\nкак и я душой, русский поэт.\nПосылаю вот месседж ВКонтакте\nи из Сирии тёплый привет.\n\n08/06/2016"
 },
 {
  "id": "2016_07_01_1933",
  "title": "Не любил",
  "genre": "любовная лирика",
  "date": "01.07.2016 08:07",
  "url": "https://stihi.ru/2016/07/01/1933",
  "text": "Да собственно сказать, тебя я не любил.\nМанили красота и возраст юный.\nВлекли, как море из пустыни Нил,\nтвои глаза царицы южной.\n\nДа собственно сказать, я сердцу лгал.\nЯ полагал, настойчивость и воля\nсумеют сердце победить. Да, больно\nему порою было. И я ждал.\n\nКак парижане летом жаждят Ниццы,\nтебя я ждал. Но чаще был один.\nМешают городу с луною слиться\nвезде горящие огни.\n\nДа собственно сказать... К чему слова?!\nМне нравилось, что творчества чернила\nв душе моей те чувства обновили,\nи что с тобой... кружилась голова.\n\n04/06/16\nЕлец"
 },
 {
  "id": "2016_07_01_1898",
  "title": "Не может солнце быть луной",
  "genre": "любовная лирика",
  "date": "01.07.2016 08:03",
  "url": "https://stihi.ru/2016/07/01/1898",
  "text": "Не может солнце быть луной,\nа луна - солнцем.\nЛюбви пылающей, большой\nне жаждем больше.\n\nНе вышло ничего. Что ж, пусть.\nГрустить не будем.\nПодвластен путь любви и чувств\nбогам - не людям.\n\nСтихи на башне городской\nчитал для музы.\nЧитает пусть теперь другой:\nне стал ей мужем.\n\nПохожи звёзды меж собой\nи не похожи.\nКак много на Земле людей...\nИ мы здесь тоже.\n\n31/05/2016"
 },
 {
  "id": "2016_07_01_1872",
  "title": "Платформа счастья и обид",
  "genre": "любовная лирика",
  "date": "01.07.2016 07:59",
  "url": "https://stihi.ru/2016/07/01/1872",
  "text": "Как легко хлопнуть дверью.\nСказать \"прости, ошибся\" и уйти.\nТрудней  – поверив, перещёлкнуть\nв тупик идущие пути.\n\nНаш поезд мчится, пробегая\nплатформы счастья и обид.\nВагон СВ. Полунагая\nсидит, в окошечко глядит.\n\nИ я не сплю. Уснуть ли можно,\nкогда бушует ураган?\n\"Всё сложно\"  – статус на Facebook'е.\nЗачем урок нам этот дан?\n\nНе проще ли сказать друг другу\n\"люблю\". А дальше лишь молчать.\nИ ждать, когда утихнет вьюга,\nи в сердце не кормить волчат.\n\n05/05/2016"
 },
 {
  "id": "2016_04_22_4955",
  "title": "Неизвестный Париж",
  "genre": "поэтические переводы",
  "date": "22.04.2016 13:35",
  "url": "https://stihi.ru/2016/04/22/4955",
  "text": "Чужой мой город, я тебя люблю.\nПо книгам знаю и из песен.\nОгромен, но душе так хорошо известен,\nхоть не был никогда в твоём краю.\n\nМне часто видится бульвар\nс журнальных чёрно-белых фото,\nцветущий как волшебный сладкий лотос\nмежду гуляющих влюблённых пар.\n\nЯ мыслями лечу в твой сад Дю Люксембург\nЗамусорен, наверное - обидно.\nНо грязи мне, влюблённому, не видно,\nЛюбовь привыкла грезить наяву.\n\nВот Нотр-Дам. Колоколами бьёт,\nГлас Вечности звучит, пред Ней я грешен...\n\nВ Берлине я живу, и им утешен.\nБерлин - он здесь, Париж - далёк.\n\nА издали все девушки красивы.\n\n(Stefan Heym \"Unbekanntes Paris\"\nперевод с немецкого: Яков Шахов\nмарт 2016)"
 },
 {
  "id": "2016_04_22_4897",
  "title": "Потерянные сны",
  "genre": "поэтические переводы",
  "date": "22.04.2016 13:29",
  "url": "https://stihi.ru/2016/04/22/4897",
  "text": "На тропинках грёз моих\nвижу образ юный твой.\nУскоряя пульс в груди,\nпеснь рождается душой.\n\nНежный возраст твой весенний\nцифрой ветренной пьянит.\nМанит, манит в свои сети,\nласки робкие сулит.\n\nТолько где, скажи мне, где же,\nмилый друг, тебя найти?\nКак же звали тебя прежде?\nРазошлись у нас пути.\n\nТвоё имя и твой адрес\nспутал сон. Иль может я?\nГде-то бродишь по тропинкам\nдавняя мечта моя.\n\n(Julio Cortazar \"Objetos Perdidos*,\nперевод с испанского: Яков Шахов)\n\n02/03/2016"
 },
 {
  "id": "2016_04_22_4581",
  "title": "Мелкий бес",
  "genre": "любовная лирика",
  "date": "22.04.2016 12:58",
  "url": "https://stihi.ru/2016/04/22/4581",
  "text": "Когда влюблённые, раскрыв сердца свои,\nготовы счастие вкушать как хлеб насущный,\nвстаёт вдруг между ними мелкий бес,\nпаразитирующая энергосущность.\n\nС крысиным маленьким хвостом.\nЛукавые глазёнки, хобот.\nКомар сосущий, но не кровь, -\nвлюблённых друг на друга ропот.\n\nСомнения, обиды, недоверье -\nвот пища для него. Такой уж гад.\nВнушает ей: \"Не делай шаг на встречу первой!\"\nЕму: \"Обманщицу нет смысла ждать!\"\n\n\"Она не та. Любви твоей не стоит!\"\n\"Себя он любит - не тебя!\"\n\"Мужчина ты! Будь горд и стоек!\"\n\"Словам его не верь: вода.\"\n\n\"Им всем лишь одного и нужно!\"\n\"Самовлюблённая кокетка. Нет.\"\n\"Не будет он отцом и мужем.\"\n\"Чтоб детям мамой стала? Бред.\"\n\nБес мысли присылает иль словами\nиз уст знакомых кстати говорит.\nБывает, прячется в советах мамы,\nи к дружеским беседам он привык.\n\n- Всё хватит, стоп! Молчи, лукавый!\nЯ слушать бред твой не хочу!\nТебя сомнения мои питают?\nСейчас обед я прекращу.\n\nРаскрою сердце ещё шире:\nпоток любви течёт полней!\nНу что хлебнул? Куда ты, милый?\nБыл тут. И нет его уже.\n\nДраконы, черти, барабашки\nбоятся искренней любви.\nСейчас один из них от Яшки\nогрёб за мерзости свои.\n\n11.04.16"
 },
 {
  "id": "2016_04_19_1839",
  "title": "Капризная Родина",
  "genre": "поэтические переводы",
  "date": "19.04.2016 07:46",
  "url": "https://stihi.ru/2016/04/19/1839",
  "text": "Хулио Кортасар\nКАПРИЗНАЯ РОДИНА\nТы видишь Южный Крест.\nвдыхаешь лето и аромат его спелых персиков,\nгуляешь по ночам.\nМоя далёкая и тихая мечта.\nАргентина!\nВсё та же, милая сердцу\nАргентина.\n\nТы даришь влагу моим глазам,\nлишь коснувшись лёгкой рукой своей\nмоей души.\nТы даришь прохладу расстояния,\nрасставание,\nгорький полуночный кофе\nодиночества.\n\nДождь всегда начинает идти\nв середине фильма.\nЯ получил от тебя цветок,\nно паук прятался среди его лепестков.\n\nДумаю, ты знаешь это.\nИ это всего лишь очередной твой каприз.\nНо я постоянно забываю зонт\nпрежде, чем увидеть тебя.\nВ ресторане не было свободных мест,\nа на углах твоих улиц распродавалась война.\n\nЯ был текстом твоих танго,\nмелодий, не требующих слов.\n\n(Julio Cortazar \"La mufa\",\nперевод с испанского: Яков Шахов\nмарт 2016)"
 },
 {
  "id": "2016_04_17_3563",
  "title": "ПочтиПоэт",
  "genre": "поэтические переводы",
  "date": "17.04.2016 10:47",
  "url": "https://stihi.ru/2016/04/17/3563",
  "text": "Мария фон Эбнер-Эшенбах\n\nТрагедия есть в мире этом -\nрождённым быть почтипоэтом.\nОбъять душой простор Вселенной,\nгде xаос - в буйстве неизменном.\nВ его страстях, в его борьбе\nузреть, как Тьма рождает Свет.\n\nВмещать и адовое пламя\nи рая чисты идеалы.\nВнимать, как вянет красота.\nРосу пить с нового цветка.\nГулять и кущей, и болотом,\nтак не познав, на свете кто ты.\n\nДар неосмысленный внутри,\nбеззвучный крик в твоей груди.\nБутон раскрывшийся в волненьи.\nПокоя нет! Вперёд стремленье...\nНо как всё это передать?\nСлова как с чувствами связать?\nТрагедия есть в мире этом -\nрождённым быть почтипоэтом.\n\n(Marie von Ebner-Eschenbach \"Der Halbpoet\"\nперевод с немецкого: Яков Шахов\nфевраль 2016)"
 },
 {
  "id": "2016_04_05_9861",
  "title": "Серафим",
  "genre": "религиозная лирика",
  "date": "05.04.2016 20:41",
  "url": "https://stihi.ru/2016/04/05/9861",
  "text": "Вот вспомнил время фронтовое.\nЯ командиром роты был.\nФашистам, помню, после боя\nс десяток вырыли могил.\nПохоронили... Тоже ж люди.\nА сами сели пировать.\nТакая участь у солдат -\n\"Сегодня жив. А завтра будем?\"\n\n- И чем же будем запивать?\n\nУ немцев - схрон. А там три бочки.\nПо праву наш теперь трофей.\n- Ребята, спирт!\n- Уверен?\n- Точно.\n- А ну-ка, брат, давай налей.\n\nСолдаты мигом оживились.\nГотовы \"к бою\" котелки.\nНо пить нам было не с руки.\n- Что даром шли? И даром бились?\nПриказ: \"По бочкам ну-ка! Пли!\"\n\nПриказ отдал седой полковник.\nЯ спорить. Он мне: \"Не дури!\"\nЕго не знаю, видно, новый.\nНу что же делать, братцы: \"Пли!\"\n\nЗапели трели автоматы,\nпролился спирт наш на песок.\nИспытывали лёгкий шок\nмои поникшие солдаты,\nи я, присевший на пенёк.\n\nПотом (не помню уж как точно)\nузнал, что это метанол.\nСпирт не этиловый - метиловый.\nПолковника не видел больше,\nно он тогда беду отвёл.\n\nА вот окончилась война,\nего глаза я снова встретил.\nНа сером маленьком портрете.\nИ где? Прям дома у меня!\n\nМонах с крестом и бородой\nседой, как снег. Прозрачны очи.\nПолковник наш. Он самый. Точно.\nА взгляд хоть строгий, но родной.\n\n- Кто это? - маму я спросил.\nОна: \"То старец Серафим.\nОтец духовный мой, наставник.\nМолился Богу за тебя,\nи видишь сам - ты жив и вздраве.\nВсё Господу благодаря!\"\n\n3 апреля  2016 г.\nАвтор: Яков Шахов\n_________________\n* Из \"Жития Преподобного Серафима Вырицкого\""
 },
 {
  "id": "2016_04_01_10872",
  "title": "Job",
  "genre": "шуточные стихи",
  "date": "01.04.2016 21:28",
  "url": "https://stihi.ru/2016/04/01/10872",
  "text": "Я сегодня целый день искал работу.\nРезюме, HeadHunter... Найти б хоть что-то.\nВ графе поиска ввёл слово \"поэт\".\n\"Результат запроса: вакансий нет.\"\n\nТак... Что ещё я умею?\nУмножать, слагать... Интегралить - робею.\n\"Математик\" - ввожу я в той же графе.\n\"Результат запроса: вакансий нет.\"\n\nХм-м. Что ещё?\n\nМогу в онлайне быть... Хоть целый день.\nСердечки, репосты... И прочая хрень.\n\"М-е-н-е-д-ж-е-р\". Пишу я русское слово.\nВот это да! Вот это сурово!\n\n\"1105 вакансий - в Москве.\"\nРебята, что скажите? Может, это по мне?!\n\n01/04/16\n\nP.S.\nС 1 апреля, друзья! ;"
 },
 {
  "id": "2016_03_31_5768",
  "title": "Вы когда нибудь...",
  "genre": "поэтические переводы",
  "date": "31.03.2016 13:49",
  "url": "https://stihi.ru/2016/03/31/5768",
  "text": "Элизабет Уэсли\nВЫ КОГДА-НИБУДЬ...\n(перевод: Яков Шахов)\n\nВы когда-нибудь\n\nв гуще колосьев пшеничного поля\nв небо смотрели, а ласковый дождик\nВас целовал, - и под сердцем кололо?\n\nИли в минуту внезапной печали\nдругу звонили, часами болтали?\nМилой своей Вы фиалки вручали?\n\nМожет, качали детей на руках?\nХлебом кормили Вы нищих бродяг?\nЧасто летали душой в облака?\n\nЗапечатлев уходящий момент,\nБогу молитву шептали за всех,\nныне живущих на грешной Земле?\n\nС дерева ели Вы спелый лимон?\nУтром морозным узор за стеклом,\nв солнца лучах, приводил Вас в восторг?\n\nОт безысходности выли, как волк?\nМожет, мечтали под жёлтой луной\nили кружились Вы в танце хмельном?\n\nВсё это Жизни великой дыханье,\nболь или радость - сердец трепетанье.\nМиру улыбкой Вы чаще сверкайте!\n\n(Elizabeth Wesley\n\"Have You Ever\"\nперевод с английского:\nЯков Шахов\nмарт 2016)"
 },
 {
  "id": "2016_03_09_5356",
  "title": "Есенину",
  "genre": "городская лирика",
  "date": "09.03.2016 14:00",
  "url": "https://stihi.ru/2016/03/09/5356",
  "text": "\"... не ставьте памятник в Рязани...\"\nС.А. Есенин \"Мой путь\"\n\nЕсть в Рязани памятник странный.\nЯ запомнил его черты,\nкогда с музой под ручку гуляли\nпо просторам великой страны.\n\nБогатырских размеров, парень,\nи по пояс зарытый землёй.\nВзором зорким в далёкие дали\nустремлён он открытой душой.\n\nТа земля его силой питает\nи кудрявит пшеницу волос.\nПод берёзовым небом Рязани\nклён могучий и славный возрос.\n\nА ещё там я видел картину,\nкак на памятник мальчик залез,\nфотографию юного сына\nмолодой снизу делал отец.\n\nА потом, тот мальчишка, слезая,\nу отца как-то робко спросил:\n\"Знаешь, папа, я, кажется, знаю,\nэтот дядя защитником, был?\"\n\nЛюбознательность милая детства\nот отца получила ответ:\n\"Этот парень простой, деревенский,\nбыл великий он русский поэт!\"\n\nДа, Есенин, с тобой мы знакомы.\nТы воистину огненный щит,\nот неправды лукавой и злобы\nсердце русское стих твой хранит.\n\nИ хоть памятник ставить в Рязани\nне велел ты потомкам своим,\nо тебе будем помнить стихами,\nчто когда-то ты здесь сотворил.\n\nмарт 2016\nРязань, Тула, Елец\n\nЯков Шахов"
 },
 {
  "id": "2016_03_03_3453",
  "title": "Мысли вслух",
  "genre": "cтихотворения в прозе",
  "date": "03.03.2016 10:42",
  "url": "https://stihi.ru/2016/03/03/3453",
  "text": "Где?\nНебольшая квартира в стареньком доме у дороги, ведущей к храму. Между тюрьмой и разорённым монастырём. Местом, где спорят с Богом, и местом, где Его славят (точнее, славили раньше, но в последнее столетие почему-то перестали).\nНебольшой городок в четырёхстах километрах южнее большого. Столицы. Самой большой страны нашей планеты. Планета - не самая большая. И звезда. Где-то ближе к краю скопления себе подобных.\nКогда?\nЧуть более двух тысяч раз обернулась планета вокруг своей звезды после того, как на ней родился тот, которого мы распяли. За правду, колющую наши глаза.\nКто?\nОдин из семи миллиардов похожих на других, распявших Его. Но тогда нас было меньше.\nЧто?\nНабираю текст, нажимая на чёрные клавиши. Пытаюсь через него хоть что-то понять.\nЗачем?\nНе знаю. Вдруг, пойму, что что-то не так идёт, как должно, и изменю. Вряд ли получится, но я буду стараться. Либо пойму вдруг, кто я на самом деле и зачем я здесь. Хотя это, кажется, ещё никому из нас не удавалось.\nМожет зря мы Его распяли?\nИли так надо было?\nСколько ещё планета совершит оборотов прежде, чем я уйду с неё?\nИ куда я уйду?\nТуда, откуда пришёл или куда-то ещё?\nТы! Может быть, Ты меня слышишь?\nПомоги найти ответы на эти вопросы!\nЛибо я их должен искать сам?\nА может, это вообще всё неважно?\nИ я просто недореализованный бездельник, в праздности проводящий отмеренные ему мгновения?\nПочему тогда всё так случилось?\nИли эти вопросы всё же хоть что-то значат?\n\n01.03.2016\nЯков Шахов"
 },
 {
  "id": "2016_02_18_3754",
  "title": "Австралия",
  "genre": "стихи для детей",
  "date": "18.02.2016 10:58",
  "url": "https://stihi.ru/2016/02/18/3754",
  "text": "Маленькая кухонька\nв маленькой квартире.\nЗа столом с английского\nтекст переводили.\n\nЧто-то про Австралию.\nДевочка и мальчик.\nПальчики по клавишам\nдевочкины скачат.\n\nИзумрудной прерией\nкенгуру стадами.\nКлавиши ноутбучные\nпроросли полями.\n\nА в глазах у девочки -\nморе-океан.\nНа доске б для сёрфинга\nпо лихим волнам!\n\nМельбурн, Сидней, Канберра.\nЧто за города!\nНебоскрёбы горами,\nрайски берега!\n\nЗагорелый, сильный он,\nпрямо у воды,\nи она в купальнике\nрозовом стоит.\n\nВдруг. Качнулось всё,\nскрылось под волну...\nДевочка толкает:\n\"Ты чего? Уснул?\"\n\nМаленькая кухонька\nв маленькой квартире,\nпятый час с английского\nтекст переводили.\n\n17.02.2016\nЕлец"
 },
 {
  "id": "2016_02_11_2724",
  "title": "Другу детства",
  "genre": "без рубрики",
  "date": "11.02.2016 09:16",
  "url": "https://stihi.ru/2016/02/11/2724",
  "text": "Конец двадцатого столетья,\nи снова смута на Руси.\nБорис на троне.\nМы были дети.\nДалёк наш город от Москвы.\n\nХодили в садик, после в школу.\nДрались и в шутку, и всерьёз,\nиграли в Дэнди, \"Mortal Combat\",\nи делали забеги ос.\n\nНаловим коробком от спичек\nмы пару-тройку жёлтых ос,\nжужжаших на кусте,\nи бег с препятствием для них\nпо всем приличьям,\nустраиваем где-то тут же, во дворе.\n\nБывало, что оса кусалась,\nоставив в коже жало - не беда!\nНас это в осах очень восхищало:\nпогибнуть смело, \"поразив\" врага.\n\nА помнишь, как мы самыми крутыми\nс тобой в районе рэперами были?\nНосили балахон, банданы...\nТе шорты до сих пор мне велики!\nНу да! Крутые чуваки! :)\n\nИ ты ещё мечтал родиться\nтолстым негром,\nв какой-нибудь трущобе,\nблизь Нью-Джерси.\nА наши первые смешные песни\nписались на магнитные кассеты.\n\nНам скоро 30 стукнет. Что ж поделать...\nБег времени, увы, остановить нельзя.\nДа, детство наше, юность отжужжали,\nНо к счастью, их целительное жало\nне в силах из сердец извлечь\nни ты, ни я.\n\nфевраль 2016"
 },
 {
  "id": "2016_02_03_6075",
  "title": "Лиана надежд",
  "genre": "любовная лирика",
  "date": "03.02.2016 14:11",
  "url": "https://stihi.ru/2016/02/03/6075",
  "text": "Там побережье океана,\nныряет солнце в негу вод.\nИ девушка усталым взглядом\nласкает алый небосвод.\n\nСтройна, как пальма. Тёплый ветер\nеё касается волос,\nи платье бежевого цвета\nзакат окрасил цветом роз.\n\nВдали от суеты веселья\nстоит задумчива, одна.\nЗачем скучает в чудный вечер?\nО чём же думает она?\n\nО том, что где-то за закатом\nстрана заснеженная есть.\nЧто вскоре кораблём крылатым\nона дотронется небес.\n\nВернётся птицей перелётной\nв свой край. И, может быть, её\nкудрявый сероглазый кто-то\nв краю том ждёт уже давно.\n\nБыть может, он на солнце тоже\nсейчас глядит сквозь облака.\nСвет солнца одолеть поможет\nим часовые пояса.\n\nВ душе у девушки - надежда,\nмостом из золотых лиан.\nИ, сбросив на песок одежду,\nидёт купаться в океан.\n\n30.01 - 02.02.2016"
 },
 {
  "id": "2016_01_28_4244",
  "title": "Пьют в глубинке люди...",
  "genre": "гражданская лирика",
  "date": "28.01.2016 11:48",
  "url": "https://stihi.ru/2016/01/28/4244",
  "text": "Пьют в глубинке люди,\nпьют мои друзья.\nТолько я не буду,\nтолько мне нельзя.\n\n- Может, гордый очень?\nМожет, нездоров?\nИли трезвым хочешь\nбыть в эпоху снов?\n\nНет. Я пьяный тоже,\nпьян я без вина.\nДушу мне тревожит\nсолнышком весна.\n\nСтранное то дело:\nбрежу наяву.\nЗа окном - метели,\nвижу я - весну.\n\nТаят все сугробы,\nширится река.\nНабухают почки,\nвыше облака.\n\nЛуч земли коснулся.\nИ травинки вдруг,\nкак мурашки, лугом\nк берегу бегут.\n\nНа полянке двое,\nи в руке - рука.\nОн её целует\nв щёчку... Эх, весна!\n\nВот какие грёзы\nснятся наяву\nвечером морозным.\nМне лишь одному?\n\n27.01.16"
 },
 {
  "id": "2016_01_26_8625",
  "title": "Чай с лимоном",
  "genre": "любовная лирика",
  "date": "26.01.2016 18:14",
  "url": "https://stihi.ru/2016/01/26/8625",
  "text": "Чай с лимоном люблю по утрам\nпить из кружки с твоей фотографией,\nновогодний презент от тебя...\nА вообще я люблю с тобой завтракать.\n\nДаже если омлет подгорел\nили \"мы на гавайской диете\" -\nэто мелочь. Улыбка твоя -\nсамый вкусный десерт на планете!\n\nНу а если просторы Земли\nнам преградой окажутся снова,\nна меня с кружки той ты смотри.\nСлаще чай будет пить мне с лимоном.\n\n23.01.2016"
 },
 {
  "id": "2016_01_26_8549",
  "title": "Чайка морская",
  "genre": "любовная лирика",
  "date": "26.01.2016 18:05",
  "url": "https://stihi.ru/2016/01/26/8549",
  "text": "Не звонишь третий день и не пишешь.\nТам тебе без меня хорошо?\nДалеко. Но душою мне кажешься ближе.\nРасстояние чувствам -\nв осмысленье дано.\n\nРазобраться в себе,\nможет, хочешь, а может быть, просто\nпроверяешь меня.\nЯ не знаю. Не стану звонить.\nА стихи? Уж прости.\nМежду сердцем и сердцем\nлишь колеблют незримую,\nтонкую нить.\n\nНам просторы земные даны,\nчтоб познать расставанья,\nа стихи, чтобы легче их было\nдуше превозмочь.\nПрилетай морской чайкой ко мне\nты во сне на свиданье.\nЛибо просто \"Привет!\" напиши.\nКогда близится ночь.\n\n21.01.2016\nЕлец\n\nЯков Шахов"
 },
 {
  "id": "2016_01_26_8294",
  "title": "Прорубь",
  "genre": "любовная лирика",
  "date": "26.01.2016 17:45",
  "url": "https://stihi.ru/2016/01/26/8294",
  "text": "Ёлка сбросила иголки,\nпраздничный померк наряд,\nно гирляндой дней волшебных\nчувства в памяти горят.\n\nИзумрудный скорый поезд\nна заснеженный вокзал.\nАлы щёки от мороза.\nТы приехала? Я ждал.\n\nЁлочку купили вместе\nи зеркальные шары.\nИз фольги я сделал пику,\nпомнишь, как смеялась ты?\n\nМандарины и салаты.\nРыбку в сыре запекла\nСкатерть нежно--золотая\nна стол праздничный легла.\n\nПунш в серебряных бокалах,\nречь вещает президент.\nНоль часов на Спасской башне.\nТы да я, и лишних нет.\n\nА потом деньки бежали,\nсловно речка подо льдом.\nПомнишь, как по льду гуляли,\nне боявшись - крепок лёд.\n\nДа и крепкие морозы\nне страшили нас тогда.\nА сейчас? Нестрашны тоже,\nхоть меж нами города.\n\nЯ на поезд быстрый сяду,\nчтоб увидеться с тобой\nДа. Крещенская нам прорубь -\nванна с тёплою водой.\n\nянварь 2016\nСПб"
 },
 {
  "id": "2015_12_13_7836",
  "title": "Деревенская идилия",
  "genre": "пейзажная лирика",
  "date": "13.12.2015 17:46",
  "url": "https://stihi.ru/2015/12/13/7836",
  "text": "Молоко попил из крынки,\nвытер губы рукавом,\nтак по-русски. По старинке.\nЗдравствуй, родина, мой дом.\n\nВ печке треск сухих полешков,\nполон явств дубовый стол.\nИз-за речки деревенской\nсмотрит лес на нас в окно.\n\nСядем. Вспомнится былое.\nМожет, чуть и погрустим.\nСколько минуло... С тобою\nмы по-прежнему близки.\n\nНу пойдём, пойдём скорее.\nбанька ждёт уж во дворе.\n- Бей сильней! Ещё сильнее.\nвеничком да по спине.\n\nА потом, по снегу к речке,\nв прорубь, пыл свой остудить.\nХорошо. Теперь сердечко\nпросит чай с медком испить.\n\nНочкой той морозно-звёздной\nбудет нам с тобой тепло.\nО грядущем ярки грёзы\nпринесёт пресладкий сон.\n\nВот Земля. Кружит столетья,\nмиг для Млечного Пути.\nИ потомков наших дети\nтакже счастливы, как мы.\n\nЯков Шахов\n\n12.12.2015\nСПб\n\nТеги:"
 },
 {
  "id": "2015_12_01_7016",
  "title": "На дне рождения у Блока",
  "genre": "любовная лирика",
  "date": "01.12.2015 16:19",
  "url": "https://stihi.ru/2015/12/01/7016",
  "text": "В старой гостиной, где белый рояль\nструнами в лад шевелит,\nснимок портретный: на нём юбиляр.\nГолос Ваш юный звучит.\n\nТрепет, восторг наполняют сердца\nв зале сидящих людей.\nДуши колеблет мелодий волна\nветром пшеничных полей.\n\nСлушал и я Ваш красивый романс:\nмысли, родившие звук –\nс третьего ряда взирая на стан\nи на движение рук.\n\nПосле концерта я к Вам подошёл.\nПлечи укрылись в платок.\n– Пели чудесно! Всё хорошо.\nЖаль, не купил я цветов.\n\nВы улыбались. Меня до дверей\nскромненько так проводив,\nверны остались дороге своей.\nБрёл я каналом чужим.\n\nВетер в канале качает фонарь,\nтени спешащих домой.\nВечер промозглый. Тоскливый ноябрь\nгород опутал собой.\n\nА вот в груди – полыхает огонь:\nсвет и тепло. Я спешу:\nвместо цветов, неподаренных мной,\nВам я стихи напишу.\n\n30/11/15\nСанкт-Петербург"
 },
 {
  "id": "2015_11_26_8067",
  "title": "Витать в облаках - это низко...",
  "genre": "философская лирика",
  "date": "26.11.2015 18:37",
  "url": "https://stihi.ru/2015/11/26/8067",
  "text": "Витать в облаках - это низко.\nСолнце - да, высоко.\nДальше - звёздные выси,\nдо звёзд дотянуться легко.\n\nСердце объемлет пространства,\nв нём обитают миры.\nЧтоб воцарился Порядок,\nв сердце Любовь сотвори.\n\n25.11.2015\nПетербург\nЯков Шахов"
 },
 {
  "id": "2015_11_25_5231",
  "title": "Москва",
  "genre": "городская лирика",
  "date": "25.11.2015 13:39",
  "url": "https://stihi.ru/2015/11/25/5231",
  "text": "Говорят, Москва слезам не верит.\nТолько видел, она сама плачет.\nКак царевна за запертой дверью,\nнелюбимому отдана замуж.\n\nПлачет, когда сердца русских\nпод нерусские ритмы бьются.\nОттого-то Москве грустно,\nоттого мысли змеями вьются.\n\nПлачет, когда забывают,\nчто добро побеждает всегда.\nКогда душу на деньги меняя,,\nдля других затворяют сердца.\n\nПлачет в храмах своих столица\nи слезою осенней дождит.\nЗа людей неустанно молиться\nсолнце над облаками велит.\n\n\"Может, всё же за облачком серым\nон почувствует солнышка свет?\nИ отыщется витязь тот смелый,\nизбавитель царевны своей.\"\n\nГоворят, Москва слезам не верит.\nГоворят... Ну и пусть, говорят.\n\n21-22.11.2015\nМосква\n\nАвтор: Яков Шахов"
 },
 {
  "id": "2015_11_16_4354",
  "title": "Звездолёт",
  "genre": "стихи для детей",
  "date": "16.11.2015 12:00",
  "url": "https://stihi.ru/2015/11/16/4354",
  "text": "На плечо сестрёнке Даше\nопустился звездолёт.\nМеньше пуговицы даже,\nприлетел с далёких звёзд.\n\nНа звезду и сам похожий:\nбелый-белый, как звезда.\nНа кристалл похожий тоже...\nЧто такое? Тут вода!\n\nВидно, звездолёт заметил,\nчто за ним я наблюдал.\nУлетел к своим планетам.\nЗдесь осталась лишь вода.\n\nА сестрёнка мне сказала:\n- То снежинка лишь всего.\nИ растаяла, наверно,\nот дыханья твоего.\n\n24.10.2015\nПетербург"
 },
 {
  "id": "2015_11_16_4302",
  "title": "Маленький папа",
  "genre": "стихи для детей",
  "date": "16.11.2015 11:54",
  "url": "https://stihi.ru/2015/11/16/4302",
  "text": "Когда мой папа был малыш,\nснежинки также вот кружили.\nИ бегал папа в снежной пыли,\nи был в мечтах он выше крыш,\nсчастливый самый в целом мире!\n\nТеперь мой папа уж большой.\nНо кажется. всё там же, в детстве.\nМы сквозь метель несёмся вместе.\nИ лучше в мире нет друзей,\nв снегу измазанных, как в тесте.\n\nКогда же вырасту и я,\nв снегу валяться с сыном буду.\nИ тоже стану ему другом.\nТрадицией сильна семья\nи радостью в семейном круге.\n\n23.10.2015\nПетербург"
 },
 {
  "id": "2015_11_16_4215",
  "title": "Зимняя кошка",
  "genre": "стихи для детей",
  "date": "16.11.2015 11:47",
  "url": "https://stihi.ru/2015/11/16/4215",
  "text": "У окошка сидит кошка,\nсмотрит пристально в окошко.\nЧто случилось, не поймёт.\nС неба белый пух идёт.\n\nСтранная какая шутка:\nносит ёлка теперь шубку,\nу забора шапка есть -\nне узнаешь здешних мест!\n\nВсё кругом белым бело,\nи дорожку замело.\nБыла речка - теперь поле.\nЧудо чудное какое!\n\nНа руки возьму я кошку,\nи шепну я ей на ушко:\n- Кошка, милая моя!\nПросто к нам пришла зима.\n\n21.10.2015\nПетербург"
 },
 {
  "id": "2015_11_16_4177",
  "title": "Зима",
  "genre": "стихи для детей",
  "date": "16.11.2015 11:44",
  "url": "https://stihi.ru/2015/11/16/4177",
  "text": "Снова к нам пришла зима.\nЯ кричу зиме \"Ура\".\nИ она мне отвечает,\nсолнышком в снегу играя.\n\nБрошу в ящик свой планшет,\nигр таких в планшете нет:\nсанки, лыжи и коньки.\nБудем мы кидать снежки.\nВылепим мы снежну бабу...\n- Но сосульки грызть не надо!\n\nПотеплей оденьте шапки!\nВарежки нужны на лапки.\nСнежная пришла пора -\nнаша зимушка зима!\n\n18.10.2015\nПетербург"
 },
 {
  "id": "2015_11_14_5821",
  "title": "Ивану Бунину",
  "genre": "гражданская лирика",
  "date": "14.11.2015 14:39",
  "url": "https://stihi.ru/2015/11/14/5821",
  "text": "I.\nПройдусь по старому Ельцу.\nСегодня не один гуляю,\nя с Ваней Буниным встречаюсь\nу дуба, в городском саду.\n\nИван, прости, что я «на ты»,\nтак по-простому, по-елецки.\nНе принял ты страны советской,\nтеперь уж нет и той страны.\n\nА Родина? Была и есть.\nХоть в разные росли столетья,\nземли одной с тобой мы дети.\nОтец же наш родной – Елец.\n\nЯ тоже уж давно не здесь\nживу. Бывает, что скучаю\nи, как и ты, я навещаю\nв мечтах окрестность здешних мест.\n\nВот мальчик бронзовый сидит,\nзадумавшись о чём-то важном.\nВ сторонку отложив фуражку,\nсквозь время и миры глядит.\n\nЧтоб мысли те его послушать,\nнаушники я вставлю в уши.\nВ стихах расскажет интернет,\nо чём ты думаешь, поэт.\n\nВсем сокровенным, наболевшим\nс тобой, как с братом, поделюсь\nи покажу родную Русь\nи город наш, чуть повзрослевший.\n\nII.\nВот парк, где юношей когда-то\nкормил ты белых лебедей.\nСпугнула их толпа людей\nи шум вечерних танцплощадок.\n\nВот каланча. Который век\nвзирает на Елец с вершины.\nТеперь пожарные машины\nна службе вместо лошадей.\n\nПойдём же дальше, по Орловской,\nк собору спустимся с тобой.\nТеперь он с золотой главой,\nкак богатырь под ярким солнцем.\n\nГлядит за реку, на восток,\nгде были орды Тамерлана.\nИли на запад, где незванны\nфашисты шли... Храни нас Бог!\n\nТорговой улицей пройдём.\nЗнакомься вот – Владимир Ленин.\nЯ знаю, твой он современник.\nЧто говоришь? Торговец он?\n\nСтраной, как мясом, он барыжил?\nНу ладно. Ведь и сам в Париже\nты жил. И умер. Он в Москве.\nНе будем. Лучше в тишине\n\nдавай с тобой мы посидим.\nТам у фонтана, на скамейке\nи сквозь тенистые аллеи\nна бой курантов поглядим.\n\nP.S.\nПотом подъехало такси.\nКуда намерен, не сказал.\nМеня ж зовёт ЖД-вокзал.\nО'ревуар и гран мерси.\n\n9-12.11.2015\nЕлец, Санкт-Петербург\n\nЯков Шахов\n\nТеги:"
 },
 {
  "id": "2015_11_11_5631",
  "title": "Листва",
  "genre": "философская лирика",
  "date": "11.11.2015 14:18",
  "url": "https://stihi.ru/2015/11/11/5631",
  "text": "Ноябрь-месяц, всё идёт к зиме.\nНо день чудесен: солнечен и ясен.\nЛиствой ковёр соткался на земле:\nберёза, тополь, клён, осина, ясень.\n\nВсё отдано. Все листья пали ровно.\nКто к солнцу ближе был, кто ниже - все равны.\nПохожи на людей те листья словно:\nна землю падают в преддверии зимы, как мы.\n\n09.11.2015\nЕлец"
 },
 {
  "id": "2015_11_11_5579",
  "title": "Движение мысли",
  "genre": "философская лирика",
  "date": "11.11.2015 14:13",
  "url": "https://stihi.ru/2015/11/11/5579",
  "text": "Живописец -> писатель -> поэт -> музыкант.\n\nВот движение мысли от образа к ритму.\n\nОтражает весь мир Богом данный талант,\n\nмежду Ночью и Днём непрерывную битву.\n\n10.11.2015\n\nЯков Шахов"
 },
 {
  "id": "2015_10_17_9728",
  "title": "Прогулка к морю",
  "genre": "поэмы",
  "date": "17.10.2015 21:59",
  "url": "https://stihi.ru/2015/10/17/9728",
  "text": "I. Елец\nВ коридоре вагона\nя стою, заряжаю\nот розетки советской\nсвой погасший iPhone.\nКак деревья в окошке,\nте мгновенья мелькают\nдвух недель проведённых\nсреди моря и гор.\n\nНачалось всё банально.\nС другом Пашей решили\nк морю Чёрному съездить\nи чуть-чуть отдохнуть.\nРанним утром 8-го\nна машину мы сели\nс настроеньем чудесным.\nТак отправились в путь.\n\nМы в Ельце стартовали,\nгде уже две недели,\nкак оставив свой Питер,\nя гостил у родных.\nНа Ростов навигатор,\nмагистраль М4.\nЧто поведаю дальше?\nЧто расскажет мой стих?\n\nПочему же обратно\nя на поезде еду?\nЧто случилось с машиной?\nГде остался мой друг?\nВы, любезный читатель,\nмне чуть времени дайте.\nЗаряжу свой мобильный\nи всё Вам расскажу.\n\nНапишу я о дружбе,\nсовременных кокетках,\nможет быть, и любви\nя немного коснусь.\nЮжных горных пейзажей\nи красот Лукоморья\nпару фраз оброню я\nи про Древнюю Русь.\n\nII. Ростов\nНу вперёд же скорее!\nKia Rio уж мчится\nчерез Дон и Воронеж\nна Ростов-на-Дону.\nТам ночуем сегодня,\nпогуляем, изучим.\nА уж завтра к обеду\nснова тронемся в путь.\n\nВыезжая в дорогу,\nя наметил заране\nпосетить тех знакомых,\nчто живут по пути.\nВот Ростов нас встречает\nмилой девушкой Нилой,\nчто любезно согласна\nна ночь нас приютить.\n\nС Нилой мы незнакомы,\nно её попросили\nнаши общие други\nгород нам показать.\nМы немного устали\nведь 700 километров,\nцелый день, всё ж, в дороге,\nа не 2-3 часа.\n\nНо все пробки и вёрсты\nпозабыты, гуляем,\nполной грудью вдыхая\nвоздух вольных степей.\nДон, наш батюшка, будто\nнад землёй поднимая,\nдержит город огромный\nна ладони своей.\n\nУ меня день рожденья!\nВ суши-баре с друзьями,\nев нездешнюю рыбу,\nмы ведём разговор.\nПоздравленья и тосты,\nвсё попили, всё съели.\nЗавтра снова в дорогу,\nчто пора бы домой!\n\nНила - скифов копает,\nведь она археолог:\nкости предков и утварь\nдостаёт из земли.\nОхраняя царицу,\nу дивана её мы,\nсловно древние скифы,\nна пол с Пашей легли.\n\nВ 6 утра я проснулся.\nИ пока мирно спали\nв коммунальной квартире\nростовчане-жильцы,\nя на улицу вышел,\nчтобы к Дону спуститься.\nПесней утро встречали,\nщебетали птенцы.\n\nДон, широко текущий,\nсолнца диск отражает.\nВдоль по брегу десятки\nживых спортом людей.\nТренажёры, пробежки,\nа вон юная леди\nу перил балеринит...\nЯ напротив сидел.\n\nА потом мы гуляли.\nПомню завтрак в Старбаксе,\nгде миндальным эспрессо\nПаша нас угощал.\nСувениры и фотки,\nобнимашки, прощанье.\nДо свидания, Нила!\nРостов-папа прощай!\n\nО, Ростов! Всё ж надеюсь,\nчто увидимся вскоре.\nТы такой самобытный,\nнепохож на других.\nЛевБерДон - теперь знаю,\nлевый берег у Дона,\nа на правом когда-то\nздесь Суворов служил.\n\nIII. Анапа\nВ Краснодар нам бы надо,\nгде ждёт новая встреча.\nНо сказали, там пробка\nаж в 4 часа.\nВдоль Азовского моря\nпо хорошим дорогам\nна Анапу свои мы\nустремили сердца.\n\nТам, в Анапе, давненько\nуже нас поджидали:\nстарший брат отдыхал мой\nсо своею семьёй.\nИ друзья ещё наши\nпервой юности дальней.\nОкружили заботой\nи своей добротой.\n\nУже звёздная бездна,\nкак толпа, ликовала,\nа на трон восходила\nкоролева Луна,\nв море я искупался.\n\"Здравствуй, Чёрное море!\nДолгожданная встреча!\nВспоминал я тебя.\"\n\nВ ресторане - все вместе.\nРанним утром - на яхту,\nна рыбалку поедем,\nхотя я не рыбак.\nВот и утро - в пучину,\nкак дельфины, ныряем.\nЯхту сильно качает.\nГорд и весел моряк!\n\nРыбы мы не поймали.\nНу и славно, не надо.\nМой племянник на пляже\nстроит замки песком.\nОн уж плавать умеет,\nпревосходно ныряет.\nЯ бросаю - и брызги!\nКак касатка хвостом.\n\nIV. Абхазия\nНебо ранней зарёю\nнад Анапой сияет,\nПаша ключ зажиганья\nповернул. И вперёд\nот волшебного жеста\nмимо водной лазури\nупряжь в сто лошадей нас\nсерпантином несёт!\n\nНовороссийск, Геленджик\nи ещё Кабардинка,\nгде в дольменах хранится\nтайна мудрость Земли.\nА потом кони наши,\nвидно, чуть подустали,\nи под Джубгой мы в пробке\n2 часа провели.\n\nУж смеркалось, мы в Сочи\nна машине въезжаем\nи в туннелях несёмся\nдо окраин страны.\nВот и кактус абхазский\nза границей встречает.\nАргонавты - в Колхиде!\nЗа царевной пришли.\n\nАня учится в Минске\nи немного скучает,\nотдыхая под Гагрой\nвместе с мамой своей.\nС Селигера знакомы,\nгода 3, как ВКонтакте\nпереписка. И вот, мы\nпару дней будем с ней.\n\nЧайкой белой дни эти\nбыстро так пролетели.\nАвтокемпинг, палатка,\nи мои же стихи\nмне на пляже в Пицунде\nнаизусть прочитала.\nА на жёлто-лукавом\nслово \"Smile\" на груди.\n\nВ горном озере Рица\nАня с Пашей ныряет,\nи советскую песню\n\"Третий должен уйти\"\nмы в машине все пели\nи слова понимали.\nАня с грустью сказала:\n\"Паша, Яша, прости!\"\n\nНапоследок ещё нам\nпожелала, хороших\nчтобы с Пашей девчонок\nнепременно нашли.\nИ уехала с мамой\nв зарубежье, в Россию.\nМы совету же вняли:\nпоискали - нашли.\n\nДве сестры, из Уральских\nна Кавказские горы,\nзагореть захотели\nна морском берегу.\nПознакомились - рады,\nчто мы с ним не абхазы.\nНеужели похожи?\nШутка новых подруг.\n\nВот и день тот приходит,\nнам пора возвращаться.\nЖдёт нас Адлер и Сочи,\nи ещё Краснодар.\nТы Абхазия - сказка:\nживописная Гагра,\nдлиннохвойные сосны\nи небесна вода!\n\nПляж вечерний закатом,\nкак вином, опьяняет.\nКак и медленный танец\nв ресторане \"Гагрипш\".\nНа конях скачем в горы!\nИ вокал - в древнем храме.\nАпельсинно-лимонна\nюжно-нежная жизнь!\n\nV. Красная поляна\nВот вернулись в Россию\nи на Красной поляне\nс Пашей мы собирались\nночь одну ночевать.\nЗдесь всё супер! Шикарно!\nЦелый город вознёсся.\nРоза-хутор построен\nкак оазис в горах.\n\nМы с приятелем Женей\nповстречались, самбистом.\nОн тут с игр Олимпийских\nпостоянно живёт.\nНа подъёмнике утром\nс Пашей в горы мы едем,\nсовершенно не зная,\nчто же дальше нас ждёт.\n\nНа вершине - прозрачно,\nвоздух - свеж и приятен.\nМы просили нас сфоткать\nдвух столичных богинь.\nВчетвером за обедом\nмы спонтанно решили,\nчто отъезд наш отложим\nмы на завтрашний день.\n\nА на утро проснувшись,\nя спросил: \"Как поедем?\"\nПаша тихо ответил:\n\"Знаешь? Я остаюсь.\"\nТо, признаться, нежданно.\nВот на поезде еду.\nТолько Паша - мне с детства,\nлет 15 как, друг.\n\nИ вопросов я лишних\nзадавать не намерен.\nЕсли так друг решил мой,\nзначит это всерьёз!\nЛишь об рельсы вращаясь,\nнавивают колёса:\n\"Может, в горы влюбился?\nА быть может, в неё.\"\n\n21/08 - 15/10/15\nпоезд Сухум - Москва,\nСанкт-Петербург\n\nТеги:"
 },
 {
  "id": "2015_10_10_10572",
  "title": "Эрекция дельфина",
  "genre": "шуточные стихи",
  "date": "10.10.2015 23:21",
  "url": "https://stihi.ru/2015/10/10/10572",
  "text": "Вдоль моря шли. Она и он.\nШуршала галька под ногами.\nЛетали чайки над волнами.\nА он был, кажется, влюблён.\nДельфинов видят. На афише.\nОна спросила: \"Знаешь, фишку?\nДельфины - извращенцы! Вот.\"\nНетривиальный поворот.\n\nОн засмеялся: \"Почему?\"\n\"Я плавала в бассейне с ними\nи видела, что у дельфина\nбыла эрекция. В Крыму\nтот дельфинарий находился.\nЧего так сильно удивился?\"\n\"Ну нет. Наверно, просто рядом\nдельфинья самка проплывала!\"\n\nА сам задумался: \"Вчера.\nМы только встретились. В горах,\nсредь облаков моя богиня\nгуляла. Чудная картина.\nОна сошла женой Адама\nмужское пробуждать начало.\nНо грешен мир. Свои концы\nлишь только чувствуют. Самцы.\"\n\n6-8.10.2015\nСанкт-Петербург\n\nТеги:"
 },
 {
  "id": "2015_10_05_3696",
  "title": "Белочка",
  "genre": "любовная лирика",
  "date": "05.10.2015 11:36",
  "url": "https://stihi.ru/2015/10/05/3696",
  "text": "В парке старом лесенка\nна гору бежит.\nПокидая веточку,\nклёна лист кружит.\n\nПруд внизу, под горочкой:\nзолотом вода.\nСквозь листву там плавает\nуточек семья.\n\nРядом с клёном - дуб-силач\nустремился ввысь.\nВеточка за веточкой\nбелка скачет вниз.\n\nБелочка пушистая,\nапельсинов мех,\nиз руки доверчиво\nкушает орех.\n\nЗнаю одну девочку:\nкроткий добрый нрав.\nИмя? Рифма \"белочке\",\nосень - в волосах.\n\nЛюбит есть конфеточки\nбелочка моя.\nХоть проси-упрашивай:\nцеловать нельзя!\n\nХорошо, ну ладно, пусть.\nБудем лишь друзья.\nКак от солнца тает грусть,\nвижу лишь тебя.\n\nВ парк придёшь? На лавочку,\nшоколадку есть.\nБелочка, а белочка?\nНу ответь мне \"yes!\"\n\n04/10/15\nЯков Шахов\n\nТеги:"
 },
 {
  "id": "2015_10_01_2869",
  "title": "Испанская страсть",
  "genre": "любовная лирика",
  "date": "01.10.2015 10:13",
  "url": "https://stihi.ru/2015/10/01/2869",
  "text": "Ты сказала: \"Te querro!\"\nВозразил я: \"Te amo!\"\nПо-испански как скажешь,\nчто тебя я люблю?\nИли в танце пусть лучше\nкавалер своей даме,\nслов не тратя, покажет\nстрасть и нежность свою?\n\nЛунно-звёздное небо\nза рекой наблюдает.\nУ колонны старинной\nя танцую с тобой.\nПод испанские ритмы\nмыслю я по-испански,\nсловно рыцарь влюблённый,\nДон-Кихот молодой.\n\nВот затихла гитара,\nя тебя провожаю.\nУ балкона, захочешь,\nсеренаду спою.\nА быть может соперник\nтут меня поджидает?\nРазговоры - пустое...\nСвой кинжал обнажу!\n\nУ метро очень просто\nи по-русски простились.\nПоцелуй? Только в щёчку,\nпомахала рукой.\nНо испанские страсти\nснова мозг закружили:\n\"Buenas noches, guapa!\nДоброй ночи, любовь.\"\n\n29-30/09/2015\nЯков Шахов\n\nТеги:"
 },
 {
  "id": "2015_09_02_4542",
  "title": "Маша",
  "genre": "поэмы",
  "date": "02.09.2015 13:44",
  "url": "https://stihi.ru/2015/09/02/4542",
  "text": "Яков Шахов\nМАША\n/ Яков Шахов /\nI.\nСередина 90-х,\nдетский лагерь на Дону.\nДискотека, как у взрослых,\nзубы чистить и ко сну.\n\nНо пока последний танец,\nбелый танец... \"О, медляк!\nИ к тому же, они сами\nприглашают. Так-так-так.\"\n\nМальчик, 10 лет от рода.\nСердце бьётся, ищет Ту.\n\"Где ж Она? Была же вроде б.\"\nВзором сверлит темноту.\n\nТут, к нему подходит Маша.\nНо не Та, подруга Той.\nЧуть повыше, чуть постарше.\n\"Но не хуже красотой!\"\n\nПриглашает. Он смутился.\nОтвечает скромно: \"Нет.\"\nМаша ждёт, потом уходит.\nВсё как будто бы во сне.\n\nОн ни разу, ведь, ни разу\nс девочкой не танцевал.\nНо уже об этом думал,\nто давно уже желал.\n\nПоразмыслил и решился!\nПобежал за Машей вслед.\n\"Хорошо, что подошёл ты!\"\nНет следа, от прежних \"нет\".\n\nВот танцуют. Он, робея,\nотдавил все ноги ей.\nНо зато, как стихла песня,\nстал он чуточку взрослей.\n\nИ теперь друзьям он гордо\nмог с восторгом объяснять,\nкак же с девочками нужно\nговорить и танцевать!\n\nII.\nА однажды, в той же смене,\nслучай вышел вот какой.\nПриготовить выступленье\nнужно было им гурьбой.\n\nКак-то вышло, что Мария\nглавной в деле том была.\nИ, конечно же, участье\nон принять решил. Ла-ла!\n\nРепетируют, а Маша,\nвзглядом обувь оценив,\nпрямо так ему сказала:\n\"Есть, чем это заменить?\"\n\nГлянул - пыльные ботинки.\nВмиг спустился он с небес.\nОтвечает ей с усмешкой,\nгордо так: \"Конечно, есть!\"\n\nНо куда там! Он же знает,\nчто ботинки-то одни.\nДа что левый прохудился.\nХоть носки и не видны.\n\nМама, видно, так решила:\n\"Пусть доносит до конца,\nа уж к школе что-то купим.\nУж раскрутим мы отца!\"\n\nЧто же делать? Как-то просто,\nвдруг, решение пришло.\nВ умывальнике ладошкой\nобувь вымыл... Нет и слов.\n\nВот идёт в ботинках мокрых,\nа за ним идут следы.\nКовыляет, маскирует:\n\"В левом видишь дырку ты?!\"\n\nУ столовой встреча: Маша.\nНе заметив его \"труд\",\nодобрительно кивнула:\n\"Да, вот эти подойдут!\"\n\nIII.\nИ так в рваненьких ботинках\nвсю он смену танцевал.\nКаждый танец подходил к ней,\nтолько Машу приглашал.\n\nТанцевали почти молча,\nредко слово обронив.\nТолько все в округе знали,\nдружат с Машею они.\n\nА на следующей смене\nМаши не было... И что ж?\nС лучшей той её подругой,\nтанцевать ему пришлось.\n\nТа, которая до Маши\nнравилась ему, теперь\nкак-то чуточку поменьше\n\"отворяла сердца дверь\".\n\nМашин адрес, как молитву,\nвыучил он \"назубок\".\nДумал: \"Вот вернёмся в город,\nсъезжу!\" Но и так, не смог.\n\n\"Может, встретимся случайно?\nПросто так, сказать привет.\"\nУ судьбы свои есть тайны,\nи её ответ был: \"нет.\"\n\nВот прошло уже лет 20,\nдядей стал, наверняка.\nНо твердит порою адрес:\n\"Фрунзе улица, 2а\".\n\n29.08. - 02.09.2015\nСанкт-Петербург"
 },
 {
  "id": "2015_07_09_7248",
  "title": "По Ясной поляне...",
  "genre": "любовная лирика",
  "date": "09.07.2015 18:49",
  "url": "https://stihi.ru/2015/07/09/7248",
  "text": "По Ясной поляне\nгуляли мы с Вами,\nвдоль пруда гуляли\nв старинном саду.\n\nВы помните это?\nТо самое лето,\nслучайное лето.\nБыл, вроде б, июнь.\n\nСвой камень на память,\nпрозрачный и серый,\nтакой дымно-серый,\nя Вам подарил.\n\nА Вы мне стрекозку,\nсо сломанной брошки,\nтой Вашей же брошки,\nчто кто-то сломал.\n\nХраните ли камень?\nМой гладенький камень,\nчто в графской усадьбе\nя Вам подарил...\n\nА Ваша стрекозка,\nвсё также без брошки,\nна беленькой полке\nв коробке лежит.\n\n01/07/15\nЯков Шахов"
 },
 {
  "id": "2015_06_22_4193",
  "title": "У Изборской крепости...",
  "genre": "без рубрики",
  "date": "22.06.2015 12:28",
  "url": "https://stihi.ru/2015/06/22/4193",
  "text": "У Изборской крепости\nлебеди плывут.\nТут в прохладной заводи,\nобрели приют.\nОн, она и птенчики\nшумною толпой...\n\n- Боже даст, невестушка,\nв лодочке с тобой,\nозерцом поплаваем,\nдеток заведём.\nНадо только, ладушка,\nсохранить наш дом.\nВороги коварные\nк крепости идут.\nВыстоим? Управимся?\nИль поляжем тут?\n\nДумал князь-молодушка,\nсидячи один.\nА вода холодная\nнеба тёмну синь,\nотражает звёздочки,\nмесяц, облака.\nЗачерпнула небушка\nмощная рука.\nКнязь испил водиченьки,\nбодрость обрести.\nМысли чтобы чистые,\nмудрые пришли.\n\n- Биться здесь, у крепости?\nМожно... Но тогда!\nУлетит ли лебедь сам?\nКак его семья?\nМожет, птицу лучше нам\nсетью изловить?\nДа за стену, в божий храм,\nсечу пережить.\n\nВдруг звезда на западе\nс неба сорвалась.\nСловно камушком вода,\nоживился князь.\n\n- Решено! Лишь солнышко\nвстанет, так сей час\nедем в чисто полюшко\nмы врагов встречать!\n\nУ Изборской крепости\nлебеди плывут.\nМинули столетия,\nа они всё тут.\n\n21/06/2015\nЯков Шахов\n\nТеги:"
 },
 {
  "id": "2015_05_05_3787",
  "title": "Антон Деникин песня",
  "genre": "эстрадная песня",
  "date": "05.05.2015 11:27",
  "url": "https://stihi.ru/2015/05/05/3787",
  "text": "Мелодия - Юлиан Барышников\nСлова - Яков Шахов\n\nОн покинул Россию\nво двадцатом году.\nКораблём морем синим,\nКрым оставив в дыму.\nА гражданская война,\nпустота и нищета,\nРазрушает отчий дом,\nразрывает нить времён,\n\nВот вдоль Сены в Париже\nбродит с дочкой своей\nникогда не увидит\nсердцу милых полей.\nА гражданская война,\nкак кровавая волна,\nчто смывает города.\nНе забудем никогда!\n\nДочь на руки сажает,\nей в глаза, он глядит.\nТа косичкой мотает,\nна руках не сидит.\nЗавещал он свой ей прах\nсхоронить в родных местах.\nЧтобы русские дожди\nкости мыть его могли.\n\nЛишь когда повзрослела,\nто отца поняла.\nЧто хранил  так заветно\nон в груди у себя.\nА гражданская война\nпусть не будет никогда!\nВосстановим связь времён.\nСбережём наш общий дом.\n\nапрель 2015 г.\nПетербург"
 },
 {
  "id": "2015_04_21_3297",
  "title": "Петербургская латина",
  "genre": "городская лирика",
  "date": "21.04.2015 10:37",
  "url": "https://stihi.ru/2015/04/21/3297",
  "text": "Сальса, бачата, кизомба и зук.\nВ ритме латины ночной Петербург.\n\nПламя восторга и страсти в глазах.\nКак на балу мы столетье назад.\n\nВместо каминного зала с паркетом,\nклубный танцпол под неоновым светом.\n\nПлатья на барышнях стали короче.\nВееров нет,  и движенья нестроже.\n\nФрак не отыщете на кавалере:\nджинсы, рубашка, фривольней манеры.\n\nА у парадной всех ждут не кареты,\nавтомобилей стоят километры.\n\nВместо швейцара на входе охрана.\nКучер-таксист отвезёт \"до дивану\".\n\nРаньше лакеи, теперь офицанты\nносят напитки, из фруктов салаты.\n\nРитмы эпоха меняет свои,\nвальс и мазурка - в архивной пыли.\n\nНовые танцы и новые звуки.\nЖивы и ныне балы в Петербурге!\n\n20.04.2015\nСанкт-Петербург"
 },
 {
  "id": "2015_04_08_4924",
  "title": "Терцины Данте",
  "genre": "без рубрики",
  "date": "08.04.2015 12:59",
  "url": "https://stihi.ru/2015/04/08/4924",
  "text": "Мне кажется, что в этом что-то есть.\nНе торопясь плести узор изящный,\nстроками образ излагая весь.\n\nДостойный стиль для мысли настоящей,\nидущей от начала, без конца.\nКак луч звезды, в просторы уходящий.\n\nДвиженье мысли сущего Творца...\nТерцина Данте из веков минувших\nдоносит тихий возглас мудреца.\n\nВо всех частях обетованной суши\nпо наши дни он теребит сердца.\nПоучимся и мы тревожить души!\n\nПод сенью мудрости Всевышнего Отца.\n\n08/04/15\nПетербург"
 },
 {
  "id": "2015_04_04_11483",
  "title": "Way of Humanity",
  "genre": "стихи на других языках",
  "date": "04.04.2015 22:26",
  "url": "https://stihi.ru/2015/04/04/11483",
  "text": "What is the way,\nwhich you go?\nWhat is the aim\nyou want?\nEveryone believes\nin his God,\nevery has a road.\n\nFor the Universe,\npeople are ants,\nhardly building\nthe hill.\nWhat is idea,\ngoal of them?\nFor which to create\nwe will?\n\nHumanity, please,\nopen your heart,\nfor every nations\nin world!\nIt's more\nbeautiful life\nthan only for money\nand gold.\n\n04/04/2015\nSt. Petersburg, Russia\n\nCreated by\nYakov Shakhov\nЯков Шахов"
 },
 {
  "id": "2015_03_24_783",
  "title": "Та, которая родила...",
  "genre": "любовная лирика",
  "date": "24.03.2015 01:43",
  "url": "https://stihi.ru/2015/03/24/783",
  "text": "Та, которая родила,\nта, что имя нарекла.\nТы меня ходить учила,\nплакал - на руки брала\n\nГоворить учился \"ма-ма\",\nпомнишь? Я вот позабыл...\nИли ту смешную \"драму\":\nманекен я завалил.\n\nКрикнул: \"Ой, какая тётя!\"\nИ за руку потянул.\nНу и тётя вертолётом\nоказалась на полу!\n\nПомнишь, как мне страшно было,\nслушать сказку при Луне.\nИ пластинку ты разбила,\nчтоб нестрашно было мне.\n\nА потом, года промчались,\nи живу я далеко.\nТолько вот всё то, в начале,\nвижу я легко-легко.\n\nМожет, скажет кто, мол: \"Грёзы.\nТо теперь уж не вернуть\".\nТолько, знаете... Берёзы.\nМама. Родина. Наш путь.\n\n24/03/2015"
 },
 {
  "id": "2015_03_18_4499",
  "title": "Льдинки",
  "genre": "любовная лирика",
  "date": "18.03.2015 12:27",
  "url": "https://stihi.ru/2015/03/18/4499",
  "text": "Одинокие льдинки\nпо Неве плывут.\nДля одной блондинки\nпосвящуэтюд.\n\nВешняя богиня,\nголубы глаза,\nлучик на картине\nсолнце в небесах.\n\nВот стою у льдины,\nчто на берегу,\nбосыми ногами\nв речку я войду.\n\nПогружусь три раза,\nулыбнусь. Назад.\nМир другим стал сразу.\nДивный райский сад!\n\nНичего, что Евы\nнет пока что в нём.\nК лету королева\nвозайдёт на трон.\n\nРядышком, на лавочке,\nна Неву смотреть,\nбудем, как соловушки,\nпро любовь мы петь.\n\nА пока блестящие\nпо реке плывут\nльдинки на картинке.\nВот и весь этюд.\n\n17/03/015\nПетербург"
 },
 {
  "id": "2015_01_26_4018",
  "title": "Мыслей рой",
  "genre": "философская лирика",
  "date": "26.01.2015 11:31",
  "url": "https://stihi.ru/2015/01/26/4018",
  "text": "Зимний вечер. Снег кружится.\nШпалы. Рельсы. Поле. Лес.\nДелать нечего. Не спится.\nСо второй я полки слез.\n\nПоезд наш, кометой яркой,\nнарушает тишину.\nПассажиры ждут стоянки.\nЧерез два часа - в Москву.\n\nТам полчасика подышим\nи поедем снова, в тьму.\nМысли роем рифмы ищут,\nкуст жасмина во цвету.\n\nКаждая, как пчёлка мёду,\nхочет миру дать стихов,\nчтоб рождались у народа\nмысли вновь от ритма слов.\n\nВидно, холодно и скучно\nим на улице зимой.\nВот и ищут лето в душах,\nу людей крадут покой.\n\n25/01/2015\nпоезд СПб - Елец"
 },
 {
  "id": "2014_11_21_521",
  "title": "Если вдруг разобьётся смартфон...",
  "genre": "философская лирика",
  "date": "21.11.2014 00:55",
  "url": "https://stihi.ru/2014/11/21/521",
  "text": "Если вдруг разобьётся смартфон,\nперекинуть смогу я контакты,\nне теряя практически данных,\nна свой новый, крутой телефон.\n\nА на старом оставлю я \"хлам\",\nгоры спама и фотки подруг.\nБрошу в ящик... Замкну этот круг.\nЖизни новый импульс придам!\n\nПочему же не веруют люди,\nчто душа, оставляя сей мир,\nустремится в прозрачный эфир?\nЛишь главу прочитав книги судеб.\n\n19-20/11/2014\nЯков Шахов\nПетербург"
 },
 {
  "id": "2014_11_07_3266",
  "title": "Пир с богами",
  "genre": "любовная лирика",
  "date": "07.11.2014 10:47",
  "url": "https://stihi.ru/2014/11/07/3266",
  "text": "В минуты вдохновений,\nоствавив тленный мир,\nк богам ты на Олимпе\nявляешься на пир.\n\nС ними возлегаешь\nза праздничным вином.\nи вовсе забываешь\nо бренном, о былом.\n\nТак ярок и ликующ\nоттуда мир, друзья!\nТак сердце полно чувством,\nчто и молчать нельзя!\n\n06.11.2014\nЯков Шахов"
 },
 {
  "id": "2014_11_06_4728",
  "title": "Ельчик",
  "genre": "пейзажная лирика",
  "date": "06.11.2014 13:05",
  "url": "https://stihi.ru/2014/11/06/4728",
  "text": "Как много в России реченек малых,\nзвонких ключей. безымянных ручьёв.\nВесной от снегов шумят они талых,\nк зиме затинают в предверии снов.\n\nКак люди простые, живут и не знают,\nчем труд их полезен великим морям.\nИ в реки побольше скромно впадают,\nа те - через море -\nв вечно живущий, в вечно бурлящий,\nогромный, глубокий и смелых манящий,\nлишь с Небом сравнимый -\nМировой Океан.\n\nОдна из таких, в европейской России,\nдревнюю правду в прохладе хранит,\nмудрость народа, могучую силу\nв нас пробуждает её колорит.\n\nКогда-то текла между сосен и елей,\nпоила, кормила людей и зверей.\nА ныне - забыта, и как-то несмело\nтечёт себе тихо, ничуть не быстрей.\n\nЕльчик... Как нежно журчит это имя!\nВ лесу и в долине, между бугров,\nв подножии храмов, даруя святыням\nпрозрачную свежесть своих родников.\n\nУ древнего града, он как и прежде,\nузенькой лентой тайну веков\nсвязует с грядущим,  вселяет надежду,\nчто Русь возродится, повергнет врагов.\n\n4-6.11.2014\nЕлец, Петербург\n(с) Яков Шахов"
 },
 {
  "id": "2014_10_19_11246",
  "title": "Давай поучимся у Бога",
  "genre": "философская лирика",
  "date": "19.10.2014 23:00",
  "url": "https://stihi.ru/2014/10/19/11246",
  "text": "Давай поучимся у Бога\nне обижаться на людей.\nУлыбкой чистой, без затей,\nсветиться солнцем с небосклона.\nДавай поучимся у Бога.\n\nДавай поучимся у Бога\nбыть каждому всегда своим.\nИ горе, радость вместе с ним\nделить, как сушу делит море.\nДавай поучимся у Бога.\n\nДава поучися у Бога\nмечтать огромными мечтами,\nидеи воплощать делами,\nстоять за Правду, словно горы.\nДаавай поучимся у Бога.\n\nДавай поучимся  бога...\n\n11/10/14\n(с) Яков Шахов"
 },
 {
  "id": "2014_10_19_8809",
  "title": "СнегоЛистоПад",
  "genre": "пейзажная лирика",
  "date": "19.10.2014 19:26",
  "url": "https://stihi.ru/2014/10/19/8809",
  "text": "СНЕГОлистоПАД\nВ середине осени\nвыпал первый снег.\nСловно с неба сбросили\nпепел сигарет.\n\nБудто над картиною,\nвознося хвалу,\nкто-то из художников\nобронил золу.\n\nЛистья и снежинки\nмедленно кружат...\nАх, какой случайный\nснеголистопад!\n\n19/10/14\n(с) Яков Шахов"
 },
 {
  "id": "2014_09_30_7940",
  "title": "Осенние берёзки",
  "genre": "пейзажная лирика",
  "date": "30.09.2014 19:50",
  "url": "https://stihi.ru/2014/09/30/7940",
  "text": "Как божественно шумят берёзки,\nцветом осени окрасив свой лист.\nЭкипаж - по булыжной дорожке\nкатит весело: на горку и вниз.\n\nЧерез реченьку мост перекинут.\nМы молчим, погрузившись в себя.\nМилый край деревенский покинут,\nкрай, где летом я встретил тебя.\n\nАнгела ты вышиваешь на пяльцах,\nя в окошко смотрю, на ландшафт.\n- Как божественно, милый братцы!\nТе березки вдоль речки шумят.\n\n29/09/14, Петербург\n(c) Яков Шахов"
 },
 {
  "id": "2014_08_20_8011",
  "title": "Снятся горы",
  "genre": "философская лирика",
  "date": "20.08.2014 19:55",
  "url": "https://stihi.ru/2014/08/20/8011",
  "text": "Мне каждую ночь снятся горы.\nРазнятся сюжеты и декорации сна,\nмелькают лица, сменяются разговоры.\nНеизменны лишь - наклон и высота.\n\nЧто значит символ вершины?\nКуда мне - вверх или вниз?\nВверху - одиночество и понарама долины,\nвнизу - суета и блеск водопадных брызг.\n\nВидимо, только красивым гордым птицам\nподвластен сей необычный простор -\nпарить на уровне ледника, что часто мне снится,\nи наслаждаться прохладой горных озёр.\n\nВот откуда такая сакральность\nнеровностей земли.\nВызов для обитателей равнин,\nиспытание их силы, символ истинной любви...\n\nГора - победа,\nгора - вдохновительница.\nМощи духа, мудрости красоты.\nСпасающая от скуки, утешительница,\nнадёжная хранительница,\nпространства верности и чистоты.\n\n(с) Яков Шахов\n20/08/14, Елец"
 },
 {
  "id": "2014_08_16_3464",
  "title": "Россия в сердце",
  "genre": "гражданская лирика",
  "date": "16.08.2014 12:00",
  "url": "https://stihi.ru/2014/08/16/3464",
  "text": "В Омске спели \"ом\",\nкупил \"Омичку\",\nпоклонились Иртышу.\nЕдем дальше транссибирским,\nдержим путь свой на Москву.\n\nТы, огромная Россия!\nКак тебя мне всю объять?\nВ сердце поместить святую,\nдабы чувствовать и знать.\n\nТретий день на скором мчимся,\nа вокруг - родная ширь:\nлес доемучий, степи, выси -\nсладка пища для души.\n\nВсё равно всё не опишешь:\nмир богаче всяких слов.\nРазгорается и дышит\nпламень в сердце - то любовь.\n\nПусть огонь сердец российских\nсветит ярче с каждым днём.\nИ закружат в вальсе быстром\nНарод и Родина -вдвоём.\n\n12/08/14\n(с) Яков Шахов"
 },
 {
  "id": "2014_08_15_7991",
  "title": "Встреча с Алтаем",
  "genre": "без рубрики",
  "date": "15.08.2014 19:48",
  "url": "https://stihi.ru/2014/08/15/7991",
  "text": "Навстречу утру, на восток,\nлечу я из Москвы.\nПрозрачна высь. Несёт поток\nв просторы чистоты.\n\nОбшивка лайнера блестит,\nзарёй озарена.\nМы за Уралом,\nздесь не спит\nлюбимая страна.\n\nКрасавица, борт-проводник,\nуже разносит чай.\nНу что ж, Алтай, мой новый друг!\nСкорей меня встречай!\n\n27/07/14\n(с) Яков Шахов"
 },
 {
  "id": "2014_07_25_3106",
  "title": "Сотворение",
  "genre": "басни",
  "date": "25.07.2014 10:55",
  "url": "https://stihi.ru/2014/07/25/3106",
  "text": "Когда-то Бог решил, шутя,\nвселенную вселить.\nИ завертелася крехтя\nгалактик звёздных нить.\nПланеты стали поперёк\nдвижения светил.\nИ вот тогда Господь изрёк:\n\"Да будет свет и мир!\"\n\"А где же дети будут жить?\" -\nвопрос тут прозвучал,\nтогда Отец, нахмуря бровь,\nсупруге отвечал:\n\"Планету детям мы дадим\nу маленькой звезды.\nА подрастут - тогда решим...\nЗаймись планетой ты!\"\n\"Ну ладно, так тому и быть,\nрешу я всё сама.\nПусть звёздочка та будет плыть...\nпусть будет так нежна...\nИ горсть планеток я ей дам,\nпусть крутятся вокруг.\nИ колыбель пусть будет там.\nЧто скажешь, милый друг?\"\n\"Родная, славная моя!\nПускай, да будет так!\"\nИ завертелися шутя\nпланеты плавно, в такт.\n\"Пускай на третьей поживут.\nПока ведь малыши.\nА там немножко подрастут,\nрешат где сами жить\".\n\n02/06/2014\n(c) Яков Шахов"
 },
 {
  "id": "2014_06_29_8541",
  "title": "Восторженность и честь",
  "genre": "философская лирика",
  "date": "29.06.2014 20:45",
  "url": "https://stihi.ru/2014/06/29/8541",
  "text": "Как много схем в уме, традиций,\nжеланий, целей, мыслей, догм.\nТот хочет сына и жениться,\nа этот грезит строить дом.\n\nНо, господа, позвольте малость...\nЖизнь есть сейчас, и ты живёшь!\nПардон-муа сию бестактность,\nно час придёт - и ты умрёшь.\n\nНе лучше ль то уже ценить,\nчто нам даровоно судьбою\nдышать, смеяться... Просто, жить.\nИдти вперёд своей тропою.\n\nЧто ж там, за поворотом, ждёт -\nмост в день или бездна ночи?\nТо вправду важно... То придёт...\nНо всё ж пока открыты очи!\n\nВозрадуемся, о други, Миру\nи примем в Нём всё так, как есть.\nАвось же, и клубам эфира\nмила восторженность и честь.\n\n28.06.2014\n(с) Яков Шахов"
 },
 {
  "id": "2014_06_04_6892",
  "title": "Новороссия, проснись!",
  "genre": "гражданская лирика",
  "date": "04.06.2014 17:46",
  "url": "https://stihi.ru/2014/06/04/6892",
  "text": "Харьков, Днепропетровск!\nНиколаев, Одесса!\nКировоград, Запорожье, Херсон!\nОдурманены вы западенскою прессой.\nЧто же нарушит ваш розовый сон?\nРазве не слышите плача Славянска?\nКак из-за взрывов взывает Донецк?\nГибнут на улицах дети Луганска.\nА ты всё спишь? Проснись наконец!\n\nВстань, Новороссия, гордо и смело!\nИ посмотри Галичине в глаза!\nЧто ты там видишь? Нацистское дело.\nне проронится скупая слеза.\nОни всё кричат о единой Украйне\nи не стыдятся бомбить города.\nС пафосом брызжут слюной на экране,\nтолько ввергая страну в никуда.\n\nМожет, и Центр проснётся когда-то,\nКиев - мать русских ведь, городов.\nДнепр поможет, помогут Карпаты,\nВ землях тех кости славных отцов.\nТак что проснись же скорей, Украина!\nПравду святую в душе пробуди,\nГоголя вспомни доброе имя,\nв русское царство сама приходи.\n\n03/06/14"
 },
 {
  "id": "2014_06_02_382",
  "title": "Девять",
  "genre": "философская лирика",
  "date": "02.06.2014 00:39",
  "url": "https://stihi.ru/2014/06/02/382",
  "text": "Чуть к свету прикасаюсь\nи вновь я в тьму спешу.\nВроде б пробуждаюсь,\nкак снова вдруг грешу...\nРазомкну я окружность.\nобразую спираль.\nИз плоскости тлена -\nв пространство!\nК звёздам! Вдаль!\n\n01/06/14\n(c) Яков Шахов"
 },
 {
  "id": "2014_05_29_3979",
  "title": "Разбиваясь о скалы разврата...",
  "genre": "мистика и эзотерика",
  "date": "29.05.2014 11:53",
  "url": "https://stihi.ru/2014/05/29/3979",
  "text": "Разбиваясь о скалы разврата,\nволны чувств обращаются в сперму.\nи питают порока систему.\nиспаряясь в простор суеты\nпод лучом отражённого света.\n\nТак живут города...\nИх немало в царстве подлунном.\nКто же царь над толпами безумных?\nВ чём же смысл бытия этих стай?\n\nИли битва идёт?\nЗа тела и за души.\nЧтоб в сердцах пробудился огонь.\nЧтобы смысл обрели бы\nуставшие души.\nЧтобы зверя поверг наконец-то Господь.\n\nБейся Дух!\nНаш спаситель, один утешитель.\nДа обрящешь Ты силу и славу в бою.\n\n28.05.2014"
 },
 {
  "id": "2014_03_24_11708",
  "title": "Скрипачка",
  "genre": "гражданская лирика",
  "date": "24.03.2014 23:38",
  "url": "https://stihi.ru/2014/03/24/11708",
  "text": "Минорная гармония,\nаккордами слагаясь,\nгрустинку мироздания\nс собою принесёт.\nИ сердце затрепещет,\nа души зарыдают,\nкогда, смычком касаясь,\nпо струнам проведёт.\n\nКрасавица чудесная...\nМелодия неспешная...\nВ едином сочетании\nрастрёпанных волос.\nВ порыве вдохновения,\nсердечное томление\nи слёзы на ресницах -\nне в шутку, а всерьёз.\n\nСплетая во единое\nлюдские настроения,\nона, богиня мудрая,\nдарует красоту.\nРосой омоет помыслы,\nвдохнёт прохладу вешнюю,\nпокажет мыслям будничным\nмасштаб и чистоту.\n\nИграй скрипачка, милая,\nпрелестная кудесница!\nВозрадуй души страждущих,\nизмученных людей!\nИ верю, лирой чистою,\nгармонией божественной,\nпробудишь смыслы вечные\nдля жизни без затей.\n\n24.03.2014\n(с) Яков Шахов"
 },
 {
  "id": "2014_03_21_111",
  "title": "Утренняя пробежка. Мартовская зарисовка",
  "genre": "пейзажная лирика",
  "date": "21.03.2014 00:07",
  "url": "https://stihi.ru/2014/03/21/111",
  "text": "Проснувшись утром, кросс бежал\nя вдоль Невы заледенелой.\nХрустели снежные аллеи,\nа в небе ясном Ра сиял.\n\nЛёд на реке блестел алмазом.\nКружили чайки над водой\nи бились сильно головой,\nзавидя рыбу зорким глазом.\n\nГуляли люди тут и там.\nВалялись псы в пушистом снеге.\nВсё было сказочно на бреге...\nПредстала явь подобна снам!\n\nИ я бежал, дыша свободой\nсердечно веруя мечте...\n\n20.03.14\n(с) Яков Шахов"
 },
 {
  "id": "2014_03_17_719",
  "title": "Сознательный онтос Родины",
  "genre": "эссе и статьи",
  "date": "17.03.2014 01:19",
  "url": "https://stihi.ru/2014/03/17/719",
  "text": "Как учит нас философское учение, именуемое онтологией, каждое явление, представленное в феноменологии жизни, имеет онтологическое (бытийное, сутевое) основание. Так, например, человеческое \"я\" в разных религиозных традициях трактуется как душа, часть Единого Бога, сознательного начала Мира.Следует полагать, что понимание сущностной основы явления гарантирует нам осмысление и его следствий, отражений, проявления в жизни. Так, например, онтопсихология, вслед за многими учениями древности, призывает человека познать себя. \"Познав своё \"я\", ты\nобретёшь смысл своей жизни, поймёшь судьбу\".\n\nКакие ещё явления жизни имеют сознательный онтос, такой же, как \"я\" человека? Язычники говорили, многие: солнце, земля, ветер, река. Они обожествляли эти\nявления природы. Отправляясь в морской поход. пытались \"договориться\" с богом-покровителем морской стихии. Желая получить хороший урожай, просили об этом бога солнца или богиню плодородия. Однако, если бытийную суть (онтос) имеют всеявления нашей жизни, может, не столь безосновательны и наивны были мольбы наших предков к богам?\n\nВ культуре русского народа есть ещё одно явление жизни, которое имеет свой\nсознательный онтос, своё \"я\". Это наша Родина, матушка Россия! Именно матушка, родная и заботливая к своим детям и строгая, разящая мечом своих врагов. В дни испытаний, судьбоносных вызовов, стоящих перед Ней, Её мудрость, сила и любовь так ясно ощутимы... Родина наша, мы любим тебя!\n\n16.03.14\n(с) Яков Шахов"
 },
 {
  "id": "2014_03_12_272",
  "title": "Стоящая у края",
  "genre": "гражданская лирика",
  "date": "12.03.2014 00:21",
  "url": "https://stihi.ru/2014/03/12/272",
  "text": "Чем помочь тебе? Стоящая у края,\nстрана, когда-то колыбель Руси.\nНарод твой, сам того не зная,\nпо уши душу изморал в грязи,\nв надеждах эфемерности нелепой\nпризнанья от Европы получить.\nАмерике, как пёс, готов служить.\nЗабыл он Русь и подвиг дедов…\n\nИгра за земли те давно ведётся!\nИ злобный карла в Альпах смеётся!\nКак одурачил, охмурил.\nНарод истории лишил.\nКак брат на брата натравил!\nИ златом ярким ослепил...\n\nТы Днепр спроси!\nБыть может, он расскажет\nо подвигах былых славян.\nФранцузов, орды турок, англичан,\nтебе он лики их покажет,\nот Дона павших до Балкан.\n\nНапомнит он, как от Полтавы\nфашистов гнали за Дунай.\nУвенчаны мы общей славой!\nМой брат хохол, ты это знай!\nВодой днепровской ты умойся\nи грязь коричневую смой!\nДа будет мудрость, Бог с тобой!\nА нас, москаликов, не бойся!\nЕдиной будем мы семьёй.\n\n11.03.14"
 },
 {
  "id": "2014_03_04_11055",
  "title": "Русский царь",
  "genre": "гражданская лирика",
  "date": "04.03.2014 23:19",
  "url": "https://stihi.ru/2014/03/04/11055",
  "text": "Царь державный, русский царь!\nМудрый славный государь.\nТы сплотил Россию нашу,\nвоспылала Духа чаша.\nИ настало время Russian\nв мире новом, яко встарь.\n\nПосле долгого ночлега\nверный конь предался бегу\nПо полям, лесам и горам,\nвеселясь души простору.\nВсё покорно его взору…\nМысль прозрачна, как янтарь.\n\nПобедит российский дух\nнедругов своих вокруг\nи обрящет ярку славу,\nяк спаситель величавый.\nЛяжет сердце на алтарь.\nБог един! И Он наш царь.\n\n04.03.2014"
 },
 {
  "id": "2014_02_28_594",
  "title": "Весна в феврале",
  "genre": "пейзажная лирика",
  "date": "28.02.2014 00:56",
  "url": "https://stihi.ru/2014/02/28/594",
  "text": "Ускоряется эра прогресса.\nВремя скачет галопом вперёд.\nСредь миров бродит дух Ахиллеса,\nза собою смелых ведёт.\n\nСпали люди, кошки, собаки.\nБоги придали импульс Земле.\nПровернулся вдруг круг зодиака,\nи весна началась в феврале.\n\nУтром я иду на работу.\nСветит солнце в морозном дыму.\nПтички щебетом будят кого-то.\nДети сонные в школу бредут...\n\nЛужи – льдинки. К полудню растаят,\nА уж к вечеру – нет и следа.\nТак весною ранней бывает...\nОтмеряет года нам весна.\n\nНа минутку предавшись печали,\nбрось её! Посмотри, как кругом,\nвсё наполнено силой, началом,\nпробуждением в мире живом.\n\nИ почувствовав ритмы природы,\nя иду бодрей по дороге,\nутром зимним с весенней погодой,\nчто придумали мудрые боги.\n\n27.02.2014\nПетербург"
 },
 {
  "id": "2014_02_18_1197",
  "title": "От Примы до Рыбы...",
  "genre": "философская лирика",
  "date": "18.02.2014 01:58",
  "url": "https://stihi.ru/2014/02/18/1197",
  "text": "От «Примы» до «Рыбы»* колёса стучат,\nи сердце моё стучит невпопад.\nО многом, о разном летят в голове\nмысли о Боге, о смысле, судьбе.\nСойду на конечной, увижу я свет.\nВсе люди когда-то получат ответ.\nО многом, о разном, о чём невпопад\nмысли, как стрелы, куда-то летят.\n\n17.02.2014\n_______________\n* «Прима» - «Приморская», «Рыба» - «Рыбацкое» - первая и последняя станции зелёной ветки Петербургского метро."
 },
 {
  "id": "2014_02_14_5215",
  "title": "Музе",
  "genre": "любовная лирика",
  "date": "14.02.2014 13:17",
  "url": "https://stihi.ru/2014/02/14/5215",
  "text": "Как будто ото сна просыпаюсь,\nзорким взглядом смотрю я на мир,\nвстречным девушкам всем улыбаюсь,\nа с мужчинами горд, как Сатир.\nДо чего же хорош вечер юга!\nМы гуляли всю ночь при Луне,\nна яву ты со мной – не во сне,\nмилая сердцу, родная подруга.\nМудрость жизни вижу в тебе.\n\n11.02.2014"
 },
 {
  "id": "2014_02_12_10226",
  "title": "Статуэтка Маяковского",
  "genre": "басни",
  "date": "12.02.2014 20:51",
  "url": "https://stihi.ru/2014/02/12/10226",
  "text": "Гуляли два друга вечерней порой\nпо невской центральной аллее.\nОдин был учитель, был препод другой.\nОгни вдоль проспекта горели.\n\nВ столовой покушать второй предложил.\nУ первого не было денег.\n- Пойдём, я плачу... Надо есть, чтобы жить.\n- О’кей. Я отдам, когда получу!\nЗашли они в «Северный берег».\n\nПоели. На улицу снова пошли.\nУ первого мысль появилась:\n- Напьёмся, дружище?! Чего ты молчишь?\nВторой отказался уныло.\n- Да ладно, давай!\n- Нет! Сказал, не хочу!\n- Ну что же, тогда будем делать?\n- Пойдём на метро, я домой покачу!\nНа завтра есть важное дело.\n\nИдут они мимо «Перинных рядов»,\nтут первый зайти предложил:\n- Там много есть всяких красивых холстов,\nМою бы картину купил?\n- Ты вряд ли сумел бы…\n- Смотри, как там круто! -\nзашёл в сувенирную лавку.\nИ вышел обратно, за четверть минуты:\n- Домой! Я читать буду Кафку.\n\nОн левой рукою из сумки достал,\nфигурку высокого роста.\n- Смотри! Маяковский... Его я украл.\nТо сделать мне было так просто!\n- Ты что?  Охренел?!\nКакой же позор!\nУчитель ты! Или Забыл?\nТут первый глазёнки свои опустил\nно пылом ещё не остыл:\n- Буржуи они!\nИ я не дурак,\nвсего лишь простой клептоман...\nНу ладно верну... Дурманит кураж.\nВедь ты же руки не подашь.\n\nВернул статуэтку он эту на место.\nПрощаясь, руки не подав,\nвторой лишь замел:\n- Добьёшься ареста.\nПарниша, дурить перестань!\n\nВот так распрощались.\nНа том и расстались.\nИ что же сказать мне в конце?\nНаправил куда ты, дружок, социальной\nидеи сей басни прицел?\n\nУ нас пост-модерн. Всё смешалось кругом,\nкак в доме несчастных Облонских:\nУчитель и вор. И кто прав, и кто горд.\nПорок, благодетель, позёрство.\n\nНо всё же под кожей, глубоко внутри\nживёт в нас то чувство, которым\nмы знаем, добро или зло мы творим,\nи счастье, которого стоим.\n\n11/02/2014\nПетербург"
 },
 {
  "id": "2014_02_11_5416",
  "title": "Гитара Гарсиа Лорки",
  "genre": "поэтические переводы",
  "date": "11.02.2014 13:53",
  "url": "https://stihi.ru/2014/02/11/5416",
  "text": "“La guitarra” de Federico Garcia Lorca\nфривольный перевод с испанского\n\nАккорд раздаётся\nгитарный.\nПламенеет огонь\nв тумане рассвета.\nАккорд раздаётся\nгитарный.\n\nТы замыслил что-то\nковарно.\nО бойся, мой враг,\nковарный!\n\nКак суша боится моря.\nКак ветер срывает крыши,\nпитаясь силой простора.\nО бойся. мой враг,\nковарный!\n\nПоёт моё сердце,\ncлышишь?\nПожаром кровавой битвы.\nПоёт моё сердце,\nвыше,\nот стрел улетают\nптицы.\n\nАккорд раздаётся\nгитарный.\nДа здравствует\nпламя битвы!\nАккорд раздаётся\nгитарный.\n\nПобеды достоин\nсильнейший.\n\nянварь-февраль 2014 г."
 },
 {
  "id": "2014_02_04_12029",
  "title": "Клубника на пляже",
  "genre": "любовная лирика",
  "date": "04.02.2014 22:18",
  "url": "https://stihi.ru/2014/02/04/12029",
  "text": "* * *\nТы помнишь то утро, на пляже в Египте?\nМы ели клубнику и грелись в лучах.\nТы в шляпке сидела и звонко смеялась.\nРазлука настанет всего через час.\n\nВот ты улетела на птице железной,\nв одну из далёких холодных столиц\nА солнце всё также в лазури небесной…\nПомеркли улыбки знакомых мне лиц.\n\nНо завтра настало, и я в самолёте,\nпоближе стал к солнцу, лечу за тобой\nДушою и телом, я с верой в полёте,\nи рад как безумный, что еду домой.\n\nПриехав в твой город, был встречен зимою,\nИ шапку надел, облачился в пальто,\nНо сердце стучало, горело тобою,\nУлыбкой светился, ехал в метро.\n\nИ здесь, средь метели, в далёкой России.\nЯ вижу то утро в лазурных лучах,\nНа пляже сидели и ели клубнику..\nВсё помнится ясно, сейчас при свечах.\n\n1-2 февраля 2014 г.\nсамолёт Хургада – Москва,\nСанкт-Петербург"
 },
 {
  "id": "2014_02_03_11881",
  "title": "Молитва во спасение. Акростих",
  "genre": "религиозная лирика",
  "date": "03.02.2014 22:19",
  "url": "https://stihi.ru/2014/02/03/11881",
  "text": "Боже милостливый, милосердный!\nОгради рабыню свою\nГоречи всякой, от скверны, и\nДаруй мне силу твою!\nАллилуйя спою на рассвете,\nНа икону Христа помолюсь.\nОтче наш! Мы все твои дети.\nВерю... И знаю - спасусь!\nОбогрей своею любовью\nИ надежду мне подари.\n\nА я сердцем буду с тобою,\nЛегче мыслить, когда ты внутри.\nЛучезарный Творец мирозданья!\nЕсмь я! Я есмь твоя дочь.\n\n25/01/2014\n__________\n\n¬¬____\n\nАкростих. Первыми буквами по вертикали – Богдановой Алле – адресату стихотворения."
 },
 {
  "id": "2014_01_20_10769",
  "title": "Шоколадка и смысл жизни",
  "genre": "шуточные стихи",
  "date": "20.01.2014 20:46",
  "url": "https://stihi.ru/2014/01/20/10769",
  "text": "Я ем шоколадку, мне сладко вполне,\nа жизнь – непонятная штука!\nВ каком измеренье, в какой глубине\nтаится та тайна науки?\n\nЧтоб смысл постигнуть её величавый,\nс судьбою оставшись в ладу.-\nСветило бы солнце, топило б печали.\nЯ словно в каком-то бреду\nкуда-то бреду... Направляюсь откуда?\nКто может мне то подсказать?\nКем был я когда-то и кем ещё буду?\nИ нужно ли всё это знать?\n\nСоздатель молчит: он сказал уже всё\nтвореньем своим и лишь смотрит,\nкак мы все читаем посланье его,\nзакон о любви и пороках...\n\nЯ ем шоколадку, мне сладко вполне.\nДа, жизнь - очень милая шутка\nтого, Кто улыбкой в своей вышине\nбезмолвно сияет всем людям.\n\n20/01/2014\nПетербург"
 },
 {
  "id": "2014_01_20_9967",
  "title": "Сердце молчит, а ум не спешит",
  "genre": "верлибр",
  "date": "20.01.2014 19:46",
  "url": "https://stihi.ru/2014/01/20/9967",
  "text": "Как захочу, так всё и будет!\nА как хочу? – Вот он вопрос.\nВозможно, скажут «Не дорос!»,\nУставшие, но умные люди,\nзабывшие о дурмане грёз.\n\nНу что ж! Придётся самому\nРешать и ставить все задачи.\nБродя по свету одному,\nПредавшись ветреной Удаче…\nКак больно, тихо сердце плачет.\n\nИ плач тот в сердце раздаётся,\nКак будто нет его…\nИ кто-то смеётся.\nТишина. Молчанье.\nЧто делать? Не знаю!\n\nВсё вроде хорошо!\nНо что-то мешает.\nЧто-то делать надо!\nА что? Не знаю.\n\nПускай без синтеза пока останется сия проблема\nВозможно, надо так.. Пускай не решена дилемма!\nА время, быть может, всё само расставит, решит!\nТак что сердце моё молчит, а ум не спешит.\n\n20/01/2014"
 },
 {
  "id": "2014_01_11_13819",
  "title": "Другу. Акросонет",
  "genre": "акростихи",
  "date": "11.01.2014 23:53",
  "url": "https://stihi.ru/2014/01/11/13819",
  "text": "В каждом из нас – суть мирозданья,\nИ-стины свет, лучезарный огонь.\nТ-репет восторженный, очарованье.\nА-нгелов сонмы даруют нам бронь.\nЛ-юди живут, забывая про это,\nИ порождают свою круговерть.\nЮ-г или север? – Все части света!\n\nГ-ибнут от скуки, неверья, потерь.\nА ты мечтай! Устремись за мечтою!\nМ-ир озарится твоею душой!\nЕ-сли наполнится жизнь красотою,\nЕ-хать, лететь ли дорогой прямою\nВ-есело будет ранней зарёю\nУ-пряжью звонкой, за яркой звездой.\n10/0114   Елец\n____________________\n\n* Первые буквы строк по вертикали - \"Виталию Гамееву\" моему другу на его день рожддения."
 },
 {
  "id": "2013_12_04_487",
  "title": "Чувства в начале зимы",
  "genre": "любовная лирика",
  "date": "04.12.2013 00:42",
  "url": "https://stihi.ru/2013/12/04/487",
  "text": "Однажды осень завершилась,\nпришла зима и с ней метель.\nВсё забелело, закружилось.\nКого-то жду в свою в постель.\n\nМне холодно, душе тоскливо,\nстихами разгоняю сон.\nОна мятежно молчалива.\nНо может, я в неё влюблён?\n\nНочь и зима – её природа.\nДуша волнуется в тиши.\n– Погода будет, непогода…\nНадейся радуйся, дыши!\n\nМой ум внушает радость мне,\nа сердце трепетно тревожно.\nНо на яву, как и во сне,\nжить счастливо я знаю можно!\n\n04/12/2013"
 },
 {
  "id": "2013_12_04_454",
  "title": "Летать выше",
  "genre": "мистика и эзотерика",
  "date": "04.12.2013 00:40",
  "url": "https://stihi.ru/2013/12/04/454",
  "text": "Как-то живу,\nЧто-то пою,\nИногда люблю,\nЧаще вою.\n\nМир мой прост,\nНо есть вопрос.\nКто я?\nИ что я стою?\n\nГде ты мой путь?\nСчастлив будь!\nКак отыщу – увижу.\n\nТы далеко.\nМне нелегко.\nНо я пою,\nи миссия ближе.\n\nСлышишь меня, мой Бог?\nДелаю новый вздох.\nЯ отыщу тебя, слышишь?\n\nСердце поёт в ночи!\nНу же! Не молчи!\nБуду летать выше.\n\n04/12/13"
 },
 {
  "id": "2013_12_03_11192",
  "title": "Мысль огненная",
  "genre": "философская лирика",
  "date": "03.12.2013 23:19",
  "url": "https://stihi.ru/2013/12/03/11192",
  "text": "Водою акварель разбавишь,\nкоснёшься кистью полотна…\nЧто ты напишешь? Угадаешь?\nИль мысль сама вольна твоя?\n\nО чём молчишь, о чём томишься?\nЯ вижу сердцем твою грусть.\nЗима пришла, метель кружится,\nНа небе солнце скрыто пусть.\nМороз ещё сильней ударит\nи прояснится наконец.\nМир озарится, жизнь подарит.\nЛикуй и радуйся, творец!\n\nМятежный ум нам сердце ранит.\nПорой уныние царит.\nНо… Сердце мудро, сердце знает,\nоно огонь в себе хранит.\nЧтоб обогреть в часы ненастья\nи осветить лукавый ум,\nЧтоб веру возродить и счастье,\nПронзить печаль упрямых дум.\n\nПускай мелодия поёт,\nИ в ней гармония играет.\nА счастье есть, оно придёт.\nМысль огненная э т о знает!\n\n01/12/2013"
 },
 {
  "id": "2013_03_22_11751",
  "title": "Хокку. Стилизация",
  "genre": "рубаи, хокку, танка",
  "date": "22.03.2013 23:02",
  "url": "https://stihi.ru/2013/03/22/11751",
  "text": "(в соавторстве с Артёмом Шнуровым)\nУзреть мгновенье.. Запечатлеть его в трёх строках…\n\nМандариновое древо.\nСорвавшийся плод.\nДорожка сада.\n***\nПребывающий поезд.\nМелькание вуали.\nОблачность воспоминаний.\n***\nПагода в лучах заката.\nКрадущийся тигр.\nИкебана огня.\n***\nПоцелуй ветра.\nШуршание травы.\nПарханье бабочки.\n***\nШёпот леса, птица.\nВзмах крыла.\nУлетающая трясогузка.\n***\nХижина отшельника.\nГнездо журавля на крыше.\nИероглиф мудрости.\n***\nНить шёлка.\nПрохлада росы.\nВосход солнца.\n***\nБлеск луны.\nВ чаше – вишни лепесток.\nПлеск волны.\n***\nСтебель бамбука в саду камней.\nПорыв юности.\nУтренняя заря.\n***\nБеспечность волн.\nОбъятье скал.\nСонм жемчужин\n***\nВысотки Йокогамы.\nОтражённый свет.\nСозерцание начала.\n***\nСакура в саду Киото.\nУлитка на корне древа.\nПробуждение.\n***\nМокрый асфальт.\nСтремительный поток.\nЧайка в небе.\n***\nПолуденный зной.\nБлагодатный ливень.\nТишина.\n***\nПучина, рождающая свет.\nПервый блеск зари.\nТоржество жизни.\n***\nВагон метро.\nШелест глянца.\nЯркость фантазий.\n***\nВзмах веера.\nКокетство глаз.\nМерзанье звёзд.\n***\nПеснь соловья\nв утреннем тумане.\nТаянье грёз.\n***\nЛазурь Окинавы.\nЧайка, рассекающая волну.\nРыба в цепких лапах.\n***\nДикая орхидея\nна горном склоне.\nПолёт стрекозы.\n***\nЗеркальный пруд.\nУстремлённость к облаку.\nПеро на воде.\n***\nСнежная шапка на ветке ели.\nЗерно риса на чаше весов.\nПаденье и взлёт.\n***\nДревний храм.\nБезмятежный взор.\nБлагословение.\n\n07-09/03/2013"
 },
 {
  "id": "2013_03_22_11670",
  "title": "Призыв к Ветру",
  "genre": "любовная лирика",
  "date": "22.03.2013 22:56",
  "url": "https://stihi.ru/2013/03/22/11670",
  "text": "Ветер призрачный, несущий\nмиру радость вдохновенья!\nТы меня узри, певучий,\nи даруй Любви томленье!\nЛишь Её коснусь украдкой,\nзаживу я с новой силой.\nРазрешу я все загадки,\nчто так долго в сердце были\nПолетим с Душою вместе\nмы в неведомые дали,\nпривезём дары невесте,\nчто растопят все печали,\nС нею в танце мы закружим…\nВетер, слышишь?! Я скучаю!\nПрилетай скорее, ну же!\nБез Любви я прозибаю…\n\n17/02/2013"
 },
 {
  "id": "2013_03_22_11573",
  "title": "Потеряв потребность притворяться...",
  "genre": "философская лирика",
  "date": "22.03.2013 22:48",
  "url": "https://stihi.ru/2013/03/22/11573",
  "text": "Потеряв потребность притворяться,\nобретает творчество творец.\nВсе в округе начинают удивляться,\nвозлагают на его чело вечец.\n\nОн поёт, лучами озарённый,\nвдохновлённый радостью сердец,\nнежным трепетом немного утомлённый,\nрайской музыки, гармонии певец.\n\n17/10/2012"
 },
 {
  "id": "2012_01_17_4905",
  "title": "Из гусениц в бабочки",
  "genre": "философская лирика",
  "date": "17.01.2012 12:59",
  "url": "https://stihi.ru/2012/01/17/4905",
  "text": "Всё не всерьёз,\nИль всё весьма серьёзно –\nВот две основы бытия?!\nКак Жизнь прожить,\nЧтоб не курьёзно?\nЧтобы со Смыслом шла она.\n\nЗаветы ль мудрые искать?\nСобытий в сути погружаться?\nЧто делать и о чём мечтать,\nСебе чтоб верным оставаться?\n\nСебе?\nБыть может, в том причина?!\nСебе служить всегда хотим!\nМы бережём свою личину…\nИ по тому ползём,\nА не  летим!\n\nКак бабочкой из гусеницы стать?\nПорхать и радоваться свету…\nПопробуем-ка Сердце испытать…\nЧерез Него придём к ответу!\n\n17/01/2012"
 },
 {
  "id": "2012_01_16_7396",
  "title": "МайаТа",
  "genre": "философская лирика",
  "date": "16.01.2012 18:17",
  "url": "https://stihi.ru/2012/01/16/7396",
  "text": "Мы занять себя стремимся,\nвечно что-то нужно нам…\nТем, что делаем, – гордимся,\nлюбим, жаждем, веселимся…\nОпускаемся до драм…\n\nДушу мы совсем забыли…\n–  Ти-и-ше! Нам не до неё!\nКто мы есть? И кем мы были?\nПохотливые, все в мыле…\n– Что за вздор! Что нам с того?\n\nВажно нам, чтоб было в норме…\nВсё, как все! А где же ты?\nДумаешь о моде, корме,\nотношениях, о форме?\nГде же место для мечты?\n\nБез неё ведь очень тускло\nжить, дышать, радеть.\nЛишь по ней отыщем русло,\nчтобы к Богу плыть радушно,\nа не просто помереть!\n\nЦарство Майи мы оставим,\nустремим, свой взор в себя.\nТам отыщем, распознаем,\nсвоим сердцем ощущаем\nНас-Таящие Дела!\n\n16/01/2012"
 },
 {
  "id": "2011_12_06_3893",
  "title": "Любовь к Родине",
  "genre": "гражданская лирика",
  "date": "06.12.2011 12:33",
  "url": "https://stihi.ru/2011/12/06/3893",
  "text": "Хорошее протестом не построишь!\nЭмоциям предавшись, лишь только\nсам сгоришь!\nДобро ты в мире бунтом не устроишь.\nОстановись! Подумай, что ты, друг,\nтворишь!\nКуда ввергаешь ты Россию,\nКуда зовёшь других идти?!\nКто из толпы творит стихию,\nчтоб всё сметала на пути?!\nТы – вольный человек! Тебе решать,\nчто будет дальше в твоей Жизни!\nНо чтоб нам бед не испытать,\nтвори, мой друг, Любовь к Отчизне!\n\n06/12/2011"
 },
 {
  "id": "2011_11_29_5219",
  "title": "Иерархия Света, иерархия Тьмы",
  "genre": "мистика и эзотерика",
  "date": "29.11.2011 15:00",
  "url": "https://stihi.ru/2011/11/29/5219",
  "text": "* * *\nИерархия Света, иерархия Тьмы –\nразличим два понятья!\nНаступленье весны\nзнаменуется новым началом Всего.\nМы размерим, конечно ж,\nгде добро, а где зло!\nУстремимся душою по ступеням\nмы ввысь,\nчтобы помыслы наши с Любовью\nслились!\n29/11/11"
 },
 {
  "id": "2011_10_04_5021",
  "title": "Актёрство Души",
  "genre": "мистика и эзотерика",
  "date": "04.10.2011 15:19",
  "url": "https://stihi.ru/2011/10/04/5021",
  "text": "Душа-актриса, в тело воплощаясь,\nна сцену-Землю сходит поиграть.\nИ в роли разные в Игре вживаясь,\nЛюбовь стремится и себя познать.\n\nСудьба-сценарий совести подвластна,\nа чувство такта ведает успех.\n«Благая» ложь и фальшь  – опасны,\nтрактуются они как смертный грех.\n\nДуша играет, декорации меняя,\nпоёт, наперекор Вселенной всей,\nстрадая иль в восторге пребывая,\nот роли к роли становясь смелей.\n\n03/10/2011"
 },
 {
  "id": "2011_09_13_6014",
  "title": "Лесная фея",
  "genre": "иронические стихи",
  "date": "13.09.2011 18:31",
  "url": "https://stihi.ru/2011/09/13/6014",
  "text": "В берёзовой роще гуляла колдунья,\nвенок заплетала девчонка-шалунья\nцветков золотых, одуванчиков свежих, –\nбыстро шло дело в руках её нежных.\n\nВот всё и готово, корона поспела!\nЛесная прелестница, добрая фея,\nукрадкой идёт, озорно улыбаясь,\nвзоров случайных в лесу опасаясь.\n\nВедь если увидит её кто-то внешность,\nто вмиг испытает мира безбрежность!\nПадёт зачарованный наземь живую\nиль деревом станет, и скажет: «В Раю я»!\n\nВот так и живёт, людей избегая,\nПрекрасная, жгучая, полунагая… ;\n\n13/09/2011"
 },
 {
  "id": "2011_09_01_4131",
  "title": "Осень пора лирики",
  "genre": "философская лирика",
  "date": "01.09.2011 13:36",
  "url": "https://stihi.ru/2011/09/01/4131",
  "text": "Пора Любви, пора мечтаний,\nпора восторженных речей!\nИ сердца новых трепетаний,\nпора надежд… Пора дождей!\nПора спокойствия и веры,\nпора… Мой друг, пора!\nНа крыльях сладостной Венеры,\nсвои оставив номера,\nлететь Душой и не бояться\nмасштаба собственной Мечты!\nВ лицо опасности смеяться,\nлюбуясь Миром с высоты.\n\nВ часы Природы увяданья,\nна миг лишь с Нею погрусти…\nИ прочь сомненья, ожиданья…\nЛети! Мечтай! Живи! Свети!\n\n01/09/2011"
 },
 {
  "id": "2011_03_12_3760",
  "title": "Казачья зарисовка",
  "genre": "пейзажная лирика",
  "date": "12.03.2011 12:45",
  "url": "https://stihi.ru/2011/03/12/3760",
  "text": "Воля вольная,\nстепь раздольная!\nНебо ясное,\nсолнце красное!\nПо степи лечу\nна лихом коне!\nРусский край храню,\nчтоб не быть войне!\nТы лети, мой конь,\nразудалый друг!\nВ лето знойное,\nот февральских вьюг!\n\n12/03/2011"
 },
 {
  "id": "2011_02_07_4347",
  "title": "Тетраэдр любви",
  "genre": "любовная лирика",
  "date": "07.02.2011 13:36",
  "url": "https://stihi.ru/2011/02/07/4347",
  "text": "Он и она… И есть ещё один он…\n\n– Зачем в мой город ты приехал,\nзачем стихи мне посвящал?\nВ любви с ним нашей ты помеха,\nты всё напутал, намешал!\nСебе любовь ко мне придумал,\nведь я ж не чувствую её!\nВорвался в жизнь, наделал шума,\nценя лишь мнение своё!\n\nБыть может, так и было вправду,\nбыть может, нет – им Бог судья!\nНо только он, не помня правил,\nсидел, молчал, смотрел любя.\n\n– Не знаю я, зачем приехал,\nзачем в твою ворвался жизнь.\nСказало сердце: «Надо ехать!»,\nдуша отправилася ввысь.\nРассудок принял то, как данность,\nлишь оптимально стал решать.\nПрости меня за эту странность,\nчто жить хочу, любить, дышать!\n\nПотом ещё они болтали.\nпотом уехал он домой.\nЧто дальше будет, то не знали,\nпокой иль в омут с головой.\n\nА Жизнь, конечно, всех рассудит,\nей это делать не впервой.\nЛюбовь двоим светить лишь будет\nс вершины яркою звездой!\n\n07/02/11"
 },
 {
  "id": "2011_01_20_3356",
  "title": "Любимая моя акростих",
  "genre": "акростихи",
  "date": "20.01.2011 12:06",
  "url": "https://stihi.ru/2011/01/20/3356",
  "text": "Л   -етаю я душою по ночам,\nЮ   -жный край и север изучаю,\nБ   -огам молюсь\nИ   гимны воспеваю –\nМ   -ир предстаёт моим очам!\nА   утром снова просыпаюсь,\nЯ   в быт привычный возвращаюсь…\n\nМ   -ечта, что ночью зародилась,\nО   той, которая приснилась,\nЯ   -рка и властна надо мной!\n\n20/01/2011"
 },
 {
  "id": "2010_12_31_6734",
  "title": "Под звуки вальса и бокалов с соком звон...",
  "genre": "без рубрики",
  "date": "31.12.2010 22:21",
  "url": "https://stihi.ru/2010/12/31/6734",
  "text": "Под звуки вальса и бокалов с соком (!) звон\nЛюбовь и Радость лёгкою походкой\nПриходят к добрым людям, в светлый дом,\nПо всей России – меж Калининградом и Находкой.\n\nКто им позволит в доме балом управлять,\nТого счастливее не сыщешь в мире!\nПро то, друзья, не стоит забывать,\nДа будет так, на всей Земле отныне!\n\nПусть Радость сердце наполняет,\nМелодия Любви в ушах звенит!\nМогучий Случай все желанья исполняет,\nПусть в мире лишь Добро царит!\n\nВсё это нам подарит Новый год,\nДрузья мои! Его встречайте…\n\n31/12/2010\n\nP.S. Happy New Year, you are welcome!"
 },
 {
  "id": "2010_12_22_4904",
  "title": "Начало нового мира",
  "genre": "философская лирика",
  "date": "22.12.2010 15:07",
  "url": "https://stihi.ru/2010/12/22/4904",
  "text": "Ну вот… Окончено то время,\nКогда жрецы «учили» нас!\nОковы рабства, страхов бремя\nМир скоро сбросит… Близок час!\n\nУстал народ от «пирамиды»!\nЗвенеть цепями, лицемерить,\nБояться всех, терпеть обиды.\nОн хочет Жить, Любить и Верить!\n\nВ агонии система бьётся,\nСебя пытается спасти…\nНапрасно это! Лишь смеётся\nМалыш… Что ведает пути.\n\nМир новый, сказочный грядёт!\nЕго дыхание уж слышно…\n\n22/12/2010"
 },
 {
  "id": "2010_12_14_6695",
  "title": "Объективная истина и беседа по душам",
  "genre": "эссе и статьи",
  "date": "14.12.2010 18:39",
  "url": "https://stihi.ru/2010/12/14/6695",
  "text": "Объективная истина? Добро, зло? Есть истинные вещи, а есть мнимые? Может оно и так… Но как же быть с теми людьми, которые заблуждаются… Или, по крайней мере, нам кажется, что они заблуждаются? С теми, которые не знают «объективных истин», живут в своих реалиях… Для них важны, очень важны их собственные установки, собственные мерила. В их мире те, явно необъективные вещи, вполне объективны. И утрату связи с ними или их критику такие люди воспринимают всерьёз, весьма трагично. Как быть с такими людьми? Поступать с ними, руководствуясь \"объективностью\"? Показывать несостоятельность их домыслов? Служить \"правде\" любой ценой???\nА в чём, собственно, Правда, Объективность? Ведь мы (повторяя И.Канта) лишь руководствуемся представлениями о ней… На своих собственных ощущениях оцениваем её «правдивость» и степень наших собственных заблуждений. И это очень важный аспект – помнить, что мы тоже можем заблуждаться, не переть сломя голову на осквернителя «правды»…\nОсновной принцип, видимо, и состоит в том, чтоб сохранять простое человеческое уважение к другому, пусть и несогласного в чём-то с тобой. Понимать, что он Человек… А по тому, он волен заблуждаться и ошибаться, ибо переживая, осмысливая собственные заблуждения, Человек приближается к Объективности, к Правде!\nПытаться понять другого и вместе с ним пройти тот путь от неведения, непонимания к Правде-Истине – вот, пожалуй, единственный здравый и обоснованный принцип истинной беседы по Душам.\n\n09/12/2010"
 },
 {
  "id": "2010_12_12_5791",
  "title": "Моему дяде",
  "genre": "философская лирика",
  "date": "12.12.2010 16:12",
  "url": "https://stihi.ru/2010/12/12/5791",
  "text": "Конечно, ты во многом прав…\nНа мир разумно смотришь, мыслишь…\nТяжёлый путь себе избрав,\nЖивёшь уныло как-то… Дышишь…\nПростишь неопытность мою,\nСлова и мысли – убеждён!\nТо, что сейчас тебе пою,\nБеседой нашей вдохновлён.\n\nПусть одолеет моя песнь\nВсе роли, маски и преграды!\nРазгонит море страхов, тень,\nТебе лишь принесёт награду,\nУверенности, счастья, сил,\nЛюбви энергию живую!\nВ себе, чтоб веру воскресил\nК Добру и Свету, лишь хочу я.\n\nТы говоришь, что в этом мире\nУчитель каждый, ученик…\nПрости, давай посмотрим шире,\nНе понимать я не привык!\nМир каждого есть рай и ад,\nКоторые мы строим сами:\nИз Света, Тьмы, надежд, преград,\nЧто в сердце и в уме, что с нами.\n\nИ верю я, что каждый может\nТворцом своей Вселенной стать!\nХоть обстоятельства тревожат,\nСпособны мы во снах летать!\nЧтоб изменился мир вокруг,\nВ себе нам нужно разобраться.\nВсё переменится… И вдруг\nНачнёт хорошее случаться.\n\nЯ знаю, «каторгу» свою,\nОднажды сможешь одолеть!\nОчутишься в родном краю,\nЗахочешь ты, крича, воспеть\nГимн радостный, победный,\nКрасотам мира и Любви…\nИ будет Жизнь безбедна…\nЛишь мир в себе – твори… Живи!\n\n12/12/2010"
 },
 {
  "id": "2010_12_09_4111",
  "title": "Незримая беседа",
  "genre": "любовная лирика",
  "date": "09.12.2010 13:48",
  "url": "https://stihi.ru/2010/12/09/4111",
  "text": "Вот строчки я верстаю и с лёгкостью пишу!\nТебе сказать, родная, я что-то вновь хочу!\n\nО том, что происходит, давай поговорим,\nНезримую беседу сегодня сотворим.\n\nЛегко и простодушно на сердце у меня!\nИ очень всё воздушно… Прекрасно жить любя!\n\nКому же в этом мире любовь я подарю?\nВедь думал, что с тобою я к Свету воспарю!\n\nТебе писал я строки… Ведь помнишь это ты!\nПотом, разрушив планы, развеялись мечты…\n\nУж было я поверил, что грезилось то мне\nНапрасно, и нелепо взывал в стихах к тебе!\n\nУж было налетела тяжёлая тоска,\nИ вроде б, завладела Душою на века.\n\nНо светлое то в сердце, что жило  у меня,\nОсталось непослушным тоске той, всё ж любя!\n\nЛюбовь и Радость в мире всего всегда сильней,\nОсветят путь для Жизни счастливейших людей!\n\nВ той силе убедился, тебя я повстречав!\nНи капли не жалею, часов своих отдав!\n\nЧасов, что я томился, надеялся и ждал,\nИ тех, что я закрылся, печалиться вдруг стал.\n\nВсё это преходяще… Возможно, будет вновь…\nЛишь вечна, Жизнь творяща, бессмертная Любовь!\n\nВот, что хотел сказать я в стихах на этот раз\nТебе, моя родная… Уж скоро… Близок час!\n\nКогда падут преграды всех страхов и обид,\nКогда мы будем рядом…Любовь нас одарит!\n\nС тобою будем дружны, добры и веселы!\nА помыслы созвучны, прекрасны и светлы!\n\n4 декабря 2010 г."
 },
 {
  "id": "2010_12_07_3418",
  "title": "Решения сердца",
  "genre": "любовная лирика",
  "date": "07.12.2010 12:05",
  "url": "https://stihi.ru/2010/12/07/3418",
  "text": "Тебя почти предал я,\nВ свои мысли допустив\nСомнений дух, незнанья,\nСмиренье огласив.\nЯ думал, уж напрасно\nНадеяться и ждать…\nИ сделалось ужасно,\nНаложена печать\nЗапретов и страданий.\nИ грустно от того,\nЧто ярких ожиданий,\nВзрастания мечтаний –\nНе видно ничего!\nНа сердце налетела\nБезумная тоска,\nИ сердце охладело,\nВозможно, на века…\n\nНо ту тоску, неглядя,\nЯ всё же разгоню,\nТебя, моя родная,\nНи в чём я не виню!\n\nИллюзией ль то было\nИль обманом,\nТо страстью обуяло\nОгненным вулканом.\nБыть может, так…\nЯ всё ж решил и впредь\nМечтам своим и чувствам верить!\nОни ж пробив сомнений твердь,\nСпешат к себе наш мир примерить!\n\nЧто будет с нами? Знает Бог!\nЕму лишь ведомы судьбины.\nБыть может, на перепутии дорог,\nСтоят Души Единой половины!\nПойдут они одним путём\nИль разойтись решат?\nПрошу лишь об одном,\nПусть сильно не спешат!\nРешение принять\nПусть сердце им поможет!\nЛюбовь ведь всю объять\nЛишь только сердце может!\n\n18 ноября 2010 г."
 },
 {
  "id": "2010_12_07_3383",
  "title": "Духу сомнений",
  "genre": "любовная лирика",
  "date": "07.12.2010 12:02",
  "url": "https://stihi.ru/2010/12/07/3383",
  "text": "Оставь меня ты, Дух сомнений\nИ необузданных страстей!\nХочу без прочих возражений\nЛюбить её и жить полней!\nХочу, чтобы весной прекрасной,\nПо парку нашему идя,\nМы радовались бы неге ясной,\nДруг друга всё сильней любя!\n\n13 ноября 2010 г."
 },
 {
  "id": "2010_12_04_8168",
  "title": "Разлука",
  "genre": "любовная лирика",
  "date": "04.12.2010 20:57",
  "url": "https://stihi.ru/2010/12/04/8168",
  "text": "Любимая уехала в Москву…\nА я брожу по Северной Пальмире,\nСтихами разгоняю я тоску,\nПою о той, которую люблю,\nЕдинственной во всём огромном мире!\nГрустит Душа, но эта грусть приятна,\nПоскольку погружён я в светлые мечты,\nЯ думаю о нас… Пусть то невероятно,\nЯ твёрдо убеждён, что это слышишь ты!\nБлагодарю тебя за то, что существуешь,\nИ сердце наполняешь ласковым огнём,\nЛюбимая, о как же ты меня волнуешь,\nИ скоро, верю, будем мы вдвоём!\nПройдёт разлуки миг, преграды расстоянья\nСумеем мы с тобою одолеть.\nПока же, чувствуя приятность состоянья,\nЗакрыв глаза, давай цветные сны смотреть!\n\n2 ноября 2010 г."
 },
 {
  "id": "2010_11_24_4654",
  "title": "France",
  "genre": "философская лирика",
  "date": "24.11.2010 14:54",
  "url": "https://stihi.ru/2010/11/24/4654",
  "text": "О, Франция, опять меня ты манишь,\nУж в третий иль четвёртый раз!\nНе знаю, вновь ли ты обманешь,\nИль для меня настал твой час.\n\nСудьбу нам трудно угадать,\nКогда идём к заветной цели.\nЧего от будущего ждать?\nИюльский зной или метели?\n\nО том, куда же нам идти,\nМы сами выбор можем сделать!\nА направленье нашего\tПути\nВсегда возможно переделать!\n\nХочу лишь об одном сказать\nТому, кто ведает Судьбою:\nЯ буду Сердцем выбирать!\nА не “разумной” Головою…\n\n24 ноября 2010 г."
 },
 {
  "id": "2010_11_24_4622",
  "title": "Кто я?",
  "genre": "философская лирика",
  "date": "24.11.2010 14:50",
  "url": "https://stihi.ru/2010/11/24/4622",
  "text": "Ведь сам хочу понять, кто я,\nИ кем являюсь в этом мире,\nИ кто же Вы, мои друзья,\nЧто сердцу близки и так милы.\n\nЗачем приходим в этот Свет,\nИ что нам суждено исполнить,\nСтремится вспомнить Человек,\nНыряя в думы с головою.\n\nГде, Счастье, ждёшь ты нас,\nИ для чего живём мы?\nХотим узнать всё враз,\nИ не взирать на мнений сонмы.\n\nИ пусть опять мне одиноко,\nИ грусть на сердце налетела,\nНо наша Жизнь – не однобока,\nДуша так наша захотела…\n\n12 августа, 16 октября 2010 г."
 },
 {
  "id": "2010_11_24_4174",
  "title": "Любимой",
  "genre": "любовная лирика",
  "date": "24.11.2010 13:53",
  "url": "https://stihi.ru/2010/11/24/4174",
  "text": "Любимая! Коль это, правда, так,\nЧто нам суждено любить друг друга,\nПусть будем мы свободны в той Любви!\nИ пусть не кружится над нами злая вьюга\nРасчёта, мелких мыслей и хвальбы!\nДа будет светлым, радостным наш каждый день!\nИ неге сладостной мы будем предаваться,\nИ солнышко согреет Душу и разгонит тень\nСомнений, и печаль не будет в сердце оставаться!\nА наши Души будут лишь парить,\nВ пространстве Света и Любви!\n«Как это радостно тебя любить!»\nОднажды прокричим друг другу мы…\n\n26 октября 2010 г."
 },
 {
  "id": "2010_11_21_5042",
  "title": "Читайте вслух стихи и прозу...",
  "genre": "любовная лирика",
  "date": "21.11.2010 15:03",
  "url": "https://stihi.ru/2010/11/21/5042",
  "text": "Читайте вслух стихи и прозу,\nЛюбите Жизнь, друзья мои…\nВдыхать и чувствовать, как розу,\nЕё ведь надо в наши дни!\nА дни-то те у нас прекрасны:\nМы молоды и сил полны!\nИ хоть порою столь ужасно\nРисует кто-то наши дни.\nНе верьте им,\nОни напрасно лукаво лгут.\nИм невдомёк, что\nЖизнь-то наша – вся изящна!\nМы будем жить всегда в Любви!\n\n7/09, 12/12/10"
 },
 {
  "id": "2010_11_20_8313",
  "title": "Дзюдо",
  "genre": "философская лирика",
  "date": "20.11.2010 22:13",
  "url": "https://stihi.ru/2010/11/20/8313",
  "text": "Жизнь каждого из нас есть путь,\nПуть самопознанья, совершенства духа.\nИ нас склоняют обстоятельства свернуть,\nПринять роль жертвы, шепчут, мол: «Непруха!\nТы маленький лишь человек!\nДругим сей праздник уготовлен!\nВлачи свой жалкий век!\nОставь надежду! Будь покорен!»\n\nИ трудно нам порой на то не согласиться,\nНо знаем твёрдо, помним мы одно,\nВсё может в мире сделаться, случиться,\nНо только ты будь с верой заодно!\nЛюбую сложность в пользу обращай!\nБорись, пока твоё не вышло время!\nСтремись к победе, чётко знай:\nПомочь другому – то не бремя!\n\nБорьбы из детства мудрые заветы\nНам помогают в этом мире жить!\nИдя свой путь, отбросив все наветы,\nМечту свою стремимся воплотить!\nТебя благодарю, Японский Спорт,\nЧто с Духом Русским так славно ладишь,\nИ знаем точно, наперёд,\nТы удаль русскую ещё прославишь!\n\n4-8 ноября 2010 г."
 },
 {
  "id": "2010_11_20_8290",
  "title": "Родителям",
  "genre": "любовная лирика",
  "date": "20.11.2010 22:10",
  "url": "https://stihi.ru/2010/11/20/8290",
  "text": "*посвящёно дню 30-летия их свадьбы*\n\nПусть будет то для Вас сюрпризом,\nЧто сын решил Вам написать.\nБыть может, вдохновлён капризом\nПроказничать, стишки верстать.\nВозможно, как и наш Арсений,\nХочу чуть-чуть я пошалить,\nПробить стену предубеждений,\nНемного Вас повеселить!\n\nСтихи нужны, чтобы понять,\nЧто чувствуешь, о чём мечтаешь.\nНо тут нетрудно разгадать,\nО чём, мой разум, помышляешь!\nСегодня день прекрасной Свадьбы\nРодных и близких мне людей,\nИ тридцать лет минуло как бы\nС того дня, в Городе Дождей.\n\nНо те года, я знаю точно,\nНичто в сердцах не смогут изменить.\nРешенья Юности – бессрочны!\nОни способны чудеса творить!\nИ Ваш пример достоен повторенья,\nНикто не сможет в том Вас укорить,\nИ мы, отбросив все сомненья,\nНе перестаём Вас двух любить!\n\n3 ноября 2010 г."
 },
 {
  "id": "2010_11_20_8243",
  "title": "Муха",
  "genre": "философская лирика",
  "date": "20.11.2010 22:04",
  "url": "https://stihi.ru/2010/11/20/8243",
  "text": "Муха в комнате летает,\nБьётся в стены и в стекло,\nИ совсем не замечает\nМной открытое окно.\n\nКружит, мечется, бедняжка,\nХочет путь свой разыскать!\nТы лети-лети, милашка!\nПродолжай его искать!\n\nВедь, кто ищет, тот находит, –\nТак предание гласит.\nА познавший путь – восходит,\nВ новый мир себя стремит!\n\nВ царство Истинной Свободы,\nЦарство Вечного Добра!\nА к чему же нам невзгоды,\nКак для мухи та тюрьма?\n\nДля того, чтобы познали,\nКак преграды одолеть,\nПовзрослели, мудрей стали,\nНаучились не стареть!\n\nВедь для вечной жизни надо\nБыть красивым, молодым!\nЮной нежности отраду\nВ своём сердце сохраним!\n______________________\n\nР.S.\nПока писал я строки эти,\nЗнакомой нашей повезло:\nОна нашла дорогу к дому,\nБлагополучно вылетев в окно! ;\n\n18 октября 2010 г."
 },
 {
  "id": "2010_11_20_8096",
  "title": "Зачем нужны стихи?",
  "genre": "гражданская лирика",
  "date": "20.11.2010 21:49",
  "url": "https://stihi.ru/2010/11/20/8096",
  "text": "Пишу стихи не для хвальбы,\nНе чтобы вызвать кривотолки,\nНе чтобы, сидя у ольхи,\nИх петь могли степные волки.\n\nПознать себя! Язык Любви!\nИ чувства выразить словами!\nБыть может, обсудить с друзьями\nТе рифмы звонкие мои…\n\nДабы избавить от тоски\nИ сделать ярче мир? Быть может…\nИ кто-то, прочивав стихи,\nВозможно, что-то подъитожит.\n\nНо я пишу, о том не зная,\nПишу…Забаву усмиряя!\n\n15 октября 2010 г."
 },
 {
  "id": "2010_11_20_6630",
  "title": "Клеветникам и подстрекателям",
  "genre": "гражданская лирика",
  "date": "20.11.2010 19:05",
  "url": "https://stihi.ru/2010/11/20/6630",
  "text": "Напрасно вы желаете нам зла!\nВне Блага эти устремленья!\nСознанье Ваше обуяла мгла,\nИ страх внушает разные со-мненья!\nХотите всем владеть и всеми править?\nНе глупо ль это? Есть один момент…\nКому себя готовы вы оставить?\nВедь вы – лишь только инструмент!\nТех тёмных сил, что страхом управляют,\nПорабощая дух и плоть людей,\nИ Жизнь в игру умело обращают,\nОбуревая множеством страстей!\nЧего они вам обещают?\nЛюбимых счастье и друзей?\nРациональность лишь внушают,\nОтказ от чувств  и роль вождей!\nО, эта роль… Готовы для неё вы\nСлужить и лгать, порочить всё вокруг…\nИ тут попались вы в оковы,\nОбид и мелких устремлений круг.\nОрудия лишь Вы! Но злая шутка есть:\nТелегу, что устаревает,\nЖдёт участь, неприглядная весьма, –\nНа свалку вмиг её бросают\nИ забывают, раз и навсегда.\n\nВедь люди ж вы, – а  они, как боги!\nМечтать хотят, любить, творить!\nИ не нужны нам те пороки,\nИ страхом на сердце давить!\nТак что, друзья! Давайте быть добрее!\nИ чаще слушать стук своих сердец!\nДабы с каждым мигом быть смелее,\nА не превращаться из людей в овец!\n\n9 октября 2010 г."
 }
];
